/* 令和元年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r01.committeeSessions.push(...[{"id":"r01-20190701-7","meetingId":"r01-cm07","date":"2019年7月1日","dateIso":"2019-07-01","committee":"厚生委員会","time":"午前１０時００分～午後 ２時１８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を65件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第４８号議案 品川区介護保険制度に関する条例の一部を改正する条例","agenda":"第４８号議案 品川区介護保険制度に関する条例の一部を改正する条例","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"今ご説明にあったように、消費税の増税に伴って省令および政令によりということだったと思うのです。これは、各自治体、同じ割合で同じ時期にという理解でよろしいのでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"ただし、もともと国が示している介護保険料は９段階設定ですが、各自治体が状況に応じて、それ以上に細かく設定することが可能になっておりまして、多くの自治体が国条例と若干異なる、品川区もそうですけれども、冒頭申し上げた１４段階設定になりまして。","voiceIndex":5,"id":"exchange-001"},{"speaker":"あべ委員","kind":"確認","question":"これも確認なのですけれども、こちらは本人が何かをするということは特にない。要は、申請しないと減額が何とかいうことではなくて、これは自動的に額が定められて、それを支払うということ、漏れはないということでよろしいのですか。","respondent":"寺嶋高齢者福祉課長","answer":"結論から申し上げますと、そのとおりです。漏れはございません。７月に本算定がありまして、そのときに新しい率を掛けたものを通知としてお送りして、そこから新しい率での徴収が始まって、年間を通して基準どおりの額になるような調整をするです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"渡辺委員","kind":"確認","question":"すみません。現況確認だけ。今回の区設定段階第１から第４の段階、対象者はどれぐらいの人数かと、割合だけ教えてください。","respondent":"寺嶋高齢者福祉課長","answer":"対象者は、今のところ想定ですが、１から４段階までが約２万７,０００人となっておりまして、全体、第１号被保険者からすると約３割程度というふうに推計しております。","voiceIndex":10,"id":"exchange-003"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"この対象者というのが２万７,０００人で大体３割ということだったのですけれども、減額されるということですが、ここに必要な額はどれぐらいになるでしょうか。国庫支出金の増額という形になるのでしょうか。国庫支出金の割合が２１.５％になっていると思うのですけれども、このパーセンテージが変わってくるのかどうなのかというのを、ちょっとお伺いしたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"影響額ということになりますけれども、すみません、本日の説明では割愛させていただきましたけれども、今現在、実は消費税が８％に上がったときから、段階の低い、いわゆる低所得者対策ということで、この保険料軽減制度というのは既に行われておりまして、今は第１。","voiceIndex":13,"id":"exchange-004"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"第４段階までの人は全世帯が非課税ですので、税金のかからない世帯なわけですから、もっと低廉であるべきだというふうには思いますけれども、今回の引き下げるというところは当然だと思っていますので賛成なのですが、その財源が消費税ということで、やはり低所得者に最も重くのしかかる逆進性の強い税金ですので、社会保障の財源としてはふさわしくないということを、私たち共産党は指摘をし続けています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-005"}]},{"id":"topic-02","title":"第４９号議案 品川区立高齢者多世代交流支援施設条例の一部を改正する条例","agenda":"第４９号議案 品川区立高齢者多世代交流支援施設条例の一部を改正する条例","exchanges":[{"speaker":"若林委員","kind":"質問・要望","question":"今回、多世代交流ゆうゆうプラザの開設ということで、さっきの特に１階部分ですか。","respondent":"宮尾高齢者地域支援課長","answer":"ただいまご質問いただきました、まずスペースのとり方に対する考え方ですが、地域交流スペースは、１階の入り口を入ってすぐのところに広目のスペースをとらせていただきました。","voiceIndex":27,"id":"exchange-006"},{"speaker":"渡部委員","kind":"意見","question":"スタジオというのはカラオケ室かということがまず１点。それと、今回これ、示していただいて、もともとシルバーセンターだったら目的外使用というのはわかるのだけれど、これが例えば多世代交流支援施設となると、すごくいろいろな方が使えていく中での目的外というのは、どうなったら目的外。要は、高齢者が使う分には目的使用という考え方。その辺ちょっと考え方を。","respondent":"宮尾高齢者地域支援課長","answer":"スタジオは、今回１階と２階の２カ所用意するのですが、そのどちらにもカラオケ機はご用意するつもりで、準備を進めさせていただいているところです。","voiceIndex":30,"id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"すみません。代替施設というのではないのですけれども、何か今までのサービスをどこかほかで同様な形で受けられるというようなご案内をしているのかどうかということを教えてください。そこまでです。","respondent":"宮尾高齢者地域支援課長","answer":"ただ、東品川シルバーセンターは今、週６日間入浴サービスを実施しているので、片方ずつといっても週３日にはなってしまうのですが、そこは４月に利用者を対象にした説明会を現地で開催させていただいて、説明させていただいたです。","voiceIndex":33,"id":"exchange-008"},{"speaker":"あべ委員","kind":"質問・要望","question":"確認なのですけれど、この浴室は男女交互に１日交代みたいな感じの運用なのでしょうか。それと、今シルバーセンターがゆうゆうも含めて１５館ぐらいあったかなと思うのですけれども、かなりそれぞれ老朽化していて、それぞれで更新の要望を多く聞いているのですけれども、今後どういう順番でやっていくのか。そういった全体の計画というのはあるのでしょうか。あれば教えていただきたい。","respondent":"宮尾高齢者地域支援課長","answer":"そういうふうに考えているところです。そちらは４月の利用者説明会でもご案内をさせていただいたところです。他のセンターの老朽化等に対する考え方ですが、まずはやはり施設の老朽度。こういったところがまず重要な要素になってこようかと思います。","voiceIndex":35,"id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"全体の更新に対する考え方はわかったのですけれど、具体的にどこをしていくというのは、それぞれ、次がここです、次がここですというような計画の立て方なのでしょうか。それとも具体的な館について、順番とかあるいはこのぐらいのスパンで何館やるというところまでの計画が多分あるのではないかと思うのですけれど、どうでしょう。","respondent":"宮尾高齢者地域支援課長","answer":"ですので、委員おっしゃられたような、本当でしたら長いスパンで全部きれいに計画を立てるというのが望ましいところではあるかと思うのですけれど、現段階では喫緊のところ、緊急性を重要視しながら進めさせていただいているです。","voiceIndex":37,"id":"exchange-010"},{"speaker":"石田（ち）副委員長","kind":"確認","question":"先ほどの目的外使用のところのお話もあったのですけれども、そうすると、今あるゆうゆうプラザのほうで目的外使用はどれぐらい、結構あるのか、そんなにないのか。そこら辺がどれぐらいの割合なのか伺いたいのと、基本的なところなのですけれど、高齢者クラブが利用する場合は目的外にはならない。そうなると、利用料は無料で使えるということでよかったのか、確認をお願いしたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"できた後の管理の方法ですが、これは明日ご報告する予定でおりますが、他のゆうゆうプラザと同様に指定管理者制度を導入させていただきたいと思っておりまして、こちら、明日、公募の関係のご報告をこの場でさせていただきたいというふうに思っているところです。","voiceIndex":41,"id":"exchange-011"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"目的外使用の限度額を上げるという理由に、このスタジオの広さがというふうにおっしゃられていたのですけれども、大体平米数というのはどれぐらいになっているのか。スタジオ(1)、スタジオ(2)等々、コミュニティ室等もわかれば、ちょっと教えていただきたいなと思うのですけれど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"今後の改修の考え方みたいなところにまでお話があったので、品川区の総合管理施設計画、ちょっと言葉が今不正確かもしれないのですけれど。何を言われるかというよりも、課としての考え方。シルバーセンター、ゆうゆうプラザの。ちょっと確認させていただきたい。","respondent":"宮尾高齢者地域支援課長","answer":"ただ、ちょっと先ほども触れましたけれども、建て替えをして、あまり延床面積が増えないという中で複合化ということを考えていきますと、もとあったシルバーセンターなりが複合化によって、逆に小さくなってしまうというようなことも想定としてあろうかと思いますので。","voiceIndex":48,"id":"exchange-013"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"賛成です。が、本来区民のための施設ですので、私たちはもっと低廉な利用料にすべきだというふうに思っていますという意見を述べて、賛成します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":55,"id":"exchange-014"}]},{"id":"topic-03","title":"第５０号議案 品川区社会福祉基金条例の一部を改正する条例","agenda":"第５０号議案 品川区社会福祉基金条例の一部を改正する条例","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"ご本人のご賛同を得ているということなので、あまりしつこくは言いませんけれども、基本的に品川区の事業としてやっている、全体として５４億円の事業の中の一部を寄附に充てるというのが、何と言ったらいいのでしょうか。寄附って、やはり今ある福祉に対して、さらにいいものにしてほしいという思いがあってやるわけです。そういう議論というのは、ありませんでしたか。","respondent":"築山障害者施策推進担当課長","answer":"ご寄附の方のお気持ちが入った施設であるということをお伝えするために、施設にプレートを掲げて、この施設が寄附で成り立っているということを残していきたいと考えているところです。","voiceIndex":62,"id":"exchange-015"},{"speaker":"あべ委員","kind":"意見","question":"長く残るものにという考え方も、それはそれで理解ができるところもあります。プレートという話もありましたけれども、やはりこういう思いがあって、この施設にそういう方々の気持ちが入っているということが、いろいろな形で伝わったり、それがまたつながって循環していくような何か工夫をしていっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-016"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"この障害児者総合支援施設に充てたということなのですけれども、この施設の建設は、国や都からもお金が入って建てられているものなのか、区だけの財源で建てたものなのかをちょっと伺いたいのと、５４億２,８００万４,４００円が建設経費で充当するということなのですけれども、もし国と都、区で建設費が出ているとすれば、品川区の負担の一部に使ったということなのか。","respondent":"築山障害者施策推進担当課長","answer":"こちらの施設につきましては、区の経費のみで建設されたものになっております。","voiceIndex":66,"id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"それで、その後も今おっしゃっていただいたような、長く多くの方に利用していただく障害者施設というものはあるはずなので、ここに全部ではないのですけれども、障害者とついた、障害者の部分に使ってくださいという意向の寄附金が全部使われてしまったというのは、どうしてなのかなということと、あと、これで、障害者の部分にという意向で寄せられた寄附金は、基金はなくなったという考えでいいでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"ただ、今回、障害児者総合支援施設のところに基金を充てさせていただいたのは、まず規模が大きいというところで、なかなか今後障害児者総合支援施設のような規模のものというのは難しいだろうということもあります。","voiceIndex":68,"id":"exchange-018"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"もうちょっとうまく分散させるというふうな考えもあってもよかったのではないかなと思ったので、伺ったのですけれども。そうすると、もう障害者用というか、障害者の部分に使ってほしいという基金は、全部ここで使い切った。その理由は、先ほど課長がご説明になったとおりということですか。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-019"},{"speaker":"若林委員","kind":"質問・要望","question":"表で３ページ、４ページにかけて、この高田右多子さんの基金については、「第５条の規定により処分した額を減じた額」と。ここだけこのとおりなのですけれど、この意味をひとつ教えていただきたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"第５条の規定につきましては、分割して使うことができるという旨を規定したものとなっております。先ほどの高田右多子障害者用社会福祉基金につきましては、こちらに該当するです。","voiceIndex":72,"id":"exchange-020"},{"speaker":"若林委員","kind":"質問・要望","question":"それは確認だけなので。指定管理の考え方とか。そこら辺を端的にで結構ですので、教えていただきたいと思います。今後のそこら辺のスキームというのは、スキームのある施設とない施設という事業があるのだなという、そこら辺のちょっとご説明をいただきたいなと。今回は、本当になかった。本当にというか、探したけれどなかったのですということだとは思うのですけれど、そこら辺の確認も含めて、２つ。","respondent":"築山障害者施策推進担当課長","answer":"基金の経緯についてですが、こちらの施設、平成２９年に着工している施設なのですが、もうこの段階でこちらの基金のほうを使わせていただこうというところで考えておりまして、寄贈者の方へご連絡をしてきております。","voiceIndex":75,"id":"exchange-021"},{"speaker":"渡部委員","kind":"意見","question":"ちょっと一言申し上げますと、区民の皆様ないし障害福祉のためにお金を使ってくださいというので、これだけの施設は確かにできることはめったにないと思います。その金額の多寡というのは、皆様の気持ちに全く関係ないので、逆にこの施設１カ所に集中できたことが私はよかったと思っていますということを述べさせていただいて、賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-022"}]},{"id":"topic-04","title":"第５１号議案 品川区立心身障害者福祉会館条例の一部を改正する条例","agenda":"第５１号議案 品川区立心身障害者福祉会館条例の一部を改正する条例","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"つまり１０月１日から、どんな事業が始まって、何が変わるかというのを、もう少しストレートに教えていただけると大変ありがたいです。","respondent":"松山障害者福祉課長","answer":"新規事業といたしましては、障害児の計画相談を会館で新たに行うために、条例の一部改正を行わせていただいたものです。","voiceIndex":89,"id":"exchange-023"},{"speaker":"あべ委員","kind":"質問","question":"それによって、例えば体制が変わるとか人員が変わるとか、そういったこともあれば、あわせて教えてください。","respondent":"松山障害者福祉課長","answer":"人員のところですけれども、会館では障害者の相談支援事業を既に行っておりますが、そちらに加えまして１名の障害児の相談支援専門員を配置するということで、計画相談に対応していくというものです。","voiceIndex":91,"id":"exchange-024"},{"speaker":"あべ委員","kind":"質問","question":"ですので、今回の改正というのが、条例としては会館条例を一部変えて、かつ現状追認の部分もちょっとあるのでしょうか。そのことも含めて、条例としてはそれなのですけれども、全体として、いつから、どんなふうに相談体制が変わっていくか。今、簡単にご説明いただくことは可能でしょうか。その中で、この会館の部分が、こう変わるので条例が変更されるのだという全体像が見えると、大変ありがたいです。","respondent":"松山障害者福祉課長","answer":"選定結果につきまして、あるいは今後の体制につきましては、決定次第また議会のほうで報告する予定です。今、自立支援協議会や相談支援部会を含めて検討中の案件ですので、まだ必ずこうするというものが決まっているわけではございません。","voiceIndex":93,"id":"exchange-025"},{"speaker":"あべ委員","kind":"質問","question":"そうすると、１０月１日からは、今度心身障害者の福祉施設とそれから総合支援施設で、民間のほうはでき次第という形、それが計画相談で、一般相談はまた別で見直しが行われているというようなことでよろしいのでしょうか。そこら辺の全体も見直していって、それが例えば来春ぐらいからはすっきりとアナウンスできるというようなことなので、ちょっとそのスケジュール感も含めて教えてください。","respondent":"松山障害者福祉課長","answer":"確かに今検討中のものがありますので、はっきりわかりやすく皆様にお示ししたいということを考えております。そのために、現在相談支援部会で計画相談や一般的な相談、相談支援センターを含めた事業所のガイドブックというものの作成に具体的に取り組んでいるところです。","voiceIndex":95,"id":"exchange-026"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"今、相談の部分で、相談支援とか計画相談という言葉が、相談というだけでいろいろややこしい部分が本当にあるなというふうに思っているのですけれども、もう一回確認なのですけれど、身障者会館で障害児の指定特定相談事業として計画相談をやるということでいいのかというのをまず確認したいのと、先ほど人員配置、１名の専門員をということでしたけれども。","respondent":"松山障害者福祉課長","answer":"２点目も、相談員が大人の相談と子どもの相談と兼務するのかというご質問だったかと思いますが、障害児の専門の相談ということで、別の相談支援員を置くように考えているところです。","voiceIndex":100,"id":"exchange-027"},{"speaker":"あべ委員","kind":"質問","question":"これまでそうしていただいた。その中で、今後５年間サービスを維持・向上していくためには、やはり人の定着する運営を今後ともしていただかなければいけないと考えています。区としては、どういった条件の中でこの施設の方々、法人の方々がお仕事をされていて、それは将来的にも安定して働き続けたいと思えるような状況であるのか、そういう視点で把握したり調査されたりというのは、しているのでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"離職率も、ここの杜松に関しては規模が小さいので、１人入れかわるとパーセンテージが上がってしまいますから、ほかの施設と比べて突出して離職率が低いかと言われればそんなことはないのですけれども、この規模で十数％台を保っているというのは。","voiceIndex":116,"id":"exchange-028"},{"speaker":"あべ委員","kind":"質問・要望","question":"離職率十数％だと低いという、この業界自体がどうなんだというふうには思うのですけれども、いいサービスを提供しているということは、今は人的満足度が高いということだと思うのですけれども、今後もそれが維持できるように、やはり働く方の環境ということもぜひ区は関心を持っていただきたいと思います。最後要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-029"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"指定管理の継続のための議論とはいえども、先ほどあべ委員からもありましたけれど、しっかりやっていただいて、それを今後５年間さらに任せていくということになるわけですから、事業所のほうからも計画書だったり収支報告書は毎年出されているはずですので、頑張っている、しっかりやっている施設ですと言うのであれば、それをやはり見える形で。","respondent":"寺嶋高齢者福祉課長","answer":"規模ですけれども、先ほど申し上げたように、特養ホームは定員２９名ということでやっております。それから看護小規模のほうが、１８名定員になっております。","voiceIndex":120,"id":"exchange-030"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"あと専門職。やはり看護ですので、専門職がいるだろうという思いもあるのですけれども、介護士や看護師が１１名と３.４人で、看護師が３.４人ということなのですけれども、夜も配置されているという考えでいいのでしょうか。夜の配置は、介護士と看護師がどういう人員体制になっているのか、教えていただきたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"看護小規模多機能と小規模多機能の違いということですが、まさに今副委員長おっしゃったとおり、看護がついているとしか申し上げようがないですけれども、人員配置としては、もちろん看護師がいるということに尽きるのですが。","voiceIndex":122,"id":"exchange-031"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"わかりました。ほかの自治体からも国からも視察が来るということだったので、もうちょっと看護小規模多機能というのが、こうした工夫だったり、すごいんだよじゃないですけれど、そういう状況だということがわかる形で書かれているといいかなというふうに思います。８ページのところの3)一番上。施設全体で約５７０万円増額しているというのは、どういうことなのかというのをちょっと伺いたいのですが。","respondent":"寺嶋高齢者福祉課長","answer":"地域包括ケアを推進する観点があるというこの表現は、その後に続く地域住民等々と顔の見える関係ということで、そもそも地域包括ケアの考え方というのが、多職種も含めて地域のいろいろな役割を持った方たちが一つの母体として、例えば利用者にしてみれば。","voiceIndex":124,"id":"exchange-032"}]},{"id":"topic-05","title":"令和元年陳情第１２号 品川区の相談支援制度","agenda":"令和元年陳情第１２号 品川区の相談支援制度","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"この陳情はすごくわかりやすくて、誰が何に困っていて、どういうことがあって、どうしてほしいのかという、すごくよくわかるのです。こういうわかりやすさで、ぜひご説明をしていただきたいなと思います。多分、障害福祉課の部屋にも「センター」とかいって大きい看板が掲げられているほどでもなかったかなというふうに思います。すみません。それまでは、どうするのかということをどう考えますか。","respondent":"松山障害者福祉課長","answer":"加えて、障害者相談支援センターの相談員がきちんとそれを提示しながら、皆さんに同じ説明ができるよう努めてまいりたいと考えております。したがいまして、事業者のガイドブックにつきましては、９月を目指して早急に今つくっているところです。","voiceIndex":140,"id":"exchange-033"},{"speaker":"あべ委員","kind":"意見","question":"９月にそのガイドブックができるということは、少し製作のタイムラグもあると思いますので、中身については、本ができるまではということだけではなくて、例えばホームページなり、あるいはもうちょっと簡易なものでも、できるだけ早くお示しをすることがあったほうがいいのかなというふうに思いますので、それもご検討ください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":142,"id":"exchange-034"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"これはなぜなのかということをひとつ伺いたいのと、私も支援を受けるまでの流れというのが、品川の障害者のしおりってすごくわかりづらいなというのがあると思っているのです。そういった事業所別にとかいうのではなくて、区の障害者が支援を受けるまでの流れというのをわかりやすく示すべきではないかなと。それと、なぜ要望してきているのに開催ができないのかというのをちょっと伺いたいのですけれども。","respondent":"松山障害者福祉課長","answer":"１点目のご要望についてですけれども、障害者福祉課としてはご意見は承っておりまして、こちらは今現在検討していますので、決定後、周知いたしますということでお返事をさせていただいておりました。","voiceIndex":144,"id":"exchange-035"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"説明会については要望を受けていて、今検討中ということですけれども、「現在検討しております」というものではなくてということも書かれていますが、やはり相談支援制度というのは、先ほども言ったのですけれど、支援につなげる。それの説明をしてほしい。なぜすぐに開催というふうにならないのかということをお聞かせください。","respondent":"松山障害者福祉課長","answer":"その中でも、相談支援の基本的な業務の範囲ですとか内容ですとか、そういったもので相談員が統一した説明ができ、相談支援事業の標準化、質の向上を目指して作成しています。","voiceIndex":146,"id":"exchange-036"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"わかりやすくしていくというところでの努力はされているのだなというのはわかります。統一して誰もがわかるものをというのはすごくわかるのですけれど、そうすると、やはり相談支援。そうしたら、その１３団体も含めてですけれども、相談支援についての説明会というのは当事者に向けてやるというお考えはあるのでしょうか。","respondent":"松山障害者福祉課長","answer":"説明会というよりは、やはりお困り事の相談は、相談支援センターで相談員にまずご相談を受けて、きちんとそこで受けとめ、必要なサービスにつなぐというのが相談の大きな目的ですので、まずそれを第一に重点的に考え、説明会よりは、私どもは丁寧に。","voiceIndex":148,"id":"exchange-037"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"わかりました。そうすると、区というよりは相談支援員のスキルアップではないですけれど、そういったところに。そういうところですごくお困りなので、統一したものをというのはいいのですけれど、できるまでというのは、それまでお待ちくださいというところなのですか。そして、相談員のスキルアップについてはどのように考えているのかというのをお聞かせください。","respondent":"松山障害者福祉課長","answer":"相談員の説明のスキルアップにつきましては、連絡会等を通じて周知を図ってまいります。人材育成のスキルアップにつきましては、福祉カレッジ等々の外部研修も含めまして、統一した、いわゆる個人の感性に頼らない相談のスキルの育成に力を入れていきたいと考えています。","voiceIndex":150,"id":"exchange-038"},{"speaker":"あべ委員","kind":"質問","question":"ちょっと今のやりとりを伺いながら感じたのですけれども、説明会という形をとるかどうかは別として、ガイドブックをつくる前に、当事者の方々の質問を受ける場というのはあったほうがいいと思うのです。それは、単に質問に答えるのが目的ではなくて、今、誰が、どのようなことがわからないのか。というのは、皆さんは制度を熟知されているわけです。もし、お考えがあったら。","respondent":"松山障害者福祉課長","answer":"ガイドブックの作成につきましても、案の段階で、９月の自立支援協議会で諮らせていただくという予定です。自立支援協議会の方には当事者の方もいらっしゃいますので、さまざまなお声を聞きながら、わかりやすい形で進めていきたいと考えています。","voiceIndex":153,"id":"exchange-039"},{"speaker":"あべ委員","kind":"質問・要望","question":"自立支援協議会の資料、前回も直前の夜中にお送りされていたかと思うのですけれど、あれでは当日までに読み込みができなくて、意見が言えないというお声を何人もの方々からいただきました。そこはご配慮ください。これは要望でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":155,"id":"exchange-040"},{"speaker":"若林委員","kind":"質問・要望","question":"この内容、とてもよくわかるというか、何で開催をするように求めるのかというのが、人間の感情としてすごく理解できる。要するに、「一度も説明を受けたことはありません」とか。これ、事実か事実でないかとそういうことではなくて、会の主張として、認識として。私でもそう思う。今ガイドブック等のこまごましたご質問を聞いたので、そこら辺に対する区の認識だけ、ちょっと最後お聞かせ願います。","respondent":"松山障害者福祉課長","answer":"確かにこの陳情の方のご指摘のように、ちょっとわかりにくさというのは、もちろんわかるところではありますけれども、今、若林委員のご指摘のとおり、どの相談支援センターに行っても、どの相談員に聞いても、同じ体制で同じことが説明できるというところが。","voiceIndex":157,"id":"exchange-041"},{"speaker":"渡部委員","kind":"意見","question":"だけれど、そのご家庭それぞれの問題点というのは違うわけだから、全てが全て同じ相談で来るわけはなくて、必ず個別対応しなければならないというのが、この障害福祉というところなのかなというのはずっと僕は思っていた中で、今回はこれに限らずさまざまな問題が挙がっているときに、会としてですとか、それぞれ障害というのがいろいろある中で、１３団体というお話もされていたのだけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":161,"id":"exchange-042"},{"speaker":"渡辺委員","kind":"意見","question":"結論を出す。結論は不採択ということで、今も議論があったように、課題のところは十分まず行政が把握されている点。この件だけでなくです。キーワードである、わかりやすさという何か方法論のところ。これもやはりわけがあっての、理由があってのことというふうに解釈して、これは陳情者にしても、思いは、方向性は十分担保されているという思いから不採択かと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":162,"id":"exchange-043"},{"speaker":"若林委員","kind":"質問・要望","question":"こういう会に入っている方、ほかの団体の方、入っておられない方、できれば全ての障害児者の方のお気持ちを区にわかってもらって、それに沿って寄り添う形で、どんな形であれ説明会云々ということはともかく、支援できる、支えていける、そういう品川区をつくっていただきたいなという思いで、不採択で結構だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":163,"id":"exchange-044"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"結論を出す、で、採択を主張したいと思います。やはり会の皆さんがわからない、説明してほしい。そういうふうにおっしゃっているわけで、先ほども１団体だけにというよりは、１３団体ありますしということもおっしゃっていましたけれども、やはりそうした一つ一つ丁寧に応えていかなければいけないのが障害者分野なのではないかなと私は思いますし、半年以上前から要望しているのに応えてもらえていない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-045"},{"speaker":"あべ委員","kind":"質問・要望","question":"あるいは、もうボールは何回も来ているわけですから、何か９月までとかいうことではない打ち返しがあったほうが、新しい仕組みへの導入がやはりスムーズになるのではないかと考えています。ですので、ここでは陳情としては説明会と限定されて要望されておりますけれども、説明会という形でなくても、何らかのアクション、リアクションをしていただきたいなというふうに思います。趣旨採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":167,"id":"exchange-046"}]},{"id":"topic-06","title":"令和元年陳情第２０号 一人暮らし高齢者の命を守るために入浴設備のあるシルバーセンターの整備を求める陳情","agenda":"令和元年陳情第２０号 一人暮らし高齢者の命を守るために入浴設備のあるシルバーセンターの整備を求める陳情","exchanges":[{"speaker":"西村委員","kind":"質問","question":"２点伺います。東京２３区の異常死の内、入浴中は１,４７８件（平成２９年）とありますが、品川区内の人数ですとか現状把握なさっている数値がありましたら、教えてください。２点目が、高齢化率の高い八潮ということですが、こちらもあわせまして、高齢化率の人口把握をなさっていれば、教えてください。","respondent":"宮尾高齢者地域支援課長","answer":"すみません。地区別の高齢化率ということで、品川区全体。こちらは２０１７年４月１日現在ですが、区全体の高齢化率が２１.０％に対しまして、八潮地区が３２.７％ということで、高齢化率が高いということは認識しています。","voiceIndex":178,"id":"exchange-047"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"シルバーセンターをつくって、そこに入浴設備をつけてくださいという陳情ですけれども、６０代以上の健康づくり、仲間づくり、生きがいづくりで、シルバーセンターがつくられる。そういう目的でつくられているということでしたので、この八潮地域の高齢化率から見ても、そしてこうした陳情にもある現状から見ても、八潮地域にシルバーセンターというものが必要だという区の認識はあるのでしょうか。","respondent":"宮尾高齢者地域支援課長","answer":"シルバーセンターの設置目的というのが、仲間づくり、健康づくり、生きがいづくりということで、シルバーセンターという看板をそのまま冠した施設というのは地区内にはございませんが、先ほどご説明させていただきましたとおり、地域センター内の敬老室。","voiceIndex":181,"id":"exchange-048"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、八潮地域では、シルバーセンターではなくて他の施設等々があるから、そこで代替がきくだろうというのが、今の区の八潮地域への高齢化に対しての認識になるのか。そこを伺いたいです。シルバーセンター、いきいきセンター、ゆうゆうプラザ合わせて１６カ所区内にありますけれども、その内お風呂がついているのは１０カ所です。ついている理由を伺いたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"八潮地区内には、確か昭和５８年でしたか。こちらに建設されたときに、当時は当然今よりも高齢化率というのは高くなかったというふうに認識しています。その後、住民の皆様の住み方、住みようというのも時間の経過とともに変わっているということは認識しています。","voiceIndex":183,"id":"exchange-049"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"八潮の高齢化率が高いというところは認識されているということでした。先ほどもお伺いしたのですが、ちょっとお答えがなかったですけれども、要はほかの施設で代替できるというのが今の区の認識だということでいいですか。","respondent":"宮尾高齢者地域支援課長","answer":"それはもちろんその目的にかなった、その特定用途だけに施設があるに越したことはありませんが、ただ、やはり入浴設備を備えた施設となりますと、建設費用の問題ですとか、それからサービスの内容をどうするかというところなど、いろいろ総合的に考える必要があると思っています。","voiceIndex":185,"id":"exchange-050"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ぜひ総合的に考えていただきたいなと思うのです。ひとり暮らしの高齢者の方は、自分もそうならないか不安だということで、お風呂がすごく好きな方でも、１人で入るのが不安で躊躇するという状況が八潮には生まれているというふうにも聞いています。ほとんどのお宅が自宅にお風呂はついていますけれども、そういった入浴に困難な高齢者の実態というのは、区としてはつかんでいらっしゃるのでしょうか。","respondent":"宮尾高齢者地域支援課長","answer":"おひとり暮らしの高齢者の方にお一人ずつ、何か例えばアンケート調査を行ったとかそういった事実というのは我々のほうでは特段ないですが、ただ、やはりこれは品川区に限らず全国的な傾向だというふうに認識しておりますので、先ほどちょっと答弁の中でも触れましたけれども。","voiceIndex":187,"id":"exchange-051"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ですけれども、その後、地域の皆さんの声もあって、そしてまたその地域に銭湯が１つもなくなったということもあって、お風呂が後からついたのです。ですので、八潮の地域もお風呂は各ご家庭にはある。八潮の地域は特に高齢化が進んでいる状況であり、そこはもう区も重々承知のことだと思いますので、ぜひそうしたところからの総合的な検討を進めていっていただきたいのですが、いかがでしょうか。","respondent":"宮尾高齢者地域支援課長","answer":"ただ、当然参考にはしていますが、そういったそれぞれその地区、その地区の状況、それとタイミングの問題。いろいろありますので、一概に南品川が後からつけた、では、八潮にといったことは、また別の角度からの検討が必要かというふうに考えているところです。","voiceIndex":189,"id":"exchange-052"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"すみません。最後にします。当然地域、地域で実情は違うところですので、なので、今、八潮についてということで、八潮を総合的に、高齢化率も考えて、そして健康づくり、生きがいづくり、仲間づくりというところから見て、シルバーセンターが必要ではないかという観点からぜひ検討を進めていただきたいなというふうに思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":191,"id":"exchange-053"},{"speaker":"渡部委員","kind":"質問","question":"ご説明ありがとうございました。そのとおりで、品川区内だって、いろいろなところだって、似たような事故といいましょうか、不幸な事故というのはどこでも起こり得るから、では、それを理由にもってこうだというのは、なかなか言いづらいのかなと思うのだけれど、八潮という場所の特性が、あそこは地区計画がかかっているではないですか。では、どこをどういうふうに変えて、どういうところに。","respondent":"宮尾高齢者地域支援課長","answer":"高齢者の方の生きがいづくり、健康づくり、仲間づくりにつながっていくような対策がどうやって打てるかということは、今後もしっかりと検討してまいりたいというふうに思っているところです。","voiceIndex":193,"id":"exchange-054"},{"speaker":"あべ委員","kind":"質問・要望","question":"ただ一方で、先ほど数字も出ましたけれども、極めて高齢化率が高いというか早目に進行しているということで、今ある公共施設をどう高齢者寄りにしていくかというような工夫であるとか、あるいは施設は同様であっても設備の部分で、より要望に近い形にしていくかということはあるかと思うのですけれども、そうしたところで何か考えてらっしゃることはありますか。","respondent":"宮尾高齢者地域支援課長","answer":"我々は、この実態を大変重く、ありがたく受けとめておりますので、引き続き何か機会があるごとに、例えば今回の東品川シルバーセンターでもそうですが、改修・改築の機会を捉えて進めてまいりたいと思っているところです。","voiceIndex":197,"id":"exchange-055"},{"speaker":"あべ委員","kind":"質問・要望","question":"土地としてのニーズ。その辺の安全対策。一般的なお湯の温度に気をつけましょうとか、ヒートショックに気をつけましょうとかいうことではなくて、もっと通報システムですとかそういったようなことというのは、八潮でこそ展開するメリットというのは大きいような気がするのですけれども、そういった対策というのはある程度とっていらっしゃるのですか。何かあったような気が。","respondent":"寺嶋高齢者福祉課長","answer":"ご指摘のとおり、シルバーセンターに関しましては、先ほど高齢者地域支援課長からも説明がありましたように、基本的にはご自分で入浴ができる方ということなので、ちょっと溺死の対策というのは別途考えなければいけないものかというところは、区としても認識しています。","voiceIndex":199,"id":"exchange-056"},{"speaker":"あべ委員","kind":"質問","question":"午前中出てきました東品川シルバーセンターの改修ということで、浴場を壊して、かなり減るということでもありますので、今シルバーセンターに１０カ所お風呂があるところがあるということでしたが、今後品川区の人口ですとか、あるいは高齢化率が高くなっていくにつれて、それを増やしていくのか。あるいはこのままでいくのか。もし、その方向性みたいなものがあるのであれば、教えていただければと思います。","respondent":"伊崎福祉部長","answer":"当然、今課長からもご説明しましたし、委員の皆様からもご指摘がございましたように、高齢化が進む中で入浴というコミュニティの場をどうするかということと安全管理をすることとは別に分けて、区としても考えていく段階だと捉えております。","voiceIndex":201,"id":"exchange-057"},{"speaker":"若林委員","kind":"確認","question":"前回の委員会で事務事業概要をご説明いただいた中で、この入浴中、浴槽の溺死というのは不慮の事故になるのかなと思っているのですが、そこには平成３０年度として男女合わせて６３名という数字がありましたけれども、死因として不慮の事故に入ってくるかどうかの確認。そうすると、６３人が全部浴槽での溺死とは言えませんけれども、そこからまたデータを取れるのかなと思ったのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":204,"id":"exchange-058"},{"speaker":"若林委員","kind":"質問","question":"去年、おととしだったでしょうか。こういうところで、もしかしたら喫緊の課題かもしれないことを、まさにあそこは都市環境部などそういうところが所管しているわけですから、いい機会ですので、ここに投げてみるとか、取り上げてみるとかという、まさに地域課題としてしっかり取り組んでいくべき課題ではないかなと。そういった観点でやっていきたいなと思いますけれども、何かご見解が。","respondent":"宮尾高齢者地域支援課長","answer":"高齢者の方がいつまでも生き生きと元気でお暮らしいただけるように、そのために我々はこれまでもいろいろな対策をとらせていただいておりまして、そこは高齢化が進んでいくこれからは、ますます重要になってくると思いますので。","voiceIndex":207,"id":"exchange-059"},{"speaker":"渡部委員","kind":"質問","question":"本日結論を出します。先ほど質問の中でも話をさせていただきましたが、さまざまな問題等を抱え、クリアしていかなければならないことがたくさんあると思います。おっしゃっていただいていることの理解の共通性は結構高いのかなと思うのですが、今回この内容については不採択ということで、お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":210,"id":"exchange-060"},{"speaker":"渡辺委員","kind":"意見","question":"結論を出すということで、結論は不採択です。理由は、それぞれの政策課題がこの中にもいろいろ含まれていて、入浴の問題あるいはシルバーセンターのあり方、あるいは八潮という地域の全区的な位置づけなど、それぞれの課題だと思いますし、それぞれ重要性は認識しています。それが１つの理由です。中身について、それぞれの施策の重要性、検討はこれからも十分に深めていくべきだと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":211,"id":"exchange-061"},{"speaker":"若林委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。公明党は八潮在住の新妻区議がいますので、地域でこのお話はよく伺っているところです。ただ、先ほど申し上げましたように、やはりこれは各所管でしっかりと課題として取り組んでいただきたい。決してシルバーセンターが要るか、要らないのか。そういう意味ではなくて、まさに総合的に各所管にまたがって検討していただきたいなと、そういう大きな問題だと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":212,"id":"exchange-062"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"そこから何を住民が求めているのかということを、ぜひ実態を把握していただきたいなというふうに思いますし、先ほど入浴と仲間づくりは分けて考えるというふうにおっしゃっていましたけれども、一緒に考えられるのがシルバーセンターではないかなというふうにも思うのです。ぜひ総合的に、そしてもう検討に入っていただけたらというふうに思いますので、進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":213,"id":"exchange-063"},{"speaker":"あべ委員","kind":"質問・要望","question":"あるいは高齢化が進んでいる中で、高齢者のための施設をもっと充実してほしいというお気持ち。それぞれはわかりますし、そうした方向で検討してほしいと思いますが、ただ、今の八潮の地域に、今の公共施設を全てそのままにしてさらにシルバーセンターを新しく１つ建てるというのは、やはり区全体の公共施設バランスからいくと、少しバランスを欠くかなというふうに感じます。いずれにせよ、入浴施設が欲しい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":214,"id":"exchange-064"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"品川・生活者ネットワークの吉田ゆみこ議員の一般質問の中で、大項目の２つ目、タイトルをちょっと失念したのですけれど、ヤングケアラーに関するご質問。これを地域福祉計画の中でも触れられていないという話だったと思うのですけれども、所管を超えて支援策をつくるべきというようなご質問でした。もちろん必要であるという思いのもとに質問しています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":218,"id":"exchange-065"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3536#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":54978,"voices":220}},{"id":"r01-20190701-8","meetingId":"r01-cm07","date":"2019年7月1日","dateIso":"2019-07-01","committee":"建設委員会","time":"午前１０時００分～午後 ２時５８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を88件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第５２号議案 品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第５２号議案 品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"２点あるのですが、まず改めて今回のこの地区計画等の制限を変えることの目的についてです。この地域の防災性なのか、それとも商店街のにぎわいなのか、そこについてのご説明を改めていただきたいということが１点です。それと、これは補助２９号線の整備を前提にした、それに伴った条例の改正だと思うのですけれども、その沿道３０ｍの容積率や高さの制限といったものは、今回あるのでしょうか。伺います。","respondent":"東野まちづくり立体化担当課長","answer":"こちらは、昨年の都市計画案の説明会、そちらでも委員のほうにご説明させていただいたと思うのですが、そちらの都市計画の変更という中で容積率の変更等を定めているものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"災害に強いということと、商店街への支援というお話でしたけれども、この災害に強いという点では、今回こうした地区計画の変更を含めて、この地域に道路を通してその沿道に幅３０ｍ範囲で高い建物を建てて、延焼遮断帯を形成していくということが目的だと思うのですが、幾つかその点で、災害に強いまちづくりということが目的ということでしたのでお伺いいたします。","respondent":"鈴木都市計画課長、高梨木密整備推進課長","answer":"ちょっと今、手元のほうにはデータございませんが、その中で、やはり一定特定整備路線、２０ｍプラス沿道の用途、容積率の見直しによる延焼遮断帯の形成で、当然ながらエリア全体の耐震化や不燃化、そうしたものとのセットになりますが。その条件といたしまして、建物の最低限高度７ｍであるとか、防火地域指定をして火事、火災に強い建物を建てていただくための指定等は、国等の指針に基づいて、それに従った形で都市計画の決定をし。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"ましてやこうした道路整備のために商店街が削られると。最後お伺いしますが、この店舗を一定にぎわい誘導のために入れるというルールですけれども、何というのでしょう、これでにぎわいというものは維持できるのですか。商店街を削りとる道路計画そのものを見直すほうが、私は商店街の支援のためには必要なことではないかと思いますが、その辺についての見解を伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"こちらにつきましては、地区の皆様方とこれまで話し合いを続けてきた中で、こういった一階部分を店舗その他これらに類する用途にするという制限が必要ではないかというようなところでつくった計画です。商店街のにぎわいの継続のために必要な計画だと考えています。","voiceIndex":10,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから私は、今区が進めている道路整備ではなく、この不燃化領域率７０％を目指していくためには、解体や建て替え費用を助成する不燃化特区支援、そのようなことを促進して、不燃化領域を上げることで７０％を目指し、そして延焼を防ぐというようなことが最も合理的な防災まちづくりではないかという意見を述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問・要望","question":"店舗その他これらに類する用途とあるのですけれども、その具体的な内容について教えていただきたいということ、それから既に二葉町や豊町など、ほかの地域でもこの６０m2未満、今回と同じような基準が導入されていると思うのですが、そこでの現況、特に知らなくてトラブルが起きたとか、苦情とか、また不動産の方たちも当然これを知っていらっしゃらないと、なかなか商売にならないと思うのですが。","respondent":"東野まちづくり立体化担当課長、高梨木密整備推進課長","answer":"その他これらに類する用途としましては例えばボーリング場であったり、マージャン店であったり、カラオケボックスであったり、それから劇場、映画館、保育所、公衆浴場、診療所等がこれらに類する用途として。最低敷地面積を都市計画で定めた地区の状況ですが、確かに地区計画で定めた当初は、自分の土地がもう分けられないであるとか、例えば業者のほうから詳しい説明を求める声というものが挙がったのですが。","voiceIndex":14,"id":"exchange-005"},{"speaker":"たけうち委員","kind":"質問","question":"わかりました。店舗その他これらに類する用途というところなのですけれども、そうしますと、このＢからＤ地区においては、今言ったように１階を店舗、もしくは先ほど言ったボーリング場や映画館、そういったものにしなければならないということになるのかなと思うのですが、これは今現在店舗等をやっているところということですか。","respondent":"東野まちづくり立体化担当課長","answer":"委員がおっしゃられるように、現在住宅で商店街の沿道のところにつきましては、建て替えの場合は適用となりません。現在店舗であるところが、これからも店舗としてにぎわいを維持していけるような形での地区計画となっております。","voiceIndex":17,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"要は、今とてもにぎわっているところが、この道路をつくったりすることによって分断されてしまうおそれがあって、それを何とか維持したいというような感じなのか、それとも、別のところからにぎわっているものをこちらのほうににぎわいを誘導しましょうというようなことなのか、その辺のことを伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"こちら戸越公園駅南口の商店街というところになりまして、現在もイベント等でにぎわいが持続されているような地域です。よそからにぎわいを持ってくるということではございませんで、こちらの商店街が今後とも維持していけるようにというような地区計画です。","voiceIndex":21,"id":"exchange-007"},{"speaker":"吉田委員","kind":"質問","question":"生活者ネットワークにも、お店の方というよりも地域で暮らしている方たちから、この補助２９号線のことと、それから戸越公園駅周辺の大きな再開発で、大きなビルが建ってしまうということについての不安の声がたくさん届いております。その辺のご意見を聞いたりとか、そのようなことはこれまでどのくらいなさっているのでしょうか。伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"平成２９年度からまちづくり検討委員会というものをこの地域でつくりました。こちら、町会、商店街、並びにまちづくり協議会、そうしたところから代表の方が集まりまして、検討してきたものです。","voiceIndex":23,"id":"exchange-008"},{"speaker":"吉田委員","kind":"質問","question":"建築物等の用途の制限の内容を伺うと、風俗特殊営業の建築物はつくらない、にぎわいは維持したい、敷地面積も細分化は、それを言われるとうちの土地も細分化の方向にあるので言いにくいのですけれども、やはり細密化というものは避けるべきだろうなということ、柵の制限などもすごく理解できるのですが、前提が、この戸越公園駅周辺の大規模な再開発と、道路を通すということであると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-009"},{"speaker":"松本委員","kind":"質問","question":"用途制限のただし書きと敷地最低限度のただし書きを読むと、一応今の現状維持というか、今の住居が建っているようなところで、６０m2未満の土地というようなところであれば、また新たに同じような小さな建物を建てられるというような理解でよろしいでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"委員がおっしゃるとおり、現在６０m2未満の住宅につきましては、同様のものが建て替えの際には建てられるというようなものです。","voiceIndex":27,"id":"exchange-010"},{"speaker":"松本委員","kind":"質問","question":"そうすると、防災の観点などからすると、余り大きなものが建っていくという方向ではなくて、小さいものはそのまま残るというところで、これは道路の計画や防災などの観点からすると、ちょっと大丈夫かなというような思いもするのですが、そのあたりはどうでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"こちらの地区につきましては、そのほかに、例えば補助２９号線沿道につきましては、７ｍ以上の建物を建てなければいけないとか、耐火建築物を建てなければいけないなどの制限がありますので、そういったところもあわせて。","voiceIndex":29,"id":"exchange-011"},{"speaker":"大沢委員","kind":"質問","question":"まちづくりで新たな活性化ができるということですけれども、別表第２関係のところで、新規追加として、Ａ地区、Ｂ地区からＤ地区もそうでしょうけれども、店舗型性風俗特殊営業に制限がかかっています。非常に判別は難しいと思うのですけれども、このあたりは店舗型の性風俗営業よりも、むしろ無店舗型を注意、警戒するべきではないかと思うのですが、その想定はどのようにされているのか教えてください。","respondent":"東野まちづくり立体化担当課長","answer":"無店舗型というところも気をつけなければいけないという部分にはなってくるところですので、そういったものにつきましては、警察等との協議をこれからしていく必要があるのではないかと。この地区だけではないと思うのですけれども、そのように考えてあります。","voiceIndex":32,"id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"評価をするのだけれども、幾つかお聞きしたいのは、必ずその協議に皆さんも参加をされて、案的なもの、こういうものでどうですかなどという話をされるのだと思うのです。特例のように、今６０m2以下はこうだよということもしているのだけれども、この辺の意見を交換し合うスタートのときの話に、確かに細分化という話は必ず出るのですが、現実こうだよということがあるではないですか。建物自体は。","respondent":"高梨木密整備推進課長、鈴木都市計画課長","answer":"木密地域で多く６０m2の最低敷地制限をかけておりますので、全体の話としてお答えをしますと、基本的には各地区において、この６０m2ありきで、最低敷地面積の制限をかけるのだったら６０m2ですというような考え方は。今、高度斜線のお話もいただきましたので、補足してご説明しますと、やはり街並みをつくっていくのは、今ご質問いただきました最低敷地面積もありますが、高度斜線、それから地区計画では特に壁面線の後退といって。","voiceIndex":34,"id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひそれで進めてください。木密のようなところは２種高度も結構あるわけで、そうするとその２種高度の立ち上がりの部分をどのように変えていくのだということ、別に２種高度は２種高度で構わないので、立ち上げのところのスタートを変えればいいだけであるから、そういうことも含めて考えていただきたいなと、これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-014"},{"speaker":"安藤委員","kind":"意見","question":"反対です。態度表明をします。延焼遮断帯の形成といいながら、その効果も見られません。商店街の活性化や日常的な暮らしを支える拠点の形成と掲げながら、商店街を削りとる補助２９号線については問題があり、その廃止こそ行政が行うべきことでありますので反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-015"},{"speaker":"吉田委員","kind":"意見","question":"この用途の制限の内容については、それぞれところによっては妥当なものであると思いますけれども、やはり戸越公園駅周辺の大きな再開発と、補助２９号線ということが前提となっており、それに対しては本当にさまざま地域の方たちの不安の声が生活者ネットワークには届いております。この計画を前提とする、この用途の制限の内容については承知いたしかねるということで反対をいたしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-016"}]},{"id":"topic-02","title":"第３６号議案 令和元年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第３６号議案 令和元年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"すみません。仮設という言葉が出てくるのですが、これは一時的なものになるのでしょうか。この環境学習交流施設ができてしまえば、そこに戻るわけにはいかないと思うのですが、その辺をお願いしたいと思います。","respondent":"溝口公園課長","answer":"公園の管理詰所につきましては、三ツ木保育園仮園舎の解体後になりますが、その後公園の改修を今計画しておりまして、公園の敷地等の有効活用から、それにあわせて、そこに管理事務所を設置したいと考えています。","voiceIndex":51,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"今のご説明ですと、三ツ木保育園の仮設園舎が解体された後に、その辺に管理詰所を建設するという想定でよろしいでしょうか。","respondent":"溝口公園課長","answer":"すみません。私の説明が悪かったです。時期的なものは保育園仮園舎の撤去後というふうに考えておりますが、実際の管理詰所をどの場所にしていくのかということは、今年度戸越公園全体の整備計画を立てていく中で、検討しながら進めていきたいと考えているところです。","voiceIndex":53,"id":"exchange-018"},{"speaker":"吉田委員","kind":"質問","question":"すみません。現地を見に行けばよかったのですけれども、その余裕がなくて、まず、仮設倉庫、駐車場を整備する区所有地は今どのような状況なのか教えてください。","respondent":"溝口公園課長","answer":"戸越公園向かい側の区所有地ですが、もともとは遺贈物件になっておりまして、現在は更地で管理しています。","voiceIndex":56,"id":"exchange-019"},{"speaker":"吉田委員","kind":"質問","question":"スケジュールのことを伺ってもいいでしょうか。この議案に直接関わらないかもしれないのですけれども、全体計画説明会が９月に予定されておりますが、それは全体なので、ここで初めてこの環境学習交流施設や、三ツ木保育園の仮設園舎が建てられるよということが説明されるという理解でよろしいのでしょうか。","respondent":"溝口公園課長","answer":"改めて説明会という形で、区民の皆様にお知らせするのはこの９月が初めてのことになるので、そこについてはしっかり計画内容等をご説明しながら進めていきたいと考えているところです。","voiceIndex":58,"id":"exchange-020"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。せっかくの環境学習交流施設ですので、ぜひ地元の方たちにも理解していただいて、歓迎される形で開設に至ったらいいなと考えています。今年の９月に説明会ということなのですが、今７月だから、あと８月、９月の２ヵ月ですか、なるべく早く情報が地元の方たちに行くように要望したいと思いますけれども、少しでも時期を早めるとか、そういう可能性があったら教えてください。","respondent":"溝口公園課長","answer":"なかなか、会場の都合等もありますので、早くやるということは難しいとは思いますが、できる限り広報などの周知期間、そういったものはとりながら、この説明会に臨みたいと考えているものです。","voiceIndex":60,"id":"exchange-021"},{"speaker":"吉田委員","kind":"質問・要望","question":"念を押す形で本当に申しわけないのですが、この場所にたしか遊具があったと思うのです。ぜひ一刻でも早くというか、なるべく早く情報を提供していただいて、丁寧に説明していただきたいなと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-022"},{"speaker":"たけうち委員","kind":"質問・要望","question":"先ほど安藤委員の質疑のところで、この仮設管理詰所の仮設が終わって戻る場所はまだ、一応未定ということでいいのですか。それから、地元のほうからもいろいろ要望等も、直接この戸越公園とは関係ないですけれども、仮設が入る詰所の近辺のところについて、ご要望もあるのかなとは思うのですが、その辺も今後は一応検討しながら、仮設管理詰所というものは検討していくということでよろしいですか。","respondent":"溝口公園課長","answer":"本設につきましては、三ツ木保育園仮園舎のある場所、それから、戸越公園、また隣には文庫の森もありますので、そういったところも含めて、公園の管理詰所としてのその後の運用も含めてになると思いますが、どのように設置したら一番適したものになるのか、また。","voiceIndex":64,"id":"exchange-023"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました。ぜひ地域の意見もいろいろ聞きながらやっていただきたいということと、最後要望ですけれども、この工事をされる期間、かなり大型の車両等も通ると思います。小学校も隣接していますし、近くでこの間死亡事故がありましたから、ぜひ交通事故等に気をつけていただいて工事を進めていただきたい。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-024"},{"speaker":"松本委員","kind":"質問","question":"今回、本予算ではなくて補正で計上された理由についてお伺いできればと思います。","respondent":"溝口公園課長","answer":"（仮設）品川区立環境学習交流施設、または三ツ木保育園仮園舎という公園内を使っての施設建築、または仮設の建築物という形になりますので、極力ふだんの公園利用者にご迷惑をおかけしないような形をとらなければいけないという中で。","voiceIndex":68,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"賛成です。少し意見を言います。環境学習交流施設を建設するための移設ですので賛成です。ただ、この予算の審査には直接関係ないのですけれども、三ツ木保育園の老朽化に伴う改築は必要ですが、改築と同時に民営化はすべきではないという意見を述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-026"}]},{"id":"topic-03","title":"令和元年陳情第８号 細街路拡幅整備事業における拡幅整備不備に関する陳情","agenda":"令和元年陳情第８号 細街路拡幅整備事業における拡幅整備不備に関する陳情","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"立ち木の例が１つ出ましたけれども、いわゆる既存不適格ではなくて、細街路拡幅整備を行った後の後退用地が要綱どおり整備されないというケースにはどのようなものがあるのか、またよくあることなのか伺いたいと思います。区は、違反是正指導実績の件数について、どのような把握の仕方を現状しているのか伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"立ち木の件はわかりましたけれども、例えば塀も結構あると思いますが、細街路拡幅整備を行ったはずなのですけれども塀が残るというようなケースというものは、なぜそういうことが発生するのかということと、またよくあることなのかということも伺いたいと思います。結構あると思いますけれども。そして相談があった場合に、それが法令や要綱に違反していた場合の対応についても伺いたいと思います。","respondent":"長尾建築課長","answer":"こういった塀の突出などがあった場合の区の対応についてですけれども、そういった疑いがあるというようなご連絡を建築課のほうで受けた場合は、先ほどもお伝えしたように現地確認や、所有者の方に状況をお伺いするといったことを行い、まず状況の確認をいたします。","voiceIndex":86,"id":"exchange-028"},{"speaker":"安藤委員","kind":"確認","question":"それはちょっと認識がどうなのかなというか、実際に結構あるのではないかということを私は思うのですけれども、その辺はちょっとどんなものなのか、そのあたりはお伺いしたいと思います。最後に陳情に杉並区での条例改正の例が紹介されておりますが、どのようなものなのでしょうか。品川区では何らかの要綱や条例の改正の考えというものは、区はあるのかどうか伺います。","respondent":"長尾建築課長","answer":"どけてくださいという指導をすると。その指導を続けても効果があらわれない場合は勧告をする、公表するといった行政手続を進めていって、その後退部分の支障物件の撤去というところに対しての対応をしていくような改正を行っております。","voiceIndex":88,"id":"exchange-029"},{"speaker":"松本委員","kind":"質問","question":"この陳情に、具体的な住所などが挙がっているところがあると思うのですけれども、これは不備というふうに考えてよろしいのですか。それとも違う見解があれば教えていただけたらと思います。","respondent":"長尾建築課長","answer":"ですので細街路拡幅整備要綱上の不備というふうには、区としては捉えていないところです。","voiceIndex":91,"id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"資料の一番下の表の違反是正指導実績について、先ほどご報告いただきましたけれども、この実績は指導した実績なのでしょうか。それとも指導の結果、実際きちんと是正してくださった実績なのでしょうか。そこを教えてください。","respondent":"長尾建築課長","answer":"なかなかその建築物にかかわる部分の是正につきましては、すぐに対応できるものとできないものといろいろありますので、違反是正がすぐになされないようなものにつきましては、継続的に所有者にアプローチをして、その後の違反の是正状況などを確認しながら。","voiceIndex":94,"id":"exchange-031"},{"speaker":"吉田委員","kind":"質問","question":"そうしましたら、例えばプランターなどだったら比較的容易に撤去していただけるとかあると思うのですが、この指導実績の内、是正に至った数もきちんと把握しておられるのでしょうか。","respondent":"長尾建築課長","answer":"プランターなど、そういった通行に支障が出てくるような、容易に動かせないものにつきましては、今記録としてはとっておりませんが、事例としては、例えば後退用地部分に駐輪場のラックが置かれていた場合などで、所有者の方に対して継続的にアプローチをして。","voiceIndex":96,"id":"exchange-032"},{"speaker":"たけうち委員","kind":"質問","question":"先ほどの松本委員と少しかぶるかもしれないのですが、この方が理由に挙げられているご自分の他のお住まいの地域の３つの事例について、この方は要旨の中で後退用地が要綱どおりに整備されておらずという理由から多分この３つの事例を挙げていただいていると思うのですが、そうするとこの要綱どおりに整備されていないということではないという理解でよろしいですか。","respondent":"長尾建築課長","answer":"そういったものを要綱上の整備ができていないというふうに捉えられなくもないのですけれども、要綱はあくまでこういう形が望ましいということを明示した上で、それに協力してくれる場合は助成金もお支払いしながら、区であとは施工させていただきながらというところで。","voiceIndex":99,"id":"exchange-033"},{"speaker":"たけうち委員","kind":"質問・要望","question":"この陳情に出されている立ち木については先ほどあったとおり、建築物ではないので要綱としては当てはまらないのだなどということがあって、そういう部分とか、あとほかの２点でコンクリートで囲まれているというところも、実際にこれはどうなのかなと、もし可能な範囲でわかれば教えていただきたい。","respondent":"長尾建築課長、中村都市環境部長","answer":"制限をかけているのは建築基準法の法律のほうでかかっています。適切な道路として整備していくための誘導策として設けているのが細街路拡幅整備要綱となります。立ち木につきましては、法に立ち木についてはセットバックしなければいけないというものがありませんので、これは逆に言うと法の表現されていない部分について立ち木が残っているということになりまして。","voiceIndex":101,"id":"exchange-034"},{"speaker":"松本委員","kind":"確認","question":"今の確認なのですけれども、結局このセットバックというものは、建て替えのときなどに行うかと思うのですが、それが事実上やられていないというふうなことがあるというような理解でよろしいのでしょうか。それであれば、ちょっとしようがない部分もあるのかなと理解いたします。","respondent":"長尾建築課長","answer":"そういった状況もありましたので、昭和６３年に細街路拡幅整備要綱を設けて、適切にセットバックがなされるような状況をつくっていこうというふうにし、細街路拡幅整備というものを進めているところです。","voiceIndex":105,"id":"exchange-035"},{"speaker":"大沢委員","kind":"質問","question":"たけうち委員とかぶりますけれども、何も変わりませんでした、何も変化しないまま現在に至っていますと陳情者はこのような表現をされているのですけれども、これについて建築課としての取り組みは何をされたのですか。教えてくださいということが１つです。","respondent":"長尾建築課長","answer":"あわせて基準法上の中で義務づけはされていない部分につきましては、今要綱の中で誘導策としていろいろ行っておりますので、そういったところから今後ともしっかりとやっていくように、また支障物と呼ばれるような容易に動かしがたいものにつきましても。","voiceIndex":108,"id":"exchange-036"},{"speaker":"高橋（伸）副委員長","kind":"質問","question":"ご説明どうもありがとうございました。その中で、関係資料の２番目の細街路の現状と拡幅整備実績の助成のところです。平成２６年度が１０２件、平成３０年度が６件ですね。この助成件数が増えたか、減ったかということはいろいろな意味合いがあると思うのですけれども、助成が、昨年、平成３０年度は６件にとどまったのか、教えてください。","respondent":"長尾建築課長","answer":"例えば耐震化の事業の中でも、建物除却のお話でいいますと、その建物と道路に突出した部分の塀等を除却することもあわせて行っているというようなところもありますので、ある意味細街路拡幅整備要綱の中でこれまで対応してきたものが。","voiceIndex":111,"id":"exchange-037"},{"speaker":"石田（秀）委員","kind":"質問","question":"そういうことというものが、区で大変ご努力をされていろいろやっていらっしゃるのだろうけれども、現実問題はそういうことが起きてくるのであれば、例えばそこはもう道路として整備しなくてはならないとか、何か法の中でそういうものをやるしかないのかなといつも思っているのですが、そういうところの動きのような、もちろん我々もそれをやらなくてはいけないのかもしれないけれども。","respondent":"長尾建築課長","answer":"品川区としても、こういった他自治体の取り組みにつきましては、今後引き続き動向を確認しながら、より効果的な整備というところにつながるような取り組みについて検討していきたいとは考えております。","voiceIndex":114,"id":"exchange-038"},{"speaker":"石田（秀）委員","kind":"意見","question":"結論を出すでお願いします。結論としては不採択で、これは我々自戒も含めて、今の時点でこれは不採択ですけれども、法改正の部分まで含めて、どこかで議論は必要かなと少しは思っていますが、この陳情自体は不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":118,"id":"exchange-039"},{"speaker":"たけうち委員","kind":"意見","question":"結論を出すで、結論は不採択です。この方の言っていらっしゃる後退用地の改善という部分では本当にそのとおりだと思うのですが、今、石田秀男委員もおっしゃいましたけれども、やはり、この理由にされている部分のものを今の要綱、法律でどうこうできるということはなかなか難しいものがありますので、現段階では不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":119,"id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"一方で細街路拡幅整備は必要な事業なので、個々のケースにおいて、先ほど答弁もありましたけれども、粘り強く住民への働きかけをさらにやっていく必要がありますし、あと区内の後退用地の現状についても、全体像についてはある程度わかりやすく議会や区民に知らせることなど、さらなる努力を求めていきたいという思いから、趣旨採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-041"},{"speaker":"吉田委員","kind":"質問・要望","question":"いろいろこの内容については少し認識が違っているようなところもありますけれども、直接に求めていらっしゃることは、こういう状況について議会や皆が共有できるような形で、全体として改善を図るようにしてほしいということで、そこに具体的に強制的にしろとか、そのようなことは盛り込まれておりませんので、この要旨については十分理解できると思いますので、趣旨採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-042"},{"speaker":"松本委員","kind":"意見","question":"本日結論を出すで、結論は不採択でお願いします。ほかの委員の方々おっしゃられているように、趣旨としては理解できる部分もあるのですけれども、やはり昭和の時代からの背景とか、あるいは現在の法律、整備要綱との関係、そして実際に住んでいらっしゃる住民との関係でも、いろいろと難しいところがありますので、今回は不採択ということでお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":122,"id":"exchange-043"}]},{"id":"topic-04","title":"令和元年陳情第１６号 ホタル生息地の保全に関する陳情","agenda":"令和元年陳情第１６号 ホタル生息地の保全に関する陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"品川学園と八潮学園で行っている行事における、ホタルの産地や入手経路というものはどうなっているのか、わかればお伺いしたいということが１点です。お願いします。","respondent":"小林環境課長","answer":"それから八潮学園につきましては、ＰＴＡの方が取組みとして行っているところでございまして、具体的なところを申し上げますと、八潮団地の区民の方がベランダで飼育をしているといったものを放しています。","voiceIndex":130,"id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"養殖業者から購入されているという話もありましたけれども、例えばその養殖業者から購入しているホタルでも、その親や祖先がどこからのものなのかということはわかるものなのか伺いたいと思います。","respondent":"小林環境課長","answer":"そういうところになりますと、先祖のルーツというところはなかなかビシッとお示しすることは難しいのではないのかなと考えているところです。","voiceIndex":132,"id":"exchange-045"},{"speaker":"吉田委員","kind":"質問","question":"今、養殖のホタルだということが、問い合わせの結果、おわかりになったということは、今現在そのようなことは表示していないと理解してよろしいでしょうか。","respondent":"小林環境課長","answer":"表示についてですが、特に、養殖物を使っていますという表示について、改めて何か表示するものではないというふうに捉えてあります。","voiceIndex":135,"id":"exchange-046"},{"speaker":"安藤委員","kind":"確認","question":"結論を出すで、趣旨採択です。ホタルをはじめ、自然環境やその保全に関心を持ってもらうことに資する１つの方法ではありますけれども、実際になかなか実行するといいますか、産地を確認することは簡単ではないという状況もありますので、趣旨採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-047"},{"speaker":"吉田委員","kind":"確認","question":"こういういろいろなことに対しての産地や入手経路を明確にするということは、生活者ネットワークの基本的な考え方の１つです。私たちとしても少しうかつだったなと思うのですが、このホタルということに関しては、その辺の認識を今まで持っていなくて、今確認させていただいたのですけれども、やはり生産地というのがふさわしいかどうかわかりません。特に野生のものに関しては。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-048"},{"speaker":"安藤委員","kind":"意見","question":"どちらかということであれば、不採択にするべき内容ではないので、採択で構いません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":146,"id":"exchange-049"}]},{"id":"topic-05","title":"令和元年陳情第１７号 羽田増便による新飛行ルートの「教室型説明会」を引き続き開催することに関する陳情","agenda":"令和元年陳情第１７号 羽田増便による新飛行ルートの「教室型説明会」を引き続き開催することに関する陳情","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ただいまの説明のところから少しお伺いしたいのですが、まず２番目の防音工事のところですけれども、前回調査対象だということで２７施設が挙げられましたが、今回助成対象から外された３施設の中で区有施設があれば、その名前を教えていただきたいということと、また、その理由を教えていただきたいと思います。その辺を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"ただ、これは以前から、１３地区終わる前から国のほうには重ねて申している、この場でも申していますが、やはり教室型説明会を含めた、さまざまな手法を活用した丁寧な説明を行っていただきたいということで、結果としてこういう回答になってありますけれども。","voiceIndex":153,"id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、不安払拭を進めていただきたいということで、１３地域センターの説明会が終わったので改めて行ったということですが、これ今まで言っていることと何ら変わりないということで、何というのでしょう、やった意味はあるのですかという内容なのです。このまま受け取ってしまうと。そして一般質問でも、共産党はそのことを伺いましたが、なぜこの場で区議会決議のことを触れないのでしょうか。","respondent":"鈴木都市計画課長","answer":"実際昨年１１月、なかなか実現しなかった教室型説明会も、区長が国土交通省に出向いて直接要望して、１３地域、他区に先駆けて実施していただくということになってあります。","voiceIndex":155,"id":"exchange-051"},{"speaker":"安藤委員","kind":"質問・要望","question":"しかし、区長面談、この出てきた資料を見ますと、従来の内容を超えるものではないし、決議の内容について発言がないということで、なぜなのかということを伺ったので、ぜひしっかりとお答えいただきたい。これは全然決議を重く受けとめているということには、私は見えませんが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"その全会一致の決議の内容が落下物、騒音対策に対する区民の不安、区民への周知不足という理由からというところもございましたので、こうした内容をしっかり受けとめて、区長のほうも現地でこれに沿った、あるいは区として従前から求めてきた内容をさらに強く。","voiceIndex":157,"id":"exchange-052"},{"speaker":"安藤委員","kind":"質問・要望","question":"議会がはっきり容認できないと言った上で、品川区の上空を飛行しないルートの再考を強く求めるということをうたっているわけです。ですから、そこの部分が大事なところだと私は思うのです。決議の評価について伺うと、この間といっても今回の一般質問からですが、そういう決議のそこの部分に関する認識といいますか、受けとめが出てこないのですけれども、その辺をなぜ伝えなかったのですか。これは１点です。","respondent":"鈴木都市計画課長","answer":"そうしたところを踏まえて、今後、本会議の中でもご質問ありましたが、連絡会等が開かれた場合は、やはりそうした現飛行ルート案を固定化することがないような取り組みということをしっかり発言していきたいということを今考えて、検討しています。","voiceIndex":159,"id":"exchange-053"},{"speaker":"安藤委員","kind":"質問・要望","question":"その固定化云々というものを、今度連絡会を開かれるときに表明していきたいというお話ですけれども、固定化しないよう早急な検討を強く求めるということはどういうことなのでしょうか。は新ルートで一旦飛ぶことは認めますが、その後に不断に見直してほしい、見直ししなさいということを品川区がこの時点で国に求めていくように聞こえるのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"今回区の求めに応じて１３地域で地域説明会が開催されたわけですが、この新ルート案に対する区民の声はやはり非常に大きいということで、区としても区民不安の払拭には至っていないという意味では、区議会の全会一致の決議と同様な認識です。","voiceIndex":161,"id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"しかし、不断に見直しをしてくださいというようにしか私はとれないのではないかと思うのですけれども、では確認したいのは、そういう意味ではないということで、あくまで何といいましょうね、今の時点で飛ぶまでの間に、純粋に今のルート案ではない案も検討してくださいねということを要請していることなのですか。その辺少し確認させてください。","respondent":"鈴木都市計画課長","answer":"そうした中で１３地域の説明会が終わりましたが、やはり区民の方からは不安の声が出て、議会のほうもそうした取り組みの不十分、あるいは区民周知の不十分から、ルートの見直しをしてほしいという全会一致の決議が出たわけです。","voiceIndex":163,"id":"exchange-055"},{"speaker":"安藤委員","kind":"質問・要望","question":"早急に検討していただきたいと。早急にということですか。容認できません、と品川区ははっきり言ってほしいのです。そして品川区の上を飛ばないルートの再考を強く早急に求めていくというようなことを言うべきなのではないですか。つまり容認できない、再考を強く求めていくと。これをしっかりと、区としても国に求めていただきたいと思いますけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"これはやはり国の事業で、国がしっかり責任を持って考えていくべきですので、ただそうした中でも、繰り返しになりますが、区民不安に向けた取り組みをしていただきながら、やはり上空を飛ばないルート案というものは。","voiceIndex":165,"id":"exchange-056"},{"speaker":"安藤委員","kind":"質問・要望","question":"白紙撤回、容認しないということだけではないと言いますけれども、そちらを１回でも言ったことがあるのですかという話なのです。言えないという立場なのかと思わざるを得ません。国にはとても言えないと。今後立ちどまって検討すべきだと私は思います。ですから、今立ちどまって検討すべき時期だと思いますので、品川区は少しぶれ始めていると私は言いたいと思いますが、何かございましたらご答弁を。","respondent":"鈴木都市計画課長","answer":"先ほど検討を立ちどまらずにというところで、私がご説明したのは、都心上空を飛ばない検討を技術の進展を待たず今後検討をということでの立ちどまらずにという意味です。","voiceIndex":168,"id":"exchange-057"},{"speaker":"吉田委員","kind":"質問・要望","question":"今日の陳情は、教室型説明会を引き続き開催することに関する陳情ということですので、説明会ということに絞って質問したいと思います。その辺のこともきちんと説明した上で要望をされたのかどうか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"当然ながら教室型説明会については、これはもともと区のほうが強く要望して、他区に先駆けて実施していただいたものですので、１３地区が一定程度終わったのでこれで終了ということではなくて、今後も継続して行っていただきたいというところは。","voiceIndex":171,"id":"exchange-058"},{"speaker":"吉田委員","kind":"質問","question":"いつも１時間半でしたよね。その時間というものは国のほうから１時間半程度の開催にしてほしいということなのか、それとも区が会場の都合でそのようにしていらっしゃるのか。それからマスコミの取材は、一般質問へのご答弁の中でも、区としては取材を制限する理由はないというように考えているということでしたけれども、その辺のことについてもお伝えいただいたのでしょうか。","respondent":"鈴木都市計画課長","answer":"この辺のマスコミについては、これも先ほどの地域説明会の今後の実施とあわせて、やはり区のほうからは継続して何度も求めているものです。","voiceIndex":173,"id":"exchange-059"},{"speaker":"吉田委員","kind":"質問・要望","question":"もちろん、そうすると１回目の地域のものが一番不十分になるというようなこともあるかもしれませんけれども、それは改善の方向であれば別にそれで不満も出ないと思いますし、こうやって、では最初のころの不十分だったところにはもう１回開いてほしいなどという要望も可能だと思います。陳情審査の態度は後で意見とともに言いますけれども、とりあえずそれは要望としてお伝えしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-060"},{"speaker":"安藤委員","kind":"質問・要望","question":"説明会のことについて１点だけお伺いしますけれども、荏原第三でしたか、どこかの説明会で教室型説明会の議事録の公開についての質問がありました。これは検討中ですと、区も要望していて、国も検討していますという段階だったと思うのですが、そのような回答があったと思うのです。そういう事態になったとしても、区はしようがないと考えていらっしゃるのか、その辺を少しお伺いしたいと思います。","respondent":"鈴木都市計画課長","answer":"説明会の中での国の議事録に対する回答ですが、私もその１３地域ほとんど出ましたが、理解といいますか、あとは常に国とこの件についてのやりとりとしている中での認識は、議事録の公開はしませんという紋切り調の言い方ではなかったと思います。","voiceIndex":179,"id":"exchange-061"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ、これがどういう形なのかということはあるかもしれませんけれども、本当に何というのでしょう、追加して開催することとあわせて、ここでどのような質疑が行われたかということを広く共有できるような状況というものをつくられないまま、どんどん計画だけが進んでいるということだけは絶対あってはならないと思いますので、ぜひ実現するよう、もし難しいのであれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":181,"id":"exchange-062"},{"speaker":"大沢委員","kind":"質問・要望","question":"継続にしていただきたいと思います。意見を述べしますが、これは国策である以上、国が責任を持って取り扱う課題である、事案であるということは、先ほど来の理事者の答弁から明らかになっておりますので、そこの部分を前提に、品川区においても区民の不安払拭に向けた取り組み、不断の取り組みを続けていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":183,"id":"exchange-063"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"我々も継続でお願いをいたします。今国策としてやってきている。だから、そこについては、では白紙撤回をしろという感じのことは、我々は言っていないわけで。今回も、議長会への要望として、特に我々の会派は決議があったのだから、決議をそのまま活かして議長会でも他区の皆さんに訴えてくれということを主張させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":184,"id":"exchange-064"},{"speaker":"安藤委員","kind":"質問・要望","question":"採択です。やはり説明会の引き続きの開催を求める陳情の内容ですので、これを採択しないという理由が、私には正直わかりません。公明党も、さらなる説明をということで求めておりました。品川区も継続実施を求めています。ですから私は、本当に緊迫している中、区と議会が力を合わせて、国に少なくとも教室型説明会開催を求める場面だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":186,"id":"exchange-065"},{"speaker":"吉田委員","kind":"質問・要望","question":"教室型説明会をもう少しきちんとやってほしいと、陳情にもありますけれども、あくまで教室型の説明会を引き続き要望してほしいという内容ですので、それについては今、安藤委員からもありましたけれども、皆さん何も反対したり、継続にしたりする理由はないと思います。ですので、ぜひ教室型説明会の開催ということについての陳情は、採択を強く主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":187,"id":"exchange-066"},{"speaker":"松本委員","kind":"質問・要望","question":"結論を出すで、採択でお願いします。やはり従前の経緯を見ておりますと、国の対応というものは説明責任というところからはどうなのかというところがありますので、本件はあくまで教室型説明会を引き続き開催することを求めるというところですから、それは当然のところかなと思いますので、採択ということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":188,"id":"exchange-067"},{"speaker":"安藤委員","kind":"質問・要望","question":"障害者の団体の会長も入るということなのですけれども、連合町会長はこちらの５地域になっているのですが、必ずしも全部を網羅していないようにも見えないこともないのですが、そこら辺の理由をお伺いしたいというのが１点です。それと、資料に、区民の移動実態を携帯電話位置情報により把握するとありますけれども、具体的にはどういうことか、もう少し説明いただきたいと思います。","respondent":"鈴木都市計画課長","answer":"ご指摘のとおり、当初、町会長が１名だけだったのですが、やはりコミュニティバスを検討するに当たっては、いろいろ地域ごとに特性もありますし、そうした意味では、各地域ごとで入っていただきたいということで、区内を５地区、１３地区という考え方もあろうかと思いますが。","voiceIndex":203,"id":"exchange-068"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、アンケートの対象も３,０００世帯ということで、それも５地区からということですので、ある程度、その地域でのルートを考えているのかという印象なのですが、そういう考えでよろしいのかということをまずお伺いします。このルート案の策定や決定に当たって、できる限り住民の声というのを反映するべきだと考えますけれども、そのさせ方も含めてお伺いしたいと思います。","respondent":"鈴木都市計画課長","answer":"これからの検討の中で、コミュニティバスをどのルートで走らせたらいいかというところの検討に入ってまいりますので、そういう意味では、町会の方、あるいはアンケートを５地区、区内バランスよくとらせていただくです。","voiceIndex":205,"id":"exchange-069"},{"speaker":"安藤委員","kind":"確認","question":"確認なのですが、アンケートのほうは、連合町会長が入っている５地域ということでとるというわけではなく、満遍なく区内全域ということでよろしいですか。それと、(4)に事業採算性の検討とあるのですけれども、これは赤字ならやらないという意味なのか、伺いたいと思います。どのようにこの現状を区は考えているのか、解決すべき課題だと考えていらっしゃるのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"要は、大井町から役所までは、今、この陳情に、十何分かかりますと書いてありますが、そこをどう捉えて、区内全域から役所に結ぶルートを新たにつくるのか、そうしたところは、やはり品川区内、充実したバスルートを考えると、大井町と役所を結ぶルートに変えて。","voiceIndex":207,"id":"exchange-070"},{"speaker":"安藤委員","kind":"質問","question":"そういう移動の権利を保障する観点から考えるべきという福祉の事業としての観点というのは持つべきものなのではないかと思うのですけれども、そういった採算性というところが言葉として出てくると、そういった観点が薄れてしまうのではないだろうかと思うのです。その点、移動の権利の保障という観点、そこら辺というのは、区としては持ち合わせていらっしゃるのでしょうかというのを聞きたいと思います。","respondent":"鈴木都市計画課長","answer":"したがいまして、区の総合的な大きい地域交通の実態の中で、コミュニティバスがどうあるかというところをしっかり検討していきたいです。","voiceIndex":209,"id":"exchange-071"},{"speaker":"安藤委員","kind":"意見","question":"結果的に、移動したくてもできないという状況に置かれている交通弱者と言われている方々が少なからずいらっしゃるということで、民間だけでは補完できない、移動の権利が著しく大変になっている地域というのはやはりあるわけで、そういうところでぜひ品川区のコミュニティバスを通して、行政の役割をしっかり発揮していただく必要があるのかと思いまして、改めてその辺、またご意見は聞かせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":211,"id":"exchange-072"},{"speaker":"松本委員","kind":"質問","question":"これは各地域の住民の方たちの意見を吸い上げるというところだと思うのですが、一方で、町会の加入率、今、品川区内で６０％ほどと伺っています。そうすると、代表者というところでいうと、若干、漏れてくる声もあり得るのかというところで、例えば、１名は公募するということは考えられなかったのかというところを伺えればと思います。","respondent":"鈴木都市計画課長","answer":"冒頭ご説明しましたように、平成２６年に設置しました地域交通検討会をベースにまずスタートを切るというところで、今、進めてあります。その中でも、やはり町会長の方、当初お一人でしたので、そこはしっかりバランスをとってというところで、５地区の会長です。","voiceIndex":213,"id":"exchange-073"},{"speaker":"吉田委員","kind":"質問","question":"アンケートのことをまず伺いたいと思います。その辺の分析する人はどのように考えていらっしゃるのか、伺いたいと思います。それは区民同士でも、少しほかの人の考え方も共有しながら進めていくという手順が必要になってくるのではないかというか、ぜひその手順が必要だと考えるのですけれども、その辺、どのようにお考えか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"最初から最後まで区内全域で区内の方に同じような感じでアンケートをとるのがいいのか、どの段階でより地域の方の個別具体の声を反映していくかというのは、今後しっかり検討していきたいと考えています。","voiceIndex":216,"id":"exchange-074"},{"speaker":"吉田委員","kind":"質問・要望","question":"ありがとうございました。それから、やはり区民の意見というところは、すごく重要だろうと思います。その場の設定については、ぜひ慎重に行っていただきたい。最後に、これは本当に要望なのですけれども、ほかの自治体でコミュニティバスを導入しているときに、実証実験を行っています。ぜひそのようなことも、検討の決定に至るまでの中では実施していただきたいということをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":218,"id":"exchange-075"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それは、今言った部分もやってほしい。それから、もう一つは、路線バスがあるではないですか。その中で、やはり事業採算性はしっかり出してほしいと思うし、何らかの理由が、ここが一番こういう形ですという基準を持っていれば、ここはこういう形になっているのでそこを選びましたと言えるような形にぜひしていただきたいと思いますので、何かコメントがあれば、それだけお聞きしたいと思います。","respondent":"鈴木都市計画課長","answer":"やはり地域にかかわること、まさに地域の方でコミュニティバスが要らないですかと聞けば、当然、要らない方はいないわけで、そこの必要性をどう整理してご議論いただくかというところで、今まさにご提案いただいた、町会長会議であったり、そうした場でお示しをしながら。","voiceIndex":220,"id":"exchange-076"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひよろしくお願いします。そのときに、もしよければ、他区で、何でここに通していないのだという部分とか、通しても廃線したとか、いろいろあるではないですか。それは事業採算なのか、どういう形なのかという、いろいろな理由があるではないですか。私が知っている限りでは、江戸川区などというのは、路線バスにかわったわけです。そこはお願いだけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":222,"id":"exchange-077"},{"speaker":"吉田委員","kind":"質問・要望","question":"１点だけ。先ほど石田秀男委員が、多分、例示として言われたのだと思うのですけれども、町会の連合会の会議にかけるようにというぐらいまではやってほしいということで、例示として言われたのだと思うのですが、あえて念のため、連合会会長だけではなくて、ここには、代表で出ていらっしゃるのだと思うのです。強制はできないまでも、そういうことをこの中でお伝えいただければと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":224,"id":"exchange-078"},{"speaker":"吉田委員","kind":"意見","question":"結論を出すということで、私も採択を主張したいと思います。陳情の内容は、本当にもっともだと思います。もちろん進めるということですけれども、進めていくことと、この陳情を採択することは何も矛盾するものではないと思いますので、採択を主張したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":232,"id":"exchange-079"},{"speaker":"吉田委員","kind":"意見","question":"生活者ネットワークも、本日結論を出すということで、趣旨採択を主張したいと思います。それは、今後、区民も含めた議論の中で決めるべきではないかと。読めば、陳情の中に、運行の対象範囲としていただきますようということなのですけれども、やはり固有の地名がここで出てきてしまっているということについて、採択はしにくいかと思いますので、趣旨採択を主張したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":240,"id":"exchange-080"}]},{"id":"topic-06","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"ほぼ毎回、議会にこうした清掃車の接触事故というのが報告されており、少し残念であるなと。前回はあってはならない死亡事故もありました。事故発生件数の経年変化について伺いたいのですけれども、清掃車の事故件数は減少傾向にあるのか、増えているのか、もしわかりましたら、ここ数年の年間件数を教えていただければというのが１点です。","respondent":"工藤品川区清掃事務所長","answer":"交通安全について、あと、安全作業について、本当に毎日毎日繰り返し、そういった場で意識付けをし、一体となった再発防止がとれるように、今、努めているところです。","voiceIndex":247,"id":"exchange-081"},{"speaker":"安藤委員","kind":"質問・要望","question":"その中でミスを出さないというのもなかなか大変な状況かとも思われますので、そういった再発防止に当たっては、労働環境ですとか、そういったところも含めてぜひ取り組んでいっていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":249,"id":"exchange-082"},{"speaker":"大沢委員","kind":"質問","question":"集合住宅が、はっきり言うと、増えているわけですけれども、その集合住宅の量と、収集される職員の関係性、それは、どのように対応して、どのような話を現場でされているのですか。要は、増やしているのか、集合住宅が増えれば、ものすごく収集されている方の負担は増えるわけで、そこのところはどのように対応されているのか。","respondent":"工藤品川区清掃事務所長","answer":"したがいまして、ある１カ所で集合住宅等が増えて、ごみの量が増えましても、当然、そのグループがそれ以上の仕事をするということにはなってございませんで、適正な清掃車、適正な業務量の中で仕事が完結するような形で、毎回、毎年作業計画をつくって、事故のないように。","voiceIndex":251,"id":"exchange-083"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、計画を聞きましたけれども、いずれにしても、先ほど委員からもありましたが、毎日のことで、かなりのハードワークだと思います。そこら辺のところは、確かに交通の安全に対する啓発は必要なことでありますけれども、それ以前に、オーバーワーク、これは、健康面、体調面、体力面、しっかりと留意しながら、計画自体の中にも組み込んでいただきたいと思うのですけれども、どうですか。","respondent":"工藤品川区清掃事務所長","answer":"引き続き、ご指摘ありましたように、やはり職員の安全面、そういった部分も十分配慮しながら、しっかりと取り組んでまいりたいと考えています。","voiceIndex":253,"id":"exchange-084"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"何点か伺いたいと思います。ここら辺のところはどう把握されているのか。品川区にもいるのかどうか、私は全くそこは、ごめんなさい、品川区の雇上業者の部分はわからないので、教えていただきたい。それも含めて、各戸収集をやっているというのであれば、台数も他区よりは多いと思っているのだけれども、そこら辺は多いのか、そうでもないのかというのも教えていただきたいと思います。","respondent":"工藤品川区清掃事務所長","answer":"品川区におきましても、燃えるごみ、不燃ごみにつきましては、大体直営が１、雇上会社が３ぐらいで、１対３ぐらいの割合で入ってあります。他区も同様でございまして、２３区の清掃事業につきましては、雇上会社と一体となってサービスを実施しているというのが現状です。","voiceIndex":256,"id":"exchange-085"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"先ほど来、ずっと安全運転で気をつけてくださいと、だけれども、現実は各戸収集しているわけで、作業員の方も、おりたり、ずっと走ったりというようなところもあったり、結構いろいろさまざまな場面が、各戸収集だと、ほかの区よりは絶対多いはずです。こんなの言えますかと質問したら、絶対言えないですよね。そこら辺も踏まえてあげていただきたい。これは要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":260,"id":"exchange-086"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"不適切だったら、ご指摘ください。質問の内容、中身、一応、言っておいたほうがいいですか。〔「芹澤議員の第４３条ただし書きです。では、発言、質問者が違ってしまいましたけれども、中身についてご答弁いただいたのですけれども、不勉強なものですから、理解できなかったのです。その辺をもう少し図式とかも含めてご説明いただけると、答弁の内容が理解しやすいと思ったのですが、それはだめですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":263,"id":"exchange-087"},{"speaker":"吉田委員","kind":"質問","question":"未接道宅地であっても、こういう条件があれば、それは許可していますというような内容、そういう条件が、すみません、不勉強で理解できなかったので、図式とかも含めてご説明いただけると、ご答弁の内容が理解できるかと思って、この機会がそれにふさわしいのかどうかも含めて、ぜひお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":267,"id":"exchange-088"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4262#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":68663,"voices":270}},{"id":"r01-20190701-9","meetingId":"r01-cm07","date":"2019年7月1日","dateIso":"2019-07-01","committee":"文教委員会","time":"午前１０時００分～午後 ０時０７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第４２号議案、品川区放課後児童健全育成事業の設備および運営の基準に関する条例の一部を改正する条例","agenda":"第４２号議案、品川区放課後児童健全育成事業の設備および運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"筒井委員","kind":"質問","question":"ちなみに、この「指定都市の長」の指定都市というのは大体どういったところなのでしょうか。","respondent":"廣田子ども育成課長","answer":"政令指定都市につきましては、横浜市でありますとか、近くで言えば川崎市、大阪市、名古屋市、京都市等、近いと千葉市、そのあたりと。今２０市程度だと思います。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"確認","question":"今回、研修を行う主体が政令指定都市まで広がるということで、これまで都道府県が行ってきたものと研修の水準が変わることはないのかということを確認したいと思いますが、いかがでしょうか。","respondent":"廣田子ども育成課長","answer":"この内容につきましては、国のほうから全国共通で通用する修了証として位置づけるということなので、修了証等に関しても均一化を図るということにされているものとなっているので、同等のものと認識しています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"意見","question":"均一化を図る、ガイドラインに沿ってやられるということでした。今回の改正部分は認定の研修のところだと思うのですけれども、資格者の資質を向上させる研修というのもあると思うのですが、それは都道府県と政令指定都市では別の役割をもって行われているものだったのですけれども、この認定の研修ではそういったことはなくて、実施主体によって役割分担するということはないということでいいのか。","respondent":"廣田子ども育成課長","answer":"全国一律で行うものと認識しています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"国のほうでこの放課後児童健全育成事業の基準が変わったということで、国会での法案審議を見たのですけれども、この基準が従うべき基準から参酌する基準に、つまりは参考にする基準に変わったということだったのですが、先ほどの説明だと、これは従うべきなので今回改正するということでしたので、今回は、参酌する基準にはなっていないということでいいのか、ここも確認させていただきたいと思います。","respondent":"廣田子ども育成課長","answer":"委託の業者につきましては、配置の基準は確認しておりますが、何人か、入れ替わりもありますので、現在数字としては押さえておりません。参酌すべき基準になろうという話については、来年の春からと認識しています。","voiceIndex":11,"id":"exchange-004"},{"speaker":"のだて委員","kind":"確認","question":"今まで従うべき基準としていたものを参酌する基準にするというのは、私はやめるべきだと思うのですけれども、区の認識として基準はどういうものなのか、特に配置の基準ですね、今、２人以上となっていますけれども、そこのお考え。やはりこれは子どもの安全を守るための最低レベルの基準だと私は思っていますので、これを変えるべきではないと思いますけれども、区の考えをお聞きしたいと思います。","respondent":"廣田子ども育成課長","answer":"受講の予定なのですけれども、区が雇用している職員については全員受講させる方向でやっておりますけれども、委託業者につきましては、認定資格を持っている者と補助員でも可能という部分についてもありますので。","voiceIndex":13,"id":"exchange-005"},{"speaker":"横山委員","kind":"確認","question":"今回のこの改正の背景を教えていただけたらと思います。簡単で結構です。研修の枠のところですとか、受講のタイミングを現場に合わせるというような狙いがあるのかと思うのですけれども、品川区においては何か影響が出るのか、どのような影響があるのかというのを確認させてください。","respondent":"廣田子ども育成課長","answer":"この改正につきましては、国のほうで地方分権に関する提案を募って決めていくというところで、平成２９年の地方からの提案等に関する対応方針ということで決まったと聞いております。","voiceIndex":16,"id":"exchange-006"},{"speaker":"横山委員","kind":"提案","question":"一つ、地方のほうからそういった提案ということで、今回このような改正があったと思うのですけれども、放課後児童支援員も数の状況ですとか受講のタイミングについて、区は全員の受講を進めているということだったのですけれども、枠といいますか、そういったものと、現場の状況というものもあると思うのですが、そのあたり、今現在はスムーズに進んでいるということでよろしいのでしょうか。","respondent":"廣田子ども育成課長","answer":"受講に関しましては、東京都の研修が年間大体１１クールぐらいあります。順次希望を募りまして、１回に数名ずつ、区の直営の職員と委託の職員から希望を募って、区市町村経由で申し込みになっておりますので、順調に申し込んでおりまして受講を進めているところです。","voiceIndex":18,"id":"exchange-007"},{"speaker":"のだて委員","kind":"確認","question":"今回のこの改正で負担が増える方はいるのかどうか、いないのかも含めて確認したいと思います。認可外保育所ですとか認証保育所などはこの条例にはないのですけれども、保育料などがどのように決められているのか、また、無償化に伴ってどうなるのか伺いたいと思います。","respondent":"佐藤保育課長、大澤保育支援課長","answer":"１点目のご質問は、無償化によって負担が増える人がいるのかというご質問ですけれども、負担が増える方はいません。認証保育所と認可外保育所の利用者に関しては、保育料のうち３万７,０００円が無償の対象となります。基本的には償還払いとなりますので、保育料を施設に払った後に、３万７,０００円掛ける利用月数で給付をするという形となります。","voiceIndex":32,"id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"それもぜひ教えていただきたいと思います。今、品川区は認可外保育所にも助成を行っていますけれども、その際に認可外保育所の基準を満たしたところに支援をしていると思うのですが、今回の無償化で認可外保育所の基準を満たしていないところというのはどうなるのか伺いたいと思います。","respondent":"大澤保育支援課長","answer":"認証保育所と認可外保育所への給付につきましては、要綱で定めることになります。認可外の施設につきましては、無償化の対象施設は国の基準を満たしていない施設も５年間は猶予期間として無償化の対象施設となります。","voiceIndex":35,"id":"exchange-009"},{"speaker":"のだて委員","kind":"質問","question":"やはり今の基準というのは認可の基準が最低限になっているということですから、それをさらに上げていくというのが本来行っていくべきことであって、認可外も含めて認証もということになりますけれども、認可の基準に引き上げていくというお考えがあるのか、伺いたいと思います。","respondent":"大澤保育支援課長","answer":"認可外の基準に関しましては、５年間の猶予というのは、国の考え方としても、５年の間に基準を満たす施設になってくださいという考え方ですので、東京都としても品川区としてもそのように指導していくべきと認識しています。","voiceIndex":37,"id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"基準を満たすようにということでしたので、ぜひそれも積極的に区として進めていただきたいと思います。この無償化に伴って区の負担額というのはどうなるのでしょうか。今まで区では私立の認可保育園には大きな支援をしてきたと言っていましたけれども、区立保育園のほうには国から補助がないという話でした。この関係はどうなるのか伺いたいと思います。","respondent":"佐藤保育課長","answer":"無償化の実施に関わる区全体の保育事業に関する財源のご質問だと思います。保育料の減額分に関しましては、１０月から開始なので半年分なのですけれども、１年間でお話をすると、保育料に関しては年間１３億円ぐらいの減収になる見込みです。","voiceIndex":39,"id":"exchange-011"},{"speaker":"のだて委員","kind":"確認","question":"今のお話ですと、年間でいくと１３億円減額になって、私立保育園のところで１８億円ですか、増収になるということで、つまりその計算だとプラス・マイナス５億円になるということになりますけれども、確認でお伺いしたいと思います。","respondent":"佐藤保育課長","answer":"国・都の負担金は約１９億円入ることを見込んでおります。現在の在籍児の数で出していますので、今後、入園児が一定数増えますけれども、その金額で見込んでおりますので、増減としては６億円、単純に計算すると増えていくと見込んでおります。","voiceIndex":41,"id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"これは私立園でプラスで１９億円増収になるということですけれども、そうすると、なおさら区立の保育園が増設されないということを危惧してしまうのですが。区立の保育園というのが大事だと思いますが、この間、区立園が赤字になるというようなお話もあったと思うんですけれども、この区立園が問題だと考えていらっしゃるのか伺いたいと思います。","respondent":"佐藤保育課長","answer":"私立が増えておりますけれども、私立も保護者の要望に応えた的確な保育を行っているということで、保護者からの需要も増えております。どちらにいたしましても、区立のほうも一定程度数を維持して、品川区の保育の質の維持に向けて努力していきたいと考えております。","voiceIndex":43,"id":"exchange-013"},{"speaker":"のだて委員","kind":"質問・要望","question":"区立のほうが大切だということですので、やはり民営化を進めることはやめていただきたいということを言っておきたいと思います。それと、今回のこの無償化というのは、消費税の増税を前提にしたものとして国では進められておりますけれども、増税しなかった場合に、区ではどのような対応をするのか伺います。","respondent":"佐藤保育課長","answer":"増税しなかった場合にどういう対応をするのかですけれども、全国一律で行う国の制度ですので、財源がないとなかなか難しい面もありますので、国の動向を見きわめたいと考えております。","voiceIndex":45,"id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"国の動向を見守るということでしたけれども、それはやはりもう保護者とかには周知をしていらっしゃるのでしょうか。消費税というのは低所得者の人ほど負担割合が重くなるという逆進性の強い税制ですので、やはり消費税に頼らない別の道で実現していくべきだと考えていますけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-015"},{"speaker":"塚本委員","kind":"質問・要望","question":"このことについては、東京都が交付団体だから云々という話も一時期ちょっとあったりしたのですけれども、今後の見通しとして、安定的に国からそういった負担金は得られるかというところでの確認が一つと、あとはこの収支によって得られた増収の使い方ということも、これまでの委員会でもいろいろ議論があったと思います。","respondent":"佐藤保育課長","answer":"増収になることが全国の自治体で見込まれるので、それをほかの事業に回すことなく、子ども・子育ての関係に使うようにというので来ておりますので、その趣旨に沿って、今後も品川区の保育の質の向上に向けて頑張っていきたいと考えています。","voiceIndex":51,"id":"exchange-016"},{"speaker":"塚本委員","kind":"質問・要望","question":"よろしくお願いしたいと思います。第２子が半額で、第３子が無償ということを打ち出しています。そのことに関しては、品川区は、今そこについては第１子の年齢の上限があるので、その部分が東京都の上乗せ支援によって拡充される部分かなと捉えていますけれども、そのことについて、特に条例改正等、ここには載っていないのですけれども、どのような対応になっていくのか教えていただきたいと思います。","respondent":"佐藤保育課長","answer":"もしそれを行うのであれば、次回の補正予算と条例改正が必要になってきます。対象者は相当限られるということはありますけれども、実施要綱がそろそろ確定しそうですので、この辺りを見てまた検討したいと考えています。","voiceIndex":53,"id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"確認","question":"今、負担の話が出てきていたのですけれども、私立保育園に関しては、今、お話があったように国や都のほうの関係で負担金を受けられると伺ったのですけれども、一つは公立の認可保育園のほうは財調との関係で今後も大丈夫なのかということが一つと、あと、今のお話にはなかった、認証保育所に関しては、区の加算分などがあると思うのですけれども、そういった分は、先ほど言ったように。","respondent":"佐藤保育課長、大澤保育支援課長","answer":"３点目の副食費の関係のご質問だと思うんですけれども、この後の第４６号議案のほうで細かくご説明します。ただ、住民税非課税世帯については、現在助成金４万円のものが給付金３万７,０００円となりますので、その差額については、無償化になって助成金額が下がるということは考えづらいので、そこは区で独自助成をしていくように検討中です。","voiceIndex":56,"id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問","question":"恐らく、保護者の方からもいろいろなお尋ねがあったりすると思うんですが、最後の認証保育所のほうは、トータルで言うと区の財源的には差額を云々とありましたけれども、そうすると負担が増えるということではないのでしょうか。","respondent":"大澤保育支援課長","answer":"今、細かい数字を持ち合わせていないので、また後日報告させていただきたいと思います。","voiceIndex":59,"id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"認可外・認証保育所の償還払い等々の決まりは要綱で定めると先ほどおっしゃいましたけれども、その要綱はこの条例改正後に作成するのかということと、それが公表されるのかということを２点お聞きしたいのですけれども、いかがでしょうか。","respondent":"大澤保育支援課長","answer":"要綱につきましては現在検討中ですので、今後、確定しましたらホームページ等でもアップして発表していくことになります。","voiceIndex":61,"id":"exchange-020"},{"speaker":"のだて委員","kind":"意見","question":"保育・幼児教育の無償化は住民生活が向上するというものですし、子育て世帯への負担軽減にもなりますので、賛成します。しかし、消費税の１０％への増税は中止して、所得税や法人税の応能負担を強化するという公正な税制によって保育・幼児教育の無償化を行うべきだということをつけ加えておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":67,"id":"exchange-021"}]},{"id":"topic-02","title":"第４６号議案、品川区特定教育・保育施設および特定地域型保育事業の運営の基準に関する条例の一部を改正する条例","agenda":"第４６号議案、品川区特定教育・保育施設および特定地域型保育事業の運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"今のご説明で、今の条例では実費徴収ができる規定となっているということで、この部分は変わらないということだったと思います。新たに区民への負担はしないように公費で負担をしたいということでしたけれども、先ほども少し話が出ましたが、副食費の部分も含めて、年収３６０万円未満世帯以外についても実費徴収をしないということでいいのか、確認したいと思います。","respondent":"佐藤保育課長","answer":"副食費の実費負担の範囲ですけれども、全世帯の児童に関してこれまでどおり公費で賄うです。","voiceIndex":107,"id":"exchange-022"},{"speaker":"横山委員","kind":"確認","question":"いくつか確認をさせてください。先ほど、今まで各自治体等の考え方ということで、品川区は公費負担ということでやってこられたと思うんですけれども、幼稚園、保育園それぞれの経緯と考え方について確認させてください。２点目が、他区の状況というのが、今、どういうふうな形になっているのか、傾向を教えてください。","respondent":"佐藤保育課長","answer":"一方、幼稚園に関しましては、給食施設は必置ではございません。区内にある単独幼稚園に関しましては、給食調理施設がありませんので、お弁当で対応しています。これまでのそういった経過の中で保育園に関しては公費負担で行ってきたです。","voiceIndex":110,"id":"exchange-023"},{"speaker":"横山委員","kind":"質問","question":"もう一点、補足給付については何か変更点等はあるのでしょうか。","respondent":"佐藤保育課長","answer":"補足給付に関しましては、これまで生活保護世帯の方々に給食だけではなくて、例えば、遠足とか教材費に関しては公費で補足給付するという形になっておりまして、その点に関しましても、今回、国から通知が来ておりまして、より広い範囲の施設で規定を設けるようにということで。","voiceIndex":112,"id":"exchange-024"},{"speaker":"塚本委員","kind":"質問・要望","question":"要するに、認可保育園だとか幼稚園だとか、区立・私立幼稚園、事業所内保育、地域型保育だとか、いろいろなところがある中で、何を指しているのかというのを確認したいのと、我が会派としても要望していた副食費の公費での負担ということで、品川区もそっちの方向だということで評価をさせていただきたいと思いますけれども、その対象となるのはどの施設になるのか。","respondent":"佐藤保育課長","answer":"幼保一体施設で週２回、幼稚園児に対して給食を出していることもやっているのですけれども、この辺も含めて、保育園では当然そうなのですけれども、なるべく広い範囲で給食食材の無償化は実施していきたいと考えております。","voiceIndex":116,"id":"exchange-025"},{"speaker":"塚本委員","kind":"質問","question":"考えていないということで、これまでどおりということになるのかと思いますけれども、その辺りについての検討というのですか、もっと言ってしまえば幼稚園児の昼食が弁当というところがあって、そこに対しての、負担ということは言えないかもしれませんけれども、その部分に対する考え方というところで、今後、無償化ということを念頭に何か考えられることというのはないのかどうか。","respondent":"大澤保育支援課長","answer":"私立幼稚園につきましては、お弁当だけのところもありますし、外部からの搬入が週２回だったり３回だったり、園によってかなりバラバラとした状況ですので、そうなると外部搬入のお弁当に関してだけ補助をするべきなのかという検討が一つ必要なことと。","voiceIndex":120,"id":"exchange-026"},{"speaker":"塚本委員","kind":"質問・要望","question":"ありがとうございました。今のご答弁にあったところでの、いろいろ区から出ている私立幼稚園に対する支援ということでの総合的な検討ということでしっかり検討していただきたいと思います。やはり、在宅子育てという方々に対する支援というのも、今後、区としていろいろ問われてくるような部分もあるのかなと考えていますので、そういった部分での方向性みたいなことも含めて、検討はお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-027"},{"speaker":"芹澤副委員長","kind":"質問","question":"先ほどの塚本委員の質問と若干かぶる部分があるのですが、第３条の改正の部分で、もともと「適切な内容」というところを、「適切であり、かつ、子どもの保護者の経済的負担の軽減について適切に配慮された内容」ということで、あえて変更していると思うのですが、今、この改正文を見ていて、ここだけそんなに入れなくても現状の改正というのはできたのかなと思っているのですが。","respondent":"佐藤保育課長","answer":"今回も基本的にそういう考え方だというのを強く打ち出してはいるのですけれども、一方で年収３６０万円未満の世帯に関して副食費は免除という考え方を、どちらかというと最近といいますか、追っかけで出してきているような面もありますので、そういう形も反映して。","voiceIndex":124,"id":"exchange-028"},{"speaker":"芹澤副委員長","kind":"確認","question":"すみません、もう一回確認です。そうすると、今回の第３条であえて書いているのは、基本的に今のところ品川区としては副食費についての考えであって、それ以外の、大枠で子育てに対してこういう経済的な負担がある世帯に対してのどうのこうのというのは、今回の改正では特に考えていらっしゃらないということですか。","respondent":"佐藤保育課長","answer":"副食費も含めて主食費に関しましても、これまで区としては公費で負担をしてきておりますので、この辺りに関しては特に考え方を変えるということもありませんし、後退するものでもございません。","voiceIndex":126,"id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"最後に１点だけ。この給食費の、予算というのはどのぐらいになるのかだけ伺いたいと思います。","respondent":"佐藤保育課長","answer":"単純計算で申しわけないのですけれども、国の試算ですと年間９万円ぐらいかかるというところで、それに対して対象者が大体５,０００人ちょっと超えているぐらいですので、年間５億円ぐらいの経費がこれまでもかかっているです。","voiceIndex":129,"id":"exchange-030"}]},{"id":"topic-03","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"１つだけお聞きしたいのですけれども、４和解条項の（２）について、「可能な限り、当該児童の動静を注視するよう努めるものとする」というところで、これに対して何か、もうちょっと具体的な区側の考えというか、今後の取り組み方というか、もう少し何かあればお聞きしたいと思います。","respondent":"有馬庶務課長","answer":"今回もそれはしていたのですけれども、より注意深く見ていきましょう、ということで現在は取り組んでいるです。","voiceIndex":143,"id":"exchange-031"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、今、お話しされた和解条項の（２）なのですけれども、これは当該児童、今回の原告だけの話ではなくて、今後一般的にこうした同様のケースの場合は区としては注意をしていく、今後の一般的な取り組みということで捉えていいのかということと、また今回、原告のほうから、主治医から運動再開の許可が出たということを申し出られたということで、その点。","respondent":"有馬庶務課長","answer":"１点目の和解条項の（２）のところですけれども、これは一般的に今後もこういう児童がいたら、きちんと注視していきましょうということで、いわゆる再発防止策の一点という意味合いで捉えています。","voiceIndex":145,"id":"exchange-032"},{"speaker":"芹澤副委員長","kind":"質問","question":"伺いたいのですが、和解がもう成立しているということなので、そこに関してはどうこう言うものではないのですが、今、お話があったように、長期間運動を休止してきた方が出てきて、保護者の申告をもとにもう一回運動の再開をするということだと思うのですが、そういう場合というのは、基本的には保護者の申告ベース、もしくは本人の申告ベースになるとは思うのですけれども。","respondent":"大関教育総合支援センター長","answer":"実際に、現場ではそのような形で話し合いをしながら進めておりますが、今回の案件につきましては、何百ｍ泳いでよいというところまでの詰めという部分で、結果的には意見の齟齬があったと認識しております。","voiceIndex":148,"id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"和解が成立したということですので、ほかの委員からもありましたけれども、こういうことが起きないように、今、話し合っている、十分注意をしながら指導していっていただきたいというのが一つで、お尋ねしたいのは、解決金の費用と、区として独立行政法人日本スポーツ振興センターの災害共済給付金の申請をするのですけれども、そことの関係というのが何かどういった形になっているのか。","respondent":"有馬庶務課長","answer":"解決金の８０万円に関係する日本スポーツ振興センターの関係ですけれども、日本スポーツ振興センターのほうは、まだ本人が申請をしていないという状況ですので、こちらについては、これからやりとりをするという段階です。","voiceIndex":151,"id":"exchange-034"},{"speaker":"高橋（し）委員","kind":"確認","question":"金額はお聞きしたのですけれども、そういう仕組みで支払われるということですが、被告が区ということですので、学校の先生方個人が対象にならないで、区のほうで被告になっているということだけ確認して終わりにします。","respondent":"有馬庶務課長","answer":"今回の事例は、その因果関係まで特定はされていません。判決ではない、和解の中での判断ということになりますので、故意だとか重大な過失があったとまでは認められないということで、教員には求償というようなことは求めない予定でおります。","voiceIndex":153,"id":"exchange-035"}]},{"id":"topic-04","title":"屋内体育館への空調設備設置","agenda":"屋内体育館への空調設備設置","exchanges":[{"speaker":"横山委員","kind":"質問","question":"それぞれの耐用年数と点検の時期を教えてください。熱効率ですとか、リースの費用面というのが、今回どのように工夫をされるのかというのを教えていただけたらと思います。","respondent":"有馬庶務課長","answer":"熱効率の工夫という部分ですけれども、どういうふうにやっていったらいいのかというところは、今、検討しているところなのです。","voiceIndex":159,"id":"exchange-036"},{"speaker":"横山委員","kind":"確認","question":"体育館の広さですとか改築等の状況によっても効率は変わってくるのかなと思うのですけれども、考え方だけ確認させてください。","respondent":"有馬庶務課長","answer":"熱効率をどこまでやっていくかというのは、まず外気との関係で考えていくというのが一つと、それから広さについても同様でして、大きい体育館と小さい体育館とではやっぱり違いますので、写真の戸越体育館みたいな吹き出しのものについては、例えば４基で済むのか。","voiceIndex":161,"id":"exchange-037"},{"speaker":"筒井委員","kind":"質問","question":"リースの学校と工事の学校と、大きく分けて２通りあると思うのですけれども、リースの学校と工事の学校を分けた理由というのは何なのかということと、リースと工事のメリットとかデメリット、何か違いがあるのかをお聞きします。","respondent":"有馬庶務課長","answer":"ただ、区として仕事を進めていく上で、工事とリースの全体のバランスをとっていかないといけないだろうということもございまして、今年の全体計画としては、こういうふうに考えたです。","voiceIndex":164,"id":"exchange-038"},{"speaker":"筒井委員","kind":"質問","question":"特に生徒にとっては効用はあまり変わらないと思うのですけれども、この図を見ますと、“何でうちの学校はリースで、工事ではないのか”というご意見も出るかと思うので、そこの辺を聞いたのですけれども、そうしたご意見が出たらどうお考えになるのでしょうか。","respondent":"有馬庶務課長","answer":"リースでいけば、撤去をするときもリース代に含められるということもありますので、これから改築が予定されている学校については、リースという判断をさせていただいたために、こういう割り振りになっているです。","voiceIndex":166,"id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"リースのほうが空調設備の機械が古くなったり、モデルが型落ちしたとか、そういった場合、柔軟に対応できるというメリットというのはあるのでしょうか。すぐ交換したりとか。","respondent":"有馬庶務課長","answer":"今回のリース契約は、今回導入する機器でのリース契約という形になりますので、これを入れ替えるとなると、また新たな更新をかけなければいけないということになってきます。","voiceIndex":168,"id":"exchange-040"},{"speaker":"筒井委員","kind":"質問","question":"そういった面では、でもコスト的にはリースのほうが安い、そういったメリットというのはあるのでしょうか。","respondent":"有馬庶務課長","answer":"今はリースの契約が終わったところでして、設置工事はこれから契約締結ということになりますので、最終的なところはこれから出てくるだろうと思いますけれども、それほど大きな差はないのではないかと考えております。","voiceIndex":170,"id":"exchange-041"},{"speaker":"塚本委員","kind":"確認","question":"夏に向けてできるところにいろいろな対応をしていただきながら進めていっていただいて、大変ありがたいと考えています。スポットバズーカを見ていると、操作というか、扱うのが結構大変そうにも見えてしまうのですけれども、その辺は問題はないのか。誰がどういうふうに管理するのかというのをお聞きしたいので、最初に確認させてください。","respondent":"有馬庶務課長","answer":"学校で使う分については、基本的に教員が操作をしていくということで対応を考えているところです。","voiceIndex":173,"id":"exchange-042"},{"speaker":"塚本委員","kind":"質問・要望","question":"今の説明に加えて、操作というのはスイッチの入り切りぐらいであまりないということですか。わかりました。事業者とか資材の関係が非常に進んできて、前倒しに進めるような環境が出てくればということもあり得るのかどうか、その辺りのお考えもお聞かせください。","respondent":"有馬庶務課長","answer":"基本的には今年度予定しているところは順調にいっているということでして、あと改築校は改築に合わせてやっていきますので、ここは大丈夫かなと思います。ただ、ここは令和３年までには全部いかないと思いますけれども。","voiceIndex":175,"id":"exchange-043"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"一つは、第二体育館がある学校があると思うのです。３つ目は、先ほど一般開放のお話がありましたけれども、熱中症対策などで一般開放での使用について、今、詳細を詰めているところということですので、ぜひ使用について進めていっていただきたいのですが、そこだけもう一回、一般開放でも利用できるかという確認だけお願いします。","respondent":"有馬庶務課長","answer":"基本的にはそういった第二体育館も含めて導入を考えているものです。それから、スポットバズーカの安全対策については、何らかガードをしていく必要があるのかないのかを含めて検討していきたいと考えています。","voiceIndex":179,"id":"exchange-044"},{"speaker":"芹澤副委員長","kind":"確認","question":"備品のところで少し確認をしたいのですが、いわゆる収納場所と設置場所といいますか、当然、体育館はスポーツをやるところだと思うのですが、例えば、体育館の壁ぎりぎりにバスケットボールのコートの線があったりというときに、どこに設置できるように……というのは、ちゃんと場所の確保というのも考えた上で数が決まっていらっしゃるのかと。","respondent":"有馬庶務課長","answer":"ですので、基本的には各学校で状況が違いますので、普段はどこに設置して、普段はどこにしまっておく、というのは、各学校の運用上の問題になると思いますので、こちらから一律にこうしろとかああしろ、ではなくて、学校状況に合わせながら、そのときはこっちに持ってきなさい。","voiceIndex":183,"id":"exchange-045"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"高橋（し）委員","kind":"質問","question":"どういう言い方をしたらいいかわからないのですが、西本議員の「子ども政策について」。詳しく言ったほうがいいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":187,"id":"exchange-046"},{"speaker":"高橋（し）委員","kind":"質問","question":"ぷりすくーる西五反田のことについて質問していただいて、指定管理者のＮＰＯ法人を社会福祉法人化していくというお話だったのですけれども、数年後の幼保連携型認定こども園を目指すという答弁です。それで、社会福祉法人か学校法人でないとできないからという答弁だったのですけれども。どういうことを聞きたいかというのも言ったほうがいいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":189,"id":"exchange-047"},{"speaker":"高橋（し）委員","kind":"意見","question":"それで、社会福祉法人化について、いつ設立になるのかというか、実際に運用になるのか、その目星というか目処ですね。現在のＮＰＯ法人との関連と、そこが今行っている指定管理の契約との関係はどうなるのかということ。認定こども園化を進めるということについて、私は賛成をしているので、そちらの考え方に基づいてお尋ねしております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":191,"id":"exchange-048"},{"speaker":"のだて委員","kind":"確認","question":"確認なのですけれども、昨年は空き状況のところが４月１日の空き状況で出されていたのですけれども、今回は５月の入園可能数となっていますが、これは何で違っているのか。それによっての違いというのはあるのか伺いたいと思います。昨年は０歳児から２歳児のところでばらけて待機児童がいたのですけれども、今回９割以上が１歳児のところになっておりますけれども、そこの分析も伺いたいと思います。","respondent":"佐藤保育課長、大澤保育支援課長","answer":"１点目のご質問ですが、表示が紛らわしくて申しわけないのですけれども、昨年の資料の数字も４月１日入園で埋まった後の空きの状況を記載しておりますので、今回と時期は一緒です。その対応策につきましては、来年４月に、同地区に少し定員の大きな園の開設を予定しておりますので、そちらのほうで吸収していけるのではないかと考えています。","voiceIndex":195,"id":"exchange-049"},{"speaker":"のだて委員","kind":"質問","question":"今、東大井・八潮地区のご説明があったのですけれども、前回は東大井・八潮地区と五反田地区のところで待機児童が出たというところでしたが、今回、五反田地区のほうでは待機児童ゼロになったと。品川地区と大井地区で出てきてしまったというところの分析も伺いましたので、そこも伺えればと思います。","respondent":"大澤保育支援課長","answer":"品川地区に関しましては、今回１歳児で１名待機児童が出ておりますが、空き状況を見ていただきますと、定期利用、地域型保育事業等に空きがありますので、この辺りはマッチングの問題だと考えております。","voiceIndex":198,"id":"exchange-050"},{"speaker":"のだて委員","kind":"質問","question":"それで、この表の中で、この間というか、平成３１年４月に向けても何園でしたか、認可保育園が開設されたと思うのですけれども、昨年と入園数を見ますと今年のほうが入園数が少ないのです。それが見たところ不承諾数が増えているというところで、この原因というか理由を伺いたいと思います。","respondent":"大澤保育支援課長","answer":"しかしながら、認可保育園の増設を中心に進めていくという考え方に変わりはございませんので、前回の文教委員会において、事務事業概要の中でご報告申し上げたように、令和２年度につきましても１０園の認可保育園の開設を予定しているところです。","voiceIndex":200,"id":"exchange-051"},{"speaker":"のだて委員","kind":"質問","question":"入園者数のところがよくわからなかったのですけれども、開設園が昨年より少なかったということで、この入園者数が減るというご説明がわからなかったのですが、既に入っている人は持ち上がりでいくので、この最初の０歳児なのか１歳児なのかというのはありますけれども、この分は全部上がるわけですよね。今、国のほうでもまとめたりしていると思うのですけれども、その待機児童数を伺いたいと思います。","respondent":"佐藤保育課長、大澤保育支援課長","answer":"１点目のご質問の入園者数のところなのですけれども、品川区は毎年待機児童対策でたくさん保育園をつくっているのですけれども、平成３０年度と平成３１年度を比較すると若干枠として減っているので。隠れ待機児童数というのが、認可以外の保育施設を利用されている方と理解すると、２４６人の方が認証等のほかの施設を利用しておりますので、その分は不承諾から引いておりますので、その数というお尋ねかと思います。","voiceIndex":202,"id":"exchange-052"},{"speaker":"のだて委員","kind":"質問・要望","question":"この隠れ待機児童は２４６人だということで、年齢別もわかれば教えていただきたいと思うのですけれども、実際に待機児童も１２人いらっしゃるということと、隠れ待機児童も２４６人いるということで、これで実質ゼロと区のほうは言っているわけですが、これがなぜゼロなのか、実際に待機児童がいるということだと思いますけれども、伺いたいと思います。","respondent":"大澤保育支援課長","answer":"これを地域別に見ましても、東大井・八潮地区につきましては、一番多い１歳児の待機児童が８人いますけれども、空き状況を見ていただくと認可保育園、定期利用、認証保育所を含めまして空きが８ありますので、地域別に見てもどこかの施設には入れる状況になっているということで。","voiceIndex":205,"id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"どこかの施設に入れるということですけれども、やはり認可保育園を希望して申し込みをされているということだと思うのです。定期利用のものもありますけれども、これもやはり期間が限られているということで選ばない人もいるのかなと思いますので、やはり認可保育園を増設していくということで待機児を解消していくというふうに進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":207,"id":"exchange-054"},{"speaker":"高橋（し）委員","kind":"質問","question":"一つだけ。品川地域の待機児童であるのですが、まだ今後、南品川、東品川地域に、今、建設中、あるいは完成間近のマンションもあると思いますけれども、そちらのほうの見込みについて。先ほど勝島、東大井地域のお話をいただいたのですが、そちらのほうの見込みといいますか、その辺りはいかがでしょうか。","respondent":"大澤保育支援課長","answer":"マンションの建設につきましては、当該の所管から保育支援課としても情報をいただきまして、計画等に反映させているところです。今後も地区別の需要をよく見ながら適切に供給してまいりたいと考えております。","voiceIndex":209,"id":"exchange-055"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"この地域ではこれまでも増えてきたところに対応していただいたのですが、まだ今後も増えていくと。今、お話があったような形で情報収集して対応していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":211,"id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4970#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":35394,"voices":212}},{"id":"r01-20190701-5","meetingId":"r01-cm07","date":"2019年7月1日","dateIso":"2019-07-01","committee":"総務委員会","time":"午前１０時００分～午後 ５時０１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を149件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"では(1)の第３７号議案からの審査でありますが、会議の運営上、順番を入れ替え、審査を行います。 まず、(9)第５９号議案、防災行政無線設備更新工事請負契約","agenda":"では(1)の第３７号議案からの審査でありますが、会議の運営上、順番を入れ替え、審査を行います。 まず、(9)第５９号議案、防災行政無線設備更新工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"最後の説明で、屋外拡声子局設備とありましたが、子局とは何ですか。","respondent":"中島防災課長","answer":"子局と申しますのは、今回屋外に設置するスピーカーと鉄柱、アンテナという形になります。親局が庁舎防災センターにありますので、ここから発信したものを受けるのが子局という位置付けです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、実際その辺について把握されているのでしょうか。というのは、うちの地域もそうなのですが、多くの区民の皆様から聞こえないと、何を言っているのかわからないと。その点についての認識と、４６カ所更新するということですが、実際これだけの数で足りると感じているのでしょうか。その辺について、ご見解をお聞かせください。","respondent":"中島防災課長","answer":"ただ、やはりドアの気密性でありますとか高層化に伴いまして、一定程度やはり聞こえないという現象もありますので、そういうところにつきましては補完手段といたしまして、緊急情報発信ダイヤルでありますとかメール等の対応でしっかりと対応していきたいと考えています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"須貝委員","kind":"質問・要望","question":"そのときに、いや、聞こえない、わからないということだと非常に不安になって、ではどうしたらいいのだろうとまごつくのが想定されることだと思うので、まして今、大震災が近づいているという話、もう３０年以内というのがはっきり明確に出ているわけですから、それならもう本当にご苦労なことだと思うのですけれども、様々な民間の施設を借りてでも。","respondent":"中島防災課長","answer":"ただ今後運用していく中で、やはり補完手段等もあります。先ほど委員もおっしゃったように、ラジオＦＭしながわとの連携も始めておりますので、そういう形の補完手段もしっかりと充実して、数と質をともに対応していきたいと考えています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"西本委員","kind":"確認","question":"この入札金額のところで、あまり大きな差はない状況でも低いほうがということになるのですけれども、この内容の確認というのはどこまでされているのでしょうか。品川区は高層マンションとかが増えてきているのですけれども、今回１５カ所新設ということなのですが、そうはいっても防災無線の役割は大きいだろうと思うのですが、どれだけの台数をこれから設置すべきなのかという検討はされるのでしょうか。","respondent":"立木経理課長、中島防災課長","answer":"こちらの２１ページの調書の１番、２番にあります田中電設、田中電気は、おそらく何も関連のない会社だと考えています。積算の部分に関しましては、きちんと積み上げがあったものをベースに入札予定価格を出しています。今のところ、現状の予定といたしましては、１５７局の子局、あと個別の受信機と申しまして、各施設等に配置している２５０局の子局のところで対応をして、そちらに関しましては、これまでの調査等で対応可能だと考えているところです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"そうなった場合の選定の仕方。そうすると、違う意味での形での条件をつけていくことも考えることが必要なのかなと。逆に言うと、優秀なところがあれば、そこをどんどん使うような入札の仕組みをつくっていかなければいけないとかいろいろ考えなければいけないと思うのですが、その辺の考え方はどうなのかなということをもう一度お聞きしたいと思います。１点だけお願いします。","respondent":"立木経理課長","answer":"お金だけではなく、工事のこれまでの成績から履行者を決定するという成績評定型の総合評価という仕組みも持ってありますので、そういったものをいろいろ上手に組み合わせて、よりよく、より安くという形を今後もしっかりやっていきたいと考えております。","voiceIndex":14,"id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"議案発送のときにはどれほどの資料が出てくるのかわからなかったですし、説明資料が手元に届いたのは先週木曜日だったので、委員長に事前に申し入れることもできずこの場となったのですけれども、ぜひ今後の契約の資料には、工事の工程表と予定価格の根拠となる資料、それと辞退理由を添えていただきたいと思うのですが、いかがでしょうか。","respondent":"立木経理課長","answer":"中身に関しましては、各所管する常任委員会のほうでそれぞれ議論が尽くされた上での契約依頼という形で、経理課のほうで承っているものですので、そこの部分、例えば予定価格の積算根拠ですとか、あと工程表の細かい部分というのは。","voiceIndex":18,"id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"その中身は各所管と言われても、そうかもしれないのですけれども、でも、その中身のことも知っての契約だと思うので、その辺は工夫していただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-007"},{"speaker":"つる副委員長","kind":"質問","question":"今日防災課長がいらっしゃるので、質問します。大事なことなのです。先ほど聞こえない、聞こえづらいとあった一方で、うるさいと言われてしまうことも、これは日常の中であるのですね。なので、新設するところにあたっては、周辺の近隣の区民の方々への説明というのはあって工事に入っていかれるのでしょうか。","respondent":"中島防災課長","answer":"設置にあたりまして、住民の方々、近隣の方々への説明ということにつきましては、どこまでしているかというのはちょっと確認はしていなかったのですが、設置に関してしっかりとそういう事後の対応等もやっていきたいと考えています。","voiceIndex":21,"id":"exchange-008"},{"speaker":"つる副委員長","kind":"質問","question":"５カ年で全体で子局が２２局の中で、今年度が１５局とかなり大きいと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-009"}]},{"id":"topic-02","title":"第６７号議案、防災服他の買入れ","agenda":"第６７号議案、防災服他の買入れ","exchanges":[{"speaker":"小芝委員","kind":"質問・要望","question":"購入理由についてお伺いしますが、来年の東京２０２０オリンピック・パラリンピック大会の開催を理由としておりますが、何か防災服の購入とオリンピック・パラリンピックとのつながりというのはいまいち見出すことができないものでございまして、何かほかに理由があるとすれば、それを教えていただきたいのですが。","respondent":"中島防災課長","answer":"東京２０２０オリンピック・パラリンピック大会とのつながりですが、今回、あまり想定することではないのかもしれないのですけれども、例えば警備事象とかが発生した場合には防災服を着用するとか、そういう現地での活用等が一定程度見込まれます。","voiceIndex":38,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"資料にある防災服他の買入れについての概要書なのですけれども、製品選定経過の中で職員の意見も聞いているというところがありますけれども、今までの防災服は男女兼用といいますか、ほぼ男性の体格に合わせていると思うのですけれども、今回もその辺、やはり体型が違うと男性用と女性用とでは服の形も違うし、機能性を考えるとどうなのかなと前から疑問に思っていたところはあるのですけれども。","respondent":"中島防災課長","answer":"今回、デザイン面での大きな変更点に関しましては、今まではシャツタイプと申しまして、ズボンの中にシャツを入れるようなタイプになっておりますが、今回はブルゾンタイプということで上下切り離しておりますので。","voiceIndex":40,"id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"辞退したところに、理由として服地の入手が困難というお話でしたが、実際ここの会社は品川区に所在しているわけで、問屋も近いと思うのですが、今、何か服地が切迫して世の中に出回っていないというような話は我々も聞かないのですが、そうなのでしょうか。ちょっとその辺どうなのだろうと思うのですが、ご見解をお聞かせください。","respondent":"立木経理課長","answer":"こちらの４２ページの調書２番の会社の服地の入手が困難という部分に関しましては、詳細は私どももちょっとわからないのですが、この防災服を今回作成するにあたってのベースとなっている参考品番といったもののベースのものが、どうもつくっているメーカーのほうから。","voiceIndex":42,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、国でも中小企業を大事にしてあげてくださいという広報まで出ているくらいですから、区としても今後何とか区内業者のところに仕事が回るように、できるだけ対応していただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-013"},{"speaker":"西本委員","kind":"提案","question":"今も質問のありました服地の件なのですが、これはデザインは専門学校の提案でということなのですね。そうなってくると、このデザインから実際つくる段階において、服地を調達するときに、やはり問屋は問屋で出回っていると思うのですけれども、そうなってくると結局大きい会社のほうが、調達しやすかったということなのですか。","respondent":"立木経理課長","answer":"そういった中で、例えばそれを使ってやるのか、それとも別のものをベースにしてやるのか、それは各会社のほうの判断ということになりまして、例えばそれでうまくいけるというようなことがあれば別のものに切り替えて、事前に届けていただくということになると思いますが。","voiceIndex":45,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"これは、デザインの段階で指定された仕様、指定された生地の種類に伴ってやっていくのでしょうけれども、実際形、服になったときに、やはりいろいろ変わることがあると思うのです。これでいいだろうと思っても、こちらのほうがいいよという、そこら辺の判断はどちらがするのですか。そこまでこの会社がやっていくということでの契約になっているのでしょうか。","respondent":"立木経理課長","answer":"今委員がおっしゃられたとおり、紙の仕様で文字とか絵で表示されております。それをベースにつくっていただいて、実際仕立て上がりみたいなものは区の所管と確認しながら、最終的には生産に入っていくという形をとると考えております。","voiceIndex":47,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問・要望","question":"よくずれが出てくると思うのです。ちょっと気になるのですが、どちらかというとここで一緒に変えるべきだったのではないかと思うのですが、どうなのですか。","respondent":"中島防災課長","answer":"靴に関してですが、現状ではそのまま使うというところで考えておりまして、委員ご指摘のご意見もありますが、使えるものは使っていくというところもありますので、現状のところは靴はそのままで使っていきたいと考えています。","voiceIndex":49,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"では意見として、靴の件は今後考えてください。多分いいものが出てきているはずなので、やはり靴というのは非常に大切です。危険を伴う場合が多々ありますので、足にけがしてしまうと助けられる側になってしまうので、助ける側にならなくてはいけないですから、そういう意味でもより安全性の高いものにしていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-017"},{"speaker":"つる副委員長","kind":"質問・要望","question":"着数なのですが、４,６２３点の全職員プラス議員貸与ということで、それを引くと４,５８３着になるのですが、これは予備分ですとかそういうのもあるかとは思うのですが、どこまでの職員が範囲か改めて教えていただきたいのと、そうした出入りがおそらくあると思いますので、そういう予備分がどのぐらいあるのかということと、あと、サイズは今既存のいらっしゃる方にアンケートをとっているので。","respondent":"中島防災課長","answer":"そのような形で配布をしています。サイズについてですが、ＸＳから５ＸＬまで、今、数量は職員等に調査いたしまして計上しています。予備につきましては、手元に今資料がないですが、たしか７００着程度、職員のサイズに比例した形で用意をしています。","voiceIndex":52,"id":"exchange-018"},{"speaker":"つる副委員長","kind":"確認","question":"ただ、一応確認で、今後このデザインのままで何年いくかわからないですが、当然足りなくなれば都度発注するわけですよね。その発注単位はどのぐらいのイメージで考えていらっしゃるのか、どのぐらい減ってきたらこのくらい発注しようとか、そういう細かい部分ですが、そうすると印刷などでも版下があって、それを刷るだけなら安いとかあるじゃないですか。","respondent":"中島防災課長","answer":"今回一定程度大幅リニューアルになりますので、新規職員の採用等も見込まれますので、今回予備は設けております。","voiceIndex":54,"id":"exchange-019"}]},{"id":"topic-03","title":"第６０号議案、第二戸越幹線整備工事（北品川立坑）請負契約","agenda":"第６０号議案、第二戸越幹線整備工事（北品川立坑）請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"この工事の場所と、工事が終わった後の話なのですけれども、子供の森公園の隣接地ということですけれども、ここは今何があるというか、誰の土地というか、ちょっと私は詳しくないので教えていただきたいのですけれども、ただ、いずれにしろ立坑工事なので、工事が終わったら埋め戻して平らになると思うのですけれども、そこは今後どういう計画になるのか、もしわかれば教えてください。","respondent":"松本河川下水道課長","answer":"工事する場所ですが、ここは第一三共跡地でございまして、広町一丁目周辺地区の地区計画に基づき施設の集約化が進められて、未利用地が生まれたため、同社の意向により地域貢献として区に寄附された形になっておりまして、跡地利用につきましては。","voiceIndex":70,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"もしお答えできたら、区の土地だということはわかったのですけれども、更地にした後の動きはどのような感じなのか、概要だけでいいので教えていただけますでしょうか。","respondent":"柏原企画調整課長","answer":"こちらの土地と隣接しています子供の森公園というところがありますので、そういったところの公園の整備も含めて活用していきたいということで考えているところです。","voiceIndex":72,"id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"時間軸がちょっとわからないのですけれども、ここに児童相談所ができると思うのです。それに伴って子供の森公園も変わると思うのです。この工事が終わって更地にしてから児童相談所設置が始まって、それが終わってから、子供の森公園の整備なのか、これは玉突きでいろいろされると思うのです。そこの順番がちょっと見えていないので、そこをまず整理させてもらっていいでしょうか。","respondent":"柏原企画調整課長","answer":"ですので、ちょうどこの子供の森公園の中、これでいいますとこの契約のほうの資料の２６ページ、ちょっと小さくて恐縮ですけれども、今回の立坑の工事だけがその丸がついている、先ほど説明のありました第一三共からいただいたところであるのですが。","voiceIndex":74,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"スパンが長くてよく見えないところがあるのですけれども、多分ここはこれからになるのでしょうけれども、児童相談所を設置するときも、道路の関係も出てくるのかなと思うのです。児童相談所ができて、それが終わってから子供の森のほうも整備するという形になるのですけれども、全体的・一体的なここの計画というものをやはり示していかないといけないのではないかと思うのですが、いかがですか。","respondent":"柏原企画調整課長","answer":"こちらの工事もありますので、その部分についても説明というのはたしかされていたと聞いておるのですけれども、トータルでどういったことになるかというのは、改めてわかりやすいような形で説明が必要かと思いますけれども。","voiceIndex":76,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"それはわかっているのです。なので、そこをトータルで、将来的にはもう１０年先かもしれないけれども、こういうものができて、こういう形になりますよという計画をしっかり示していくということは必要なことだと思うのです。お知らせをしていただきたいと思いますので、これは意見とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"今回、大成・松本建設共同企業体なのですが、共同企業体ですけれども、松本組なのですが、立坑をやっていく工事に対して、松本組は専門的なそういうノウハウはお持ちなのですか。ちょっと見解だけお聞かせください。","respondent":"立木経理課長","answer":"なおかつ、第２グループに入る際にも、きちんと工事実績等といったものも出していただいているということになっておりますので、そこの部分に関しましてはきちんと履行がされるものと判断しております。","voiceIndex":79,"id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"一般の区民の方にもわかりやすいのかどうかわからないのですが、少し違和感を感じたので質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"賛成です。１つ意見を言わせていただきたいのですけれども、このような簡単な工程表でも、あるだけその後スケジュールの確認もできることなども考えて、ありがたいと思います。このような工程表を示していただけると、もっと思いを込めて賛成と言えるので、ぜひほかの事業でもそうなるといいと思いながら賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-027"}]},{"id":"topic-04","title":"第６１号議案、鮫浜小学校校舎改築その他工事請負契約、(12)第６２号議案、鮫浜小学校校舎改築その他機械設備工事請負契約および(13)第６３号議案","agenda":"第６１号議案、鮫浜小学校校舎改築その他工事請負契約、(12)第６２号議案、鮫浜小学校校舎改築その他機械設備工事請負契約および(13)第６３号議案","exchanges":[{"speaker":"田中委員","kind":"質問","question":"第６１号議案の辞退された方と無効になった方の理由はわかりました。落札されていないこの２番の方との差は金額だったのかということと、あと、３３ページの第６２号議案と、３６ページの第６３号議案も、辞退理由以外の説明がなかったので、その説明をお願いします。それともう一点、２９ページの改修工事の中で、校庭の整備で人工芝があります。","respondent":"立木経理課長、若生学校施設担当課長","answer":"ですので、こちらの調書のほうで特に金額の面でご説明をしないのは、一番金額が低い事業者が落札者となるという原則に基づいているものですので、そういった意味でご説明は省略させていただいたものです。１点目、外構工事の中で人工芝の面積ですけれども、今回整備する鮫浜小学校のグラウンド、これは立体的に京急の下の部分、それからその奥の飛び地といいますか、京急の外側も含めて人工芝にする予定でございまして。","voiceIndex":98,"id":"exchange-028"},{"speaker":"田中委員","kind":"質問","question":"人工芝のことです。その暑さ対策では何かしらの質の確保で、少しでも低減されるということでよろしかったでしょうか。ただ、その静電気に関しては、実際小学校で使われている長いロングのほうだと静電気が発生しやすい。それとも人工芝の質によって、改善されたのかという部分をもう一度お知らせください。","respondent":"若生学校施設担当課長","answer":"ただ、短いほうだと砂を入れたりとかいうのもありまして、そこである程度放電されている部分ももしかしたらあるのかなということで、静電気対策については各メーカーの質問に挙がってきているので、一定程度改良はしているところであるのですけれども。","voiceIndex":101,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"予定価格を提示しているわけですから、ほかでも価格が超過したので辞退と言われてきたと思うのですけれども、無効というのは例えばうがった見方をすれば、この積算では、区のほうが出した予定価格では到底難しいよということをあえて言いたかったのか、何か意図的なものがあるのかなというちょっとうがった見方になってしまうのですけれども、なぜ無効という形を知りつつも出されたのか。","respondent":"立木経理課長、若生学校施設担当課長","answer":"ただ、明らかに予定価格を超えているということは事実でございましたので、無効とさせていただいたという形になってあります。学校周辺が非常に狭いところでの安全性の配慮についてです。工事の前には必ず近隣対象に説明会を行っておりまして、前回１２月には、これから準備工事等入るということ、仮設の建設が始まるということで、説明会を行いました。","voiceIndex":103,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"契約のほうはいろいろな事情があったのだろうと思っていますけれども、それで、鮫浜小学校は事故のないようにぜひ配慮していただきたいということと、それから確認なのですが、仮校舎をこの敷地内で建てて、壊しながらやるという形になっているのでしょうか。","respondent":"若生学校施設担当課長","answer":"敷地内のほうに仮設を建てる計画で、もう現在ほぼ建ち上がっている状態です。場所としてはこの３０ページの下の配置図のほうを見ていただきますと、上側に京急の線路が通っている、その上側の飛び地のようなところに仮設を建てていく形です。","voiceIndex":106,"id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"そうすると特別教室を京急の上側に、校舎は現存のところを使いながらということですか。一気に壊して一気に建てるという方法を使ったほうがお金がかからないのではないかというようなことも言われている中で、今回はそういうことではなく、子どもたちがいる中で、壊しながら移動しながら順次やっていくという方法を使われているのでしょうか。その理由は何でしょうか。","respondent":"若生学校施設担当課長","answer":"ご指摘のありました、仮設をどんと建てて一気に移してというようなやり方も１つあると思います。経済性といいますか、費用に関しては、仮設を建てるとなると、やはりリース料も一定かかってくるというのもあります。","voiceIndex":108,"id":"exchange-032"},{"speaker":"須貝委員","kind":"質問","question":"これだけ入れば、単純に見て一般的に言えば工事費は増えてしまう。そうしたら、この３社という意味合いが何かマイナスに捉えられ、工事費は高くなる、それから建設もうまくいくのでしょうかという疑問さえ抱かせてしまう。経理課はこういう入札をしているのですが、これでいいのですか。せいぜい２社ぐらいだったら何とかわかるのですが、これはどのようなわけでこういうふうになっているのですか。","respondent":"立木経理課長","answer":"そういったことで、あとは工事の進捗管理等に関しましても、きちんと第１グループのほうで専任技術者を置いてコントロールするというところで、それによりまして何か齟齬が出るようなことはないと考えております。","voiceIndex":110,"id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"それが１点と、それとあと、せいぜい本体と、それからもう一社ぐらいならば、その話合い云々でここは任せて、ではここはお願いするよというのは、比較的工事計画も、また建設工事もスムーズに進むかなとは思うのですが、３社も入ってしまうとこれはどうなのですか。実際全然動けない企業も出てくるのではないかという疑問すら感じるのですが、その辺についてちょっとお聞かせください。","respondent":"立木経理課長","answer":"工事の進捗、工程管理に関しましては、きちんと区ともやり取りをいたしまして、工事監理の委託も入っている中では、そこのところはしっかりできているものと考えております。","voiceIndex":112,"id":"exchange-034"},{"speaker":"須貝委員","kind":"質問","question":"最後、意見だけ言わせていただきます。先ほどからいろいろお話で技術的なノウハウを移転する、習得するというお話ですが、本来プロに任せているわけですから、勉強なら勉強で別の機会で事業交流を進めるのが本筋だと私は思うのです。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-035"},{"speaker":"小芝委員","kind":"質問","question":"この鮫浜小学校は区民の避難所として、今、鮫洲の曙町会、北町会、南町会、大井元芝町会、大井北浜川東町会、北浜川仲町会の人たちが避難所として使われると思うのですけれども、工事期間中はどのような扱いになるのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-036"}]},{"id":"topic-05","title":"第６４号議案、城南小学校・幼稚園外構整備その他工事請負契約","agenda":"第６４号議案、城南小学校・幼稚園外構整備その他工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"制限付き一般競争入札ではなく、随意契約とした理由をお教えいただきたいと思います。","respondent":"立木経理課長","answer":"ご説明が足りませんで申し訳ございません。","voiceIndex":150,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"今のご説明ですと、学校の工事にかかわるいわゆる外構整備は基本的に随意契約となるということなのか、それとも今回に限ることなのか。契約に基本的なことというのも、その都度きちんと契約をするというのはもちろん精神ではありますけれども、学校の外構工事というのは基本的にそういう考えが多いということなのか、そこをご説明いただきたいと思います。","respondent":"立木経理課長","answer":"ちょっと今回の件に関しましては、先ほど申し上げましたとおり、安全性の面とか瑕疵担保の部分でこちらのほうが有利と判断いたしました結果、こういうことになったということですので、あくまでも原則は一般競争入札ということで分けしています。","voiceIndex":152,"id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"いや、私が伺ったのは、基本的には一般競争入札なのだけれども、学校における外構の工事というのは検討はするけれども、結果として随意契約になることが多いということなのか、そうでないものもあり得るのか、そこをご説明いただきたいと思います。","respondent":"立木経理課長","answer":"大変失礼いたしました。学校の工事に関しましてもほかの工事と同じでございまして、学校だから特に外構工事は随意契約が多いかと言われると、そういったことでもなく、やはりケース・バイ・ケースで判断させていただいているというところがあります。","voiceIndex":154,"id":"exchange-039"},{"speaker":"田中委員","kind":"質問","question":"ご説明にあったのですけれども、今、中塚委員が質問しなかったら説明をされなかったというのは、ちょっとどうかなと思います。資料として、どうして随意契約になったのか、この情報公開請求した中身も最初から資料としてあればこのような質問もしなくて済んだので、ぜひ前向きにその理由とかを書いていただけるといいかと思います。","respondent":"立木経理課長","answer":"工事が進んでいく中で今回このような判断になったという、外構工事を発注する段になって、一定こういう形で考えが及ばなかったというところが出てきたというところで随意契約になったと、そういうふうに判断をしています。","voiceIndex":156,"id":"exchange-040"},{"speaker":"田中委員","kind":"質問","question":"最初の本体工事では一般競争入札だったということはわかりました。ただ、だからなぜ最初のときに、外構整備も含めた契約とならなかったのだろうと。何かちょっと理解が、もう一回説明していただいていいですか。なぜ随意契約になるのか全然わからないので。最初の時点でもうわかっていたことではないのかなと思います。","respondent":"若生学校施設担当課長","answer":"というのも、外構まで含め一本にしてしまうと、外構の部分の金額がどうしても下がってしまうので、出来形で後ろから２年となると、その分補助金の金額というのも下がってきてしまうという事情もちょっとありまして。","voiceIndex":158,"id":"exchange-041"},{"speaker":"須貝委員","kind":"質問","question":"ちょっとお聞きしたいのですけれども、外構工事で６億９,３００万円となっています。何かそのツケと言ったらおかしいのですが、これがこの契約金額、約７億円近い額で出ているというのは、ちょっとほかの学校でもそうですが、この広さで７億円近いというのはかなり高いと思うのですが、その根拠は何なのでしょうか。教えてください。","respondent":"若生学校施設担当課長、小林施設整備課長","answer":"外構の契約金額というのは、基本的には工賃の標準単価を積算しております。もう一つは、建築工事等の労務費がやはり近年上がっている部分もあります。そういったことで、コストが若干上がっている部分もあります。それで、既存の校舎を活かしながら今回工事をやっておりますので、仮設の校舎というのが極力少ないというところで、費用対効果を考えてそのようにやっておりますので、グラウンドをつくるだけではなくて。","voiceIndex":160,"id":"exchange-042"},{"speaker":"須貝委員","kind":"質問","question":"そうことですか。解体ということで、わかりました。通常我々一般的には、もう外構工事というのは地面のままで工事していくということですが、そういう意味で今回違っていた。ですから、その解体費用もここに上積みされてというような考え方ですね。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":163,"id":"exchange-043"}]},{"id":"topic-06","title":"規模改修工事請負契約、(5)第５５号議案 東品川文化センター・シルバーセンター大規模改修機械設備工事請負契約および(6)第５６号議案 東品川文化センター","agenda":"規模改修工事請負契約、(5)第５５号議案 東品川文化センター・シルバーセンター大規模改修機械設備工事請負契約および(6)第５６号議案 東品川文化センター","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"１点だけ。今回の工事をすることによって、東品川文化センター・シルバーセンターで今まで行ってきた事業に何か変更があるのか、その点だけ確認します。","respondent":"古巻文化観光課長、宮尾高齢者地域支援課長","answer":"今回の工事の結果によって文化センターに関しまして事業に変更は特にございません。現在、東品川シルバーセンターとして運営をしていますが、この大規模改修工事を契機に、高齢者多世代交流支援施設「ゆうゆうプラザ」への転換を図ろうというふうに考えてあります。","voiceIndex":180,"id":"exchange-044"},{"speaker":"田中委員","kind":"意見","question":"６ページの第５５号議案ですけれども、７ページにある入札のところで、ここに関しては辞退の理由が述べられなかったので、その部分をお知らせください。そして、午前のときにも伝えたのですけれども、全体の工期が書かれていたほうがいいと思っていまして、なぜ書けなかったのかという理由をお知らせください。","respondent":"立木経理課長","answer":"７ページの東品川文化センター・シルバーセンター大規模改修機械設備工事の辞退理由ですが、調書、４番のこちらの会社の辞退理由は、積算金額が予定価格を超過したものによるものです。","voiceIndex":183,"id":"exchange-045"},{"speaker":"田中委員","kind":"確認","question":"尋ね方が悪かったです。工程表を用意していただければということを午前中も話しました。この理由が、障害児者総合支援施設の建設の工期がおくれてしまったこともあります。工期の全体の流れが見える工程表があれば、スケジュールの確認もできることから、点検をしていきたいという意味です。何かご意見があればお願いします。","respondent":"立木経理課長","answer":"ただ、後ろが決まっておりますので、それにあわせて工期をつくり込んでいくという形になりますので、詳細な工期につきましては、今後できてくるものなので、現時点ではお知らせすることができないという形になっております。","voiceIndex":185,"id":"exchange-046"},{"speaker":"田中委員","kind":"質問・要望","question":"結論は賛成はするのですけれども、きちんと点検をしてから決定をしたいと思っていますので、これからの資料に関しては、ご事情もわかったのですけれども、ぜひ納得して決定ができるような資料を提供していただければと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":187,"id":"exchange-047"},{"speaker":"西本委員","kind":"確認","question":"それと、５階から上は都営住宅になっているものです。電気工事とか防水とかになったときには、ビル全体を考えた改修という形になるのではないかと思うのですけれども、そこら辺はどうなのか、水回りとかというのは、同じ建物なので同じになるのではないかと、１階から４階までの改修だけで済むのですかということが不思議なのですけれども、この辺はいかがですか。","respondent":"小林施設整備課長","answer":"ゆうゆうプラザのほうについても、基本的には今の間仕切りだとか、そういう平面図関係については、多少は変わりますけれども、大きな変更はございません。","voiceIndex":189,"id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"多世代というのはいいのですけれども、そこの理解はどうなのだろうという、今まで使えていたものが使えなくなったり、それから、多世代という意味では、ご理解していただける方ばかりではないと思うのです。そういう配慮をした上での今回の改修という形の理解でよろしいのでしょうか。","respondent":"宮尾高齢者地域支援課長","answer":"今、施設をご利用中の高齢者の方が、この改修を機にご不便を感じることのないように、利用者向けの説明会も４月に開催をさせていただいて、意見交換もさせていただいたところです。","voiceIndex":191,"id":"exchange-049"},{"speaker":"西本委員","kind":"質問・要望","question":"今までと違う使い方になる、建て替えをして、それなりにきっちりと役割分担とかでスペースを区切ったりするのだったらいいのですけれども、そこまで大きな改修ではないと思っているので、そうなってきたときのイメージとか、今までの方々が、結構あそこは憩いの場になっているものですから、せっかくの憩いの場が崩されるような感覚になってしまうと困るし、かといって、では、ほかの子育て中のお母さんたち。","respondent":"宮尾高齢者地域支援課長、小林施設整備課長","answer":"私からは、まず、４月に開催させていただいた利用者向けの説明会の中で主に出た意見といたしましては、やはり今回、工事期間が約１０カ月ほどかかる中で、ほぼ基本的には全館休館となる中で。そういうところもありますので、基本的には機械室で集中管理をする。ただ、基本的には、そういう個別の温度設定が多分できると思いますので、そこら辺を注意しながら進めてまいりたいと思います。","voiceIndex":193,"id":"exchange-050"},{"speaker":"つる副委員長","kind":"質問・要望","question":"今、各委員からありましたけれども、それはそれでしっかりとやっていただきたいという上で、何度かオリンピック・パラリンピック推進特別委員会でブラインドサッカーとかでもお邪魔しているところなのですが、建物の躯体のつくりが、先ほど質疑があったのですが、１点確認したいのですけれども、これ、今回、区として改修する１階から５階部分と、都営住宅の部分は、躯体は全体としてつながっているのか。","respondent":"小林施設整備課長","answer":"建物自体は一体の建物です。１階から５階までが文化センターで、その上に都営住宅がまたちょっと複雑にもう１個あるのですけれども、基本的には１階から５階は重層で系統は一緒です。","voiceIndex":196,"id":"exchange-051"},{"speaker":"つる副委員長","kind":"質問","question":"単純な考え方なのですが、このあたりについて、今回これをやっていただいて、ゆうゆうプラザ、文化センターとしてリニューアルされていくのはいいのですが、１５年というスパンで考えているのか、それともそれと違う東京都とのいろいろなやりとりがあって、それ以外の考えがあるのか、このあたりを教えてください。","respondent":"小林施設整備課長","answer":"今の１５年の考え方ではなくて、今現在で全体をリニューアルしますので、ここから何年という形になります。","voiceIndex":198,"id":"exchange-052"},{"speaker":"つる副委員長","kind":"確認","question":"ちょっと確認なのですが、今、耐震補強済みだと、長寿命を図ると、通常、何もしなければ平均５０年というざっくりな平均値があって、大体６０年とか６５年とかという長寿命の部分があるのですが、長寿命を図っている中で、そうすると、全体の躯体として、あとどのぐらい大丈夫という計算になるのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":200,"id":"exchange-053"},{"speaker":"つる副委員長","kind":"確認","question":"そうすると、あと大体１５年とか１６年というぐらいの感覚でいい。つまり、全体の寿命を延ばして６５年になったということですね。そうすると、今回、品川区の部分を改修しても、１５年後から１６年後ぐらいには全体をまたやらなければいけない状況になるのかどうかという確認です。","respondent":"小林施設整備課長","answer":"そちらの関係で設備関係が空調も含めて早急に改修することが望まれるというか、そこら辺まで設備のほうが耐用年数が少なくなってしまっていて、至急にやらないといけないという状況になっておりましたので、今現在そのまま手をつけないと、１５年もつかというと。","voiceIndex":203,"id":"exchange-054"},{"speaker":"中塚委員","kind":"質問・要望","question":"賛成しますが、一言。今のやりとりで、東京都、つまり、都営住宅を含めてよく連携をとっていただきたいと思いました。もちろん東京都が責任を持って工事を進めるわけですけれども、建物が一体化している以上、区は都とよく連携をとってやっていただきたいと一言意見を述べて賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":209,"id":"exchange-055"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっと意見だけ申し上げたいと思います。先ほど、都営住宅の件もありました。これは予測なのですが、もしかしたら都営住宅のあり方も見直しが図られる可能性も将来的にはあるのかと、そうなったときに、今工事をしなければならない現状はわかりましたので、この契約は必要だと思いますけれども、将来にわたってはここを広い意味での視野を持った形で見ていただきたいと思っています。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":230,"id":"exchange-056"}]},{"id":"topic-07","title":"第５７号議案 南ゆたか保育園・児童センター改築工事請負契約","agenda":"第５７号議案 南ゆたか保育園・児童センター改築工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"南ゆたか保育園・児童センターの改築工事ですが、工事が必要な理由、目的を改めて伺いたいと思います。それと、この前の予算特別委員会の中で、園庭が狭くなるという話は伺っておりますが、園庭が減った分、子どもたちの保育をどのようにカバーしていくのかも伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"工事の目的ですけれども、南ゆたか保育園・児童センターの老朽化、建設後約５０年程度たっているところがありまして、耐震等は十分に対応しているところではありますが、施設の老朽化を含めまして、今回、建て替えを行う次第です。","voiceIndex":236,"id":"exchange-057"},{"speaker":"中塚委員","kind":"質問","question":"園庭が減った分、近隣の公園を使うということですけれども、近隣の公園が増えるわけではないので、そういう意味では、子どもたちにとって園庭が減った分の対応としては足りないと思うのですけれども、近隣に公園を確保するとか、そういう考えはあるのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"近隣の公園の確保ということですけれども、保育園の場合、敷地内に必要面積の園庭が確保できない場合、近隣の公園を代替遊戯場とすることができます。それを含めまして、保育園の園庭の面積必要数を確保するということはできるところです。","voiceIndex":238,"id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、園庭が少なくなった分、新たな公園の整備を進めていく考えはあるのかと伺いましたので、その点、伺いたいと思います。","respondent":"柏原企画調整課長","answer":"例えば、保育園の改修のたびに公園を増設できるかというと、なかなか土地が出てこない、そういった状況もありますので、その周りのいろいろな状況を見ながら、公園の整備であったりとか、それから、そういう建物の整備は総合的に両方にらみながらですけれども。","voiceIndex":240,"id":"exchange-059"},{"speaker":"西本委員","kind":"確認","question":"南ゆたかは民営化になるのではなかったでしたか。そこをまず確認です。","respondent":"吉田保育施設調整担当課長","answer":"南ゆたか保育園は、民営化の対象にはなっておりません。","voiceIndex":242,"id":"exchange-060"},{"speaker":"西本委員","kind":"質問","question":"建築の新しい基準がありますから、当然、園庭は狭くなるというのは仕方ないことかと思うのですけれども、多分、隣の防災広場も園庭としてカウントされているのかと思うのですが、その考え方をお聞きしたいと思います。児童センターのスペースは広がるのでしょうか。階層を増やすのはもうできないと思うのですけれども、広さがもうちょっとあってもいいのかなと思うのですが、いかがですか。","respondent":"吉田保育施設調整担当課長、廣田子ども育成課長","answer":"防災広場のところにつきましては、２歳以上の子ども掛ける３.３m2という形での園庭の確保が必要になります。本園の園庭で確保できない部分につきましては、隣の防災広場を代替遊戯場という形で設定することで進めているところです。３階部分につきましては、大体６６m2ぐらい、若干広がる予定で、エレベーターもつくという形で若干広くなります。","voiceIndex":244,"id":"exchange-061"},{"speaker":"西本委員","kind":"質問","question":"児童センターもありますし、そういう意味で、例えば新しい園舎に桜の木を使って子どもたちと一緒につくりましたみたいなものをされると、地域の方、ＯＢの人たちもとてもうれしいのではないかと思いますが、いかがですか。","respondent":"吉田保育施設調整担当課長","answer":"５月まで保育園はやっておりました。保育園はそこまでは保育をやっていた関係で、なかなかタイミングがうまく合わなかったところがありまして、それを今、地元の町会と話しまして、何かできないかというところで、今詰めているところです。","voiceIndex":247,"id":"exchange-062"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、質疑にもありましたとおり、桜の木が愛されていたり、その後の活用についても住民とよく話をしていただきたいと思いますし、新たに植える桜がまた地域のシンボルとなりますようお願いしたいのと、園庭が狭くなるということですので、できるだけ近隣に新たな公園を整備して、子どもたちの保育環境をしっかりと整えていただきたいと意見を述べまして、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":253,"id":"exchange-063"},{"speaker":"田中委員","kind":"意見","question":"賛成ですけれども、生活者ネットワークも園庭が小さくなってしまうことは、子どもたちの運動量などがやっぱりちょっと不安でして、保育環境が、狭くなってもきちんと保育の質が確保されて、子どもたちの運動量も、それによって体力が低下してしまったとか、そのようなことがないように、きちんとやってほしいと思います。賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":255,"id":"exchange-064"}]},{"id":"topic-08","title":"第５８号議案 八潮北保育園大規模改修工事請負契約","agenda":"第５８号議案 八潮北保育園大規模改修工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"同じく八潮北保育園の大規模改修工事を行う目的や理由は何か伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"八潮北保育園の改修にかかる理由と目的ですけれども、理由は、建設後３０年ほどたちまして、こちらに八潮独特の熱交換システムというのがありまして、それを空調の冷暖房に使っております。","voiceIndex":262,"id":"exchange-065"},{"speaker":"中塚委員","kind":"意見","question":"熱交換システムの改修というのは、大体３０年ぐらいが１つの目安になるのか、八潮全体でこの熱交換システムが入っているだけに、３０年というのが、ここが特別早いのか、それとも１つのめどになるのか。","respondent":"小林施設整備課長","answer":"約３６年ぐらい経過しておりますけれども、去年も八潮わかば幼稚園をやって、所管のほうで４つの施設を計画的に改修する計画を立てておりますので、その第二弾ということで、八潮北、本件の大規模改修が計画されたです。","voiceIndex":264,"id":"exchange-066"},{"speaker":"中塚委員","kind":"質問","question":"熱交換システムの工事の必要性はわかりました。最後に、既に八潮北保育園について、業務委託を経て民営化の方針が出されておりますが、今回の改修工事と民営化は、どのような関係にあるのか伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"そのため、今回、改修工事等を行う八潮北、今後行う予定の八潮西につきましても、同様に民営化を進める予定でいるところです。","voiceIndex":266,"id":"exchange-067"},{"speaker":"田中委員","kind":"質問・要望","question":"ちょっとしつこく申しわけないのですけれども、辞退理由をお聞かせいただきたいのと、あと、午前中の質疑でもあったのですけれども、小学校の校庭の人工芝生について聞きました。その辺をどのように対策を考えられた契約になったのか、それで妥当な工事費だったのかということもお知らせください。","respondent":"立木経理課長、吉田保育施設調整担当課長","answer":"調書の５番の会社の辞退理由は、先ほど申し上げましたとおり、配置予定技術者の都合がつかなくなったことによるものです。そういうところで、今回、大改修をやる際に、何か対応ができないかというところで、園庭の砂の入れ替えだとかもいろいろ考えましたところ、砂対策として最もいいところが人工芝化ではないかというところと、あとは、水はけのよさだとか。","voiceIndex":269,"id":"exchange-068"},{"speaker":"田中委員","kind":"意見","question":"それに対して、今回どのような検討がされて、それよりも砂ぼこり対策のほうに決定が至った理由といいますか、そこら辺の対策、さっき、小学校のほうでは、静電気とかもやっぱり対策はなく、水をそのとき一時的にまくことや、校舎の壁を触って静電気を抑えるという対策しかなかった、そういうことだったのだけれども、小さな子どもたちが利用したときに、そのようなけがにつながったりとか。","respondent":"吉田保育施設調整担当課長","answer":"それと、保育園の子どもなので、一番大きくても５歳児です。小学校や中学校ほどの運動量はないものと考えております。そのため、一定程度の安全性は確保できるものというふうに考えたところです。","voiceIndex":272,"id":"exchange-069"},{"speaker":"田中委員","kind":"質問・要望","question":"小さな子どもたちでも、動き回ったら、やっぱり静電気も発生しますし、夏場の熱さというのは小学生より小さいとかはあまり関係ないと思うので、そこら辺の対策をきちんとしていただきたいのと、子どもたちから人工芝にした後にも、やはり声を聞き取っていただきたい、そして対策をしていただくような工事になるといいと思います。","respondent":"吉田保育施設調整担当課長","answer":"夏場の熱さについて、確かに懸念するところではあります。ただし、そこは砂のときも一緒だったのですけれども、常時水をまくというようなことで対応を予定しています。","voiceIndex":274,"id":"exchange-070"},{"speaker":"須貝委員","kind":"質問","question":"今回の入札で落札されたところは、１社ということですね。だったら、ほかも恐らくそういうふうにできるのに、ほかは２社、大きな規模は３社とあるのですが、これがちょっと不思議に感じたのですが、どう思われますか。","respondent":"立木経理課長","answer":"こちらの中の規定で、建築工事は予定価格が４億円以上のもの、土木工事も同じく４億円以上のもの、造園工事、設備工事に関しまして、予定価格が１億３,０００万円以上のものは、基本的には建設共同企業体で発注をするというふうにしていることから。","voiceIndex":276,"id":"exchange-071"},{"speaker":"西本委員","kind":"質問","question":"１階の部分が保育園ですね。２階、３階は、たしか都営住宅ということですね。都営住宅もかなり老朽化しているのではないかと思うのですけれども、全体の改築時期は、どういうふうに見立てたらいいのでしょうか。","respondent":"小林施設整備課長","answer":"そのために計画的に八潮、４つの園、こちらのほうの大規模改修を行って、設備がメーンで改修工事を行うということで、建物は鉄筋コンクリート造というと、今現在、６５年だとか、そちらから今度、もう少し長寿命化を図ってもたせるとか、そういう発想も今持っておりますので。","voiceIndex":278,"id":"exchange-072"},{"speaker":"西本委員","kind":"意見","question":"今、３６年目、東京都の動きとして、都営住宅を縮小するという傾向にあると思うのです。その場合に、都営住宅としての役割も変わる可能性もある。同じ建物になっているから、当然ながら、品川区は八潮北保育園という機能を持った施設が入っている。今度、民営化をする。そうなってくると、都営住宅がこれから先どうなるかわからない。用途が変わるかもしれない。そこら辺はどう考えられていますか。","respondent":"吉田保育施設調整担当課長","answer":"八潮の人口の関係ですけれども、就学前人口につきましては、今、若干微増の状況で、ここ数年増えているところです。しばらく続くのではないかというふうには見ておりますので、著しく八潮で保育園が余るようなことは、今のところはないというふうに認識しています。","voiceIndex":280,"id":"exchange-073"},{"speaker":"西本委員","kind":"質問・要望","question":"だから、それを含めて、民営化は１つの方法かもしれないですけれども、将来にわたっての保育園のあり方、あそこ一帯、八潮北保育園、そして都営住宅がどうなっていくかというのは、ちゃんと見ていかないと、結局子どもが少なくなってどうしようもなくなってしまうような状況にはしてほしくはないと思っているのですが、そういう将来にわたっての見通しをぜひとも見ていただきたいと思うのですが、一応。","respondent":"吉田保育施設調整担当課長","answer":"八潮における民営化の検証ですけれども、やはりこちらはしっかりやっていかなければいけないと考えていますので、検証をある一定、どのぐらいの期間でやるかというのはこれから検討していくところではありますけれども、一定の期間は公設民営という形で検証を行っていく予定です。","voiceIndex":282,"id":"exchange-074"},{"speaker":"西本委員","kind":"質問・要望","question":"まとめますけれども、目先のことだけではなくて、やはり一体施設になっているわけです。社会の動き、人口動向も含めて、トータル的に５年後、１０年後となるかもしれませんけれども、その見通しを立てた形で計画を進めていく。そうしないと、税金のむだ遣いになってしまいますので、ここを考慮していただいて、今後検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":284,"id":"exchange-075"},{"speaker":"中塚委員","kind":"質問・要望","question":"今のやりとりの中で、一定の間、公設民営をしていきたいと、検証の中身がご説明がありましたが、この八潮北保育園に関して、民間に譲渡する考えがあるのか、ないのか、そこを伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"ある意味、十分検証の時間をとって検討した上で、その後、そこを公設民営からどうしていくかというのは、その後の問題になって、まだ検証もしていない段階で、譲渡するとか、どうしますというのは、ちょっとまだ先の早い話かなというふうに認識しています。","voiceIndex":285,"id":"exchange-076"},{"speaker":"中塚委員","kind":"質問","question":"その後のことだと、まだ先のことだとおっしゃるということは、検証の結果、民間に売却する、譲渡するということは、選択肢の１つにはあるということなのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"検証した後に出てくる結果としての話は幾つか考えられるとは思いますけれども、ただ、検証もまだ行っていない段階で、譲渡するとかしないとかというところを、この場で申し上げるのは時期尚早のものと考えます。","voiceIndex":287,"id":"exchange-077"},{"speaker":"中塚委員","kind":"質問・要望","question":"区民の財産を企業のもうけのために譲渡する、売却するということは、あってはならないと思いますので、その方針は変えていただきたいと意見を述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":289,"id":"exchange-078"},{"speaker":"田中委員","kind":"確認","question":"先ほどの私とのやりとりの中で、この八潮地域は砂ぼこりが立ちやすいという話で、八潮の中では人工芝にしていくというお話でした。小学校では、改築のときにあわせて人工芝にしていくということなのですけれども、保育園では、そのような方針は特に立てていないということで確認したいのですけれども、大丈夫ですか。","respondent":"吉田保育施設調整担当課長","answer":"残りが園庭みたいな形になりますので、その場所によって人工芝がいいのか、そのままでいいのかというところは、これは今後、改築を何園か進めていく中での検討材料かと考えています。","voiceIndex":290,"id":"exchange-079"},{"speaker":"田中委員","kind":"質問・要望","question":"改築のときにそういう議論がされるときには、ぜひ保護者など、かかわる全ての人との協議の場が持たれることを要望したいと思うので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":292,"id":"exchange-080"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただし、その先に品川区のコストを下げるために民営化を進め、官製ワーキングプアをつくったり、また長く働き続けることができない企業体系になったりなど、民営化や、ましてや区の施設を民間に売却する、譲渡する、こういう方針はやめて、引き続き、直営で運営すべきだと意見を述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":297,"id":"exchange-081"},{"speaker":"西本委員","kind":"質問・要望","question":"先ほども意見を申し上げましたけれども、これからの動向をきっちり見ていただいて、そしてどういう施設がいいのか、どういう施設になっていくのか、広い視野に立って考えてください。それから、民営化の検討見直しを含めて検討していただきたいという意見を述べて、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":300,"id":"exchange-082"}]},{"id":"topic-09","title":"第３７号議案 品川区情報公開・個人情報保護条例の一部を改正する条例および(2)第３８号議案 品川区行政不服審査法施行条例の一部を改正する条例","agenda":"第３７号議案 品川区情報公開・個人情報保護条例の一部を改正する条例および(2)第３８号議案 品川区行政不服審査法施行条例の一部を改正する条例","exchanges":[{"speaker":"西本委員","kind":"質問","question":"中身は変わらない。名称が変わるということですが、なぜ工業と産業と、何が違うのでしょうか、そこを教えてください。","respondent":"木村広報広聴課長","answer":"今回、国の改正の趣旨ですが、いわゆる工業製品、物の規格を定めているＪＩＳ規格、それに最近はデータとかサービスとか、そういう情報の部分のいわゆる標準規格みたいなものも一緒に扱おうということで、工業だけだと、ちょっと言葉が足りないといいますか。","voiceIndex":306,"id":"exchange-083"},{"speaker":"西本委員","kind":"質問","question":"そうすると、中身は変わらないということなんですが、一応、くくりが広がったということは、その内容も変わるところは全くないですということなのか、今後、変わる予定があるのか、その辺はいかがですか。","respondent":"木村広報広聴課長","answer":"何点か今回の法改正に伴いまして、ちょっと細かくて申しわけないのですけれども、実際にＪＩＳ規格は申請してから認められるまでの期間を短くする、そういうスキームをつくるであるとか、罰則を強化するであるとか、要は、より国際標準化に向けて合わせていくとか。","voiceIndex":308,"id":"exchange-084"},{"speaker":"西本委員","kind":"質問","question":"いわゆるＪＩＳ規格というと、保証された規格だというふうに思うのですけれども、ＪＩＳ規格があると信頼性があるということなのですが、ＪＩＳ規格という形での信頼性の度合いはそのままという形でよろしいのでしょうか。","respondent":"木村広報広聴課長","answer":"名前のＪＩＳ規格の「ＪＩＳ」は変わりません。信頼性そのほか、何かそれによって変わるというものではございません。","voiceIndex":310,"id":"exchange-085"}]},{"id":"topic-10","title":"第３９号議案 品川区特別区税条例の一部を改正する条例","agenda":"第３９号議案 品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"住宅ローンと軽自動車税についてですけれども、まず消費税１０％への対応だという、法改正に基づく条例の一部改正ということでありますが、共産党は、消費税１０％は今行うべきではないと、そして消費税ではない別の道があると、この間、本会議でも、またいよいよ始まる参議院選挙でも元気に訴えていきたいと考えていますが、政府が消費税１０％の中止を決断した場合は。","respondent":"伊東税務課長","answer":"現状では、引き上げがされるという形での税制改正の対策等ですので、それがもし変わるということであれば、その変わった地方税法を見ながら対応していくことになるかと思います。","voiceIndex":334,"id":"exchange-086"},{"speaker":"須貝委員","kind":"質問","question":"品川区にとって、これ以上マイナスにならないように期待をしていたところもあったのですが、この内容を見る限り、全く影響はないということですか。このまま不平等税制が続いていって、さらに、ふるさと納税、品川区に入ってくる歳入、区民税もより減ってくるという、そういう傾向は変わらないというふうに考えていなければいけないのでしょうか。","respondent":"伊東税務課長","answer":"ただ、返礼品を出すことはまかりならんという話ではございません。３割以下に抑えるとか、公平な周知方法をしなさいというような形で改正されたところです。ということで、全くふるさと納税の影響が尻すぼみになっていくかというと、都市部においては、そう簡単にはいかない。","voiceIndex":336,"id":"exchange-087"},{"speaker":"田中委員","kind":"確認","question":"項目の３番目の単身児童扶養者に対する非課税措置について確認ですけれども、対象を広げるということでよろしかったでしょうか。","respondent":"伊東税務課長","answer":"広がる、非課税措置の中に、単身児童扶養者が加わるという形になりますので、いわゆる未婚の状態でお子さんがいる方に関しては、そちらも適用されるということです。","voiceIndex":338,"id":"exchange-088"},{"speaker":"西本委員","kind":"質問","question":"ふるさと納税に関しまして、「指定は、都道府県等の申出」ということなのですが、品川区はどういう動きになるのでしょうか。品川区から東京都の担当のところに、こういう返礼品はいいでしょうかという申請をして、そこから許可が出ていく形になっているのでしょうか。東京都の査定の基準とか、あとは期間であったりとかということで、そこでのやりにくさとか、時間がかかるとかはないのでしょうか。","respondent":"伊東税務課長","answer":"とはいっても、この間、東京都の担当とも相談させていただいたり、東京都を通じて総務省に話をさせていただいたりという、そういう意味では、特にやりにくさというのはなくて、事務的に淡々と進めさせていただいたというようなことです。","voiceIndex":340,"id":"exchange-089"},{"speaker":"西本委員","kind":"確認","question":"今、問題になっている過剰な返礼品という形は各自治体がやっていますよね。今の現状だと、都道府県で振り分けをされているわけではないわけではないですか。ただ、改正になったということは、このアの部分を見ると、チェック機能の権限をそろえましょうということではないのでしょうか。１つだけ確認します。先ほど、２３億円というのは、今現在のところでしょうか。","respondent":"伊東税務課長","answer":"ですから、昨年寄附した人たちが今年の住民税に影響しているのが２３億円です。","voiceIndex":342,"id":"exchange-090"},{"speaker":"西本委員","kind":"質問","question":"そこをもうちょっと教えてください。２３億円というのは、今の見込み数値でいいのですか。それとも、現時点でもう既に２３億円がマイナスという認識でいいのですか。どう解釈すればよろしいでしょうか。","respondent":"伊東税務課長","answer":"多少申告の間違い云々というのはこれからあるかもしれませんけれども、当初賦課は終わっていますので、２３億円に関しては、今年度、いわゆる減収といいますか、細かい数字は別として、２３億円ほどは減収します。","voiceIndex":344,"id":"exchange-091"},{"speaker":"大倉委員","kind":"質問・要望","question":"ふるさと納税の件で、かなりの金額が流出していくというところで、こういった制度がまた新たに変わって、そういう意味では、多少の注目度やマスコミ等でも報道されるのかなとは思うのですが、そうしたところをうまく使いながら、シティプロモーションの観点、ふるさと納税とかの周知も含めた流出抑制というのは、やっていかなければいけないと思うのですが、流出抑制とあわせて。","respondent":"伊東税務課長","answer":"はクラウドファンディングというようなお話も皆様方のほうから出ているところですけれども、なかなか私のほうでは、事業化ということで難しいところはありますけれども、全庁的にはそういうものを取り入れて何かやろうかというような話を出しているところですけれども。","voiceIndex":346,"id":"exchange-092"},{"speaker":"大倉委員","kind":"意見","question":"流出抑制とあわせて、品川区の、まさに今、水辺の千本桜等で寄附が増えているところでは、あわせて一緒にこういったことも品川区はやっているので、皆さんで品川区を応援していきませんかというシティプロモーションの視点もあわせて、各課連携しながら一緒に、全庁的にというお話もあったかと思いますので、ぜひ前向きに取り組んでいって、流出抑制とあわせて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":348,"id":"exchange-093"},{"speaker":"中塚委員","kind":"意見","question":"ふるさと納税への規制は必要なものだと思います。そのほか消費税１０％を前提にすべきではないが、条例改正の中身は、住宅ローンや軽自動車など住民の負担を減らしたり、非課税措置の対象を広げたりとするものですので、賛成します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":353,"id":"exchange-094"}]},{"id":"topic-11","title":"令和元年請願第１２号 沖縄県民投票の結果を尊重し、対話による解決を求める意見書の採択を求める請願","agenda":"令和元年請願第１２号 沖縄県民投票の結果を尊重し、対話による解決を求める意見書の採択を求める請願","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"それで、品川区に１点伺いたいのですけれども、この請願書に書かれております地方自治の本旨に基づきということですが、沖縄の辺野古基地建設をめぐって県民投票が行われたり、県知事選挙が行われたり、そのほか繰り返し繰り返しの選挙で民意が示されていると思いますが、ここでいう地方自治の本旨とは、品川区は何を差していると思っているのか、その点を伺いたいと思います。","respondent":"立川総務課長","answer":"それを受けまして、地方自治法では、地方自治の本旨ということをうたっておりますが、この中身につきましては、地方自治の本来の趣旨という意味で、国の関与を排除して、住民自治の意思に基づいて処理するという原則でございまして、基本的には２つございまして。","voiceIndex":363,"id":"exchange-095"},{"speaker":"中塚委員","kind":"質問","question":"品川区に伺いますが、辺野古基地建設をめぐって、基地をつくるなという沖縄県民の民意、総意という地方自治が踏みにじられていると品川区は思うのかどうか伺いたいと思います。その意味で、今ご説明のあった地方自治の本旨に照らして、今、辺野古基地建設をめぐって起きているこの問題は、品川区は地方自治の否定だというふうに思っているのか、どう考えているのか伺いたいと思います。","respondent":"立川総務課長","answer":"区としての考え方ですけれども、外交や安全保障に関することですので、私どもといたしましては、国の専管事項に対しまして、これまでどおり発言は控えするものです。","voiceIndex":365,"id":"exchange-096"},{"speaker":"中塚委員","kind":"質問・要望","question":"私自身は、そもそも辺野古基地建設には反対です。決して沖縄県民は諦めません。しかし、今回の意見書提出については、この基地建設の賛成、反対を問うのではなくて、県民投票の結果を尊重して、また対話による解決を求めるものですから、それぞれ政党の立場が違いますが、この点では誰もが一致できる点だと思いますので、ぜひ各委員におかれましては、請願への採択を重ねてお願い申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":367,"id":"exchange-097"},{"speaker":"田中委員","kind":"質問・要望","question":"私もまず区からの説明はちょっとおかしいかなということを思いまして、むしろ請願者の方たちに趣旨説明というか、やはりそういう機会があって、お話を伺いたかったなということを思います。中塚委員もおっしゃっていたのですけれども、私としても、やっぱりこの工事、建設の続行はやめてほしいと思っているのですけれども、ただこの意見書は、あくまで対話による解決を図ることを求めている意見書です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":369,"id":"exchange-098"},{"speaker":"小芝委員","kind":"意見","question":"沖縄を守るのは日本です。今、沖縄の基地の問題で住民投票の結果はもちろん尊重されるべきことだとは思います。しかし、沖縄をめぐる、そして極東をめぐる安全保障の環境は刻一刻と変わっています。高度に政治性のある課題だと私は考え、対話による解決を図るということを国政に提出するということに対しては、私は反対の意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":371,"id":"exchange-099"},{"speaker":"西本委員","kind":"意見","question":"品川区議会としてという形だと思うのです。私たち議員はどういう立場かと考えたときに、やはり選ばれた４０人です。住民の皆さんの代表であり、声の代弁者であるということだと思うのです。賛成意見もあるわけです。その中で私たちが話し合いを進めてくださいというのはいいのかもしれないけれども、品川区としてはという意味でいうと、品川区の中での議論が深まっていないのではないかと私は考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":372,"id":"exchange-100"},{"speaker":"須貝委員","kind":"質問・要望","question":"実際、日本の中の、そして一番こういう基地が多い沖縄県のことで、県民の皆さんが、できればその中でもっともっと議論をして、国に訴えていただくということが、そこに住まわれている人の、自治もそうですが、やっぱり住民がそこにいらっしゃるわけですから、そこはそこでもっと議論を住民同士が重ねて、実際どうなのだということを先に話し合ってしかるべきことではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":373,"id":"exchange-101"},{"speaker":"中塚委員","kind":"質問・要望","question":"田中委員からもありましたが、ぜひ私は各委員の思いを伺いたいと考えています。率直に、それぞれの思いというか、意見を出し合って議論を深めていくことが大事かと思いますので、ぜひお聞かせいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":374,"id":"exchange-102"},{"speaker":"大倉委員","kind":"質問・要望","question":"一方で、辺野古移設に関して、司法のほうでもさまざま判断が出ていて、私たち区議会議員がまさに移設に関しても当事者意識を持って議員として考えなければいけないというのは、まさにそのとおりかなと考えていますが、国の外交、国防については、かなり高度な判断、国の専管事項ということで行政のほうからもお話がありましたが、ここで品川区の区議会の意見として意見書を出すというのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":376,"id":"exchange-103"},{"speaker":"つる副委員長","kind":"提案","question":"提案があったからというわけではないのですが、意見ということで、同趣旨の請願が２０１６年の議会運営委員会に出されて、そのときにちょうど私も議会運営委員として、請願に対して意見を述べさせていただきました。２０１６年のときもお伝えさせていただいたとおり、まさにそうした意味では、区議会としては取り上げる必要はないのかというふうな意見を持っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":377,"id":"exchange-104"},{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ、小芝委員にその理由を伺いたいのですけれども、先ほど、高度に政治性があるので反対だというお話があったのですけれども、高度に政治性があると、なぜ反対なのか、別に反論しているわけではなくて、ちょっと私にはわからなかったので、そこだけご説明いただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":378,"id":"exchange-105"},{"speaker":"小芝委員","kind":"意見","question":"県民投票の結果は数として出ておりますので、十分に尊重されるべきだと思います。ただし、請願の趣旨の２つ目に、対話による解決を図ることとあります。対話による解決というのが、どうしてもこれは県民投票の結果を尊重した上でということだと思うのですけれども、やはりそもそも沖縄に米軍基地があることの理由は何なのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":379,"id":"exchange-106"},{"speaker":"中塚委員","kind":"質問・要望","question":"私の意見も述べさせていただきたいと思いますけれども、いわゆる国防とか外交とか高度に政治性があるから地方公共団体は意見を言ってはならない、むしろ言うべきではないというのは、私の受けとめでは、私は間違っていると考えています。その役割の発揮こそ求められていると思うし、沖縄はそれを今、体現しようとしているわけだし、国はこれを否定しようとしているわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":380,"id":"exchange-107"},{"speaker":"中塚委員","kind":"意見","question":"先ほど、須貝委員から議論を深めるという意味で継続にしたいという気持ちもわからなくもないわけですが、今現在、基地建設の工事が強行されているときだからこそ、今日、結論を出したいということが１つです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":386,"id":"exchange-108"},{"speaker":"須貝委員","kind":"意見","question":"先ほども申し上げましたように、以前、議運で出されたときは県民投票はありませんでした。ただ、では、我々、一区議会議員がそれに対して物を申す、こうだああだということはどうなのかというのは、やっぱりあまりにも重いので、自分自身、先ほども申し上げましたけれども、今は、はっきり言って、迷っているというのが事実です。今の段階では申し上げます、継続にしてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":387,"id":"exchange-109"},{"speaker":"田中委員","kind":"意見","question":"本日、結論を出すで、採択を主張したいと思います。それぞれご意見を本当にありがとうございました。皆さんから出ていた意見がきちんともっと議論する必要性があるということでしたら、やっぱり対話による解決を図ることというこの請願は、本当に採択をすべきだと思いますし、皆さんにぜひご協力いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":388,"id":"exchange-110"},{"speaker":"西本委員","kind":"意見","question":"私は、沖縄県民投票という意味合い、そうであるならば、１００％の近いところまで意見としてそういうことであれば、これも住民投票の結果なのだろうなという思いはありますけれども、ただ、賛成者もいる、反対者もいる、いろいろな方々がいらっしゃるのだなということも受けますと、やはりそこまで私たち品川区の区議会が責任を持った形で意見書をというところまでいくのは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":389,"id":"exchange-111"},{"speaker":"中塚委員","kind":"質問","question":"そこで、今働いている方や、その職種について、会計年度任用職員になることによって、待遇が悪くなったりすることがあるのか、何か不利益になることがあるのか、今、２３区でいろいろ調整中というところはありますが、その点を伺いたいと思います。","respondent":"黒田人事課長","answer":"品川区におきましては、現在も非常勤職員の方に働いていただきまして、各所管での事業運営を担っていただいておりますので、施行日が来たからといって、大きく変わるということはなかなか難しいのかなという意味では、現在の任用状況を鑑みながら。","voiceIndex":398,"id":"exchange-112"},{"speaker":"中塚委員","kind":"質問","question":"新しい制度になりますと、毎年公募試験をするようにと総務省が考えているようですが、品川区は毎年公募試験を行うのか伺いたいと思います。試用期間は今までなかったと伺っておりますが、約１カ月の試用期間を設けるとの新たな仕組みですが、それがなぜなのか理由を伺いたいとおります。","respondent":"黒田人事課長","answer":"毎年度公募するかというご質問ですが、現在の非常勤職員も、大体年末ぐらいに広報紙で職種と採用予定数を出して、品川区としましては、毎年度任用しているという意味では、現在と変わるところはないのかというふうに思ってあります。","voiceIndex":400,"id":"exchange-113"},{"speaker":"中塚委員","kind":"質問","question":"期末手当、つまりボーナスのこと、支給可と書いてありますが、法律上はできる規定なのです。なので、私は正規であれ、非正規であれ、ボーナスは支給すべきだと考えておりますが、品川区としては、今度の会計年度任用職員に移行するに当たって、期末手当を支給する考えがあるのか、現在の検討状況を伺いたいと思います。","respondent":"黒田人事課長","answer":"期末手当の支給につきましては、これは先ほどご説明で申し上げた２３区の任用制度の中ということで、統一交渉事項ということで、２３区統一で会計年度任用職員には期末手当を支払うというところで労使妥結をしています。","voiceIndex":402,"id":"exchange-114"},{"speaker":"小芝委員","kind":"質問","question":"来年度から会計年度任用職員は任用されるということですけれども、おおよそ年間どのくらいの予算、負担が生じるのでしょうか。","respondent":"品川財政課長","answer":"おおむねですけれども、大体３億円から４億円負担になると思います。","voiceIndex":406,"id":"exchange-115"},{"speaker":"小芝委員","kind":"意見","question":"地方財政計画に反映させるということですけれども、これは区としてそもそもそういうものが可能かどうか。請願理由の１番の制度移行に必要となる財源を地方財政計画に反映させる、それが区として可能なのかどうかということなのですが。","respondent":"品川財政課長","answer":"地方財政計画に反映させるかどうかについては、今後、いろいろとまた検討していきたいと考えています。","voiceIndex":408,"id":"exchange-116"},{"speaker":"田中委員","kind":"質問","question":"任用期間は１年で毎年の更新をする。試用期間が１カ月ありということなのですけれども、その１カ月の間は、長く非常勤として働いていた方も、そのような試験的な期間となるのかということや、お金の部分はどうなるのかというところとかも伺いたいのですけれども。","respondent":"黒田人事課長","answer":"条件付採用期間につきましては、今後の制度としまして、これは一般職、正規の公務員の１職種でありますので、条件付採用期間を設けて、その期間、良好な成績、通常に勤務していれば、通常は採用されるところですが、その期間については、ご質問にあった再度の任用においても。","voiceIndex":410,"id":"exchange-117"},{"speaker":"大倉委員","kind":"確認","question":"今までの非常勤職員から会計年度任用職員になることで、先ほどのお話だと、３億円がかかるというお話は、今の制度から会計年度任用職員になると、今までかかっていた経費がそのままかかるのか、それとも３億円というのがさらに乗ってくるということなのかの確認と、そういう意味では、雇用の処遇の改善、給与的な部分で言えば、先ほど来の話だと。","respondent":"品川財政課長、黒田人事課長","answer":"先に金額のほうですけれども、先ほど、３億円から４億円と言ったのは、現行にかかっている金額よりも３億円から４億円増額になる、こういうことです。増額になることは、委員ご指摘のとおり、期末手当が増えるというところのベース、月の月給部分が同じであれば、当然、期末手当の部分がプラスになりますので、年支出が増えるという形になりますが。","voiceIndex":412,"id":"exchange-118"},{"speaker":"西本委員","kind":"確認","question":"確認ですが、認識があまりないのかもしれません。現行の非常勤職員というのが全くなくなってということでしょうか。現在、４月１日で１,３１３人いらっしゃいますけれども、大体このぐらいの人数がいて、それがそっくりこっちの任用職員のところに移行するという形になるのか。それとあと、再任用という制度があると思うのですけれども、そことの関連性はどうなってくるのでしょうか。","respondent":"黒田人事課長","answer":"２点目の給料表を適用して決定というところにつきましては、先ほど申し上げた国のマニュアルの中で、例えば事務補助については常勤職員の初任給を上限とすることも考えられるとか、さまざま給与決定について考え方を出しておりますので、そういった中では。","voiceIndex":415,"id":"exchange-119"},{"speaker":"西本委員","kind":"質問","question":"これ、今後、仕事に対しての認識、分析、どこでどういうふうな仕事をやっていて、それが給料表に対してどこの位置にするのかというのは、本当に細かい検討をしていかないと、多分、難しくなります。そうなると、今で言う非常勤職員と正規職員との区別がどうなっていくのかみたいなところもあって、これは非常に混乱するのではないかと思うのですが、その整合性は今後どういうふうな形でやっていくのですか。","respondent":"黒田人事課長","answer":"現在、さまざまな職がありますので、これも整理していきたいと思ってありますけれども、その中で、今、責任の所在というお尋ねがございましたが、国のマニュアルの中では、会計年度任用職員の職務の内容という点については、常勤職員と異なる設定とする必要がある。","voiceIndex":417,"id":"exchange-120"},{"speaker":"中塚委員","kind":"質問・要望","question":"本日、結論を出すということと、態度としては、採択をし、意見書の提出を求めたいと思います。理由についてですが、一言、賃金を下げないとおっしゃいましたが、職の設定は区の判断でいかようにもなりますし、正規ではない人を増やす道かと思います。請願の中身もよく理解できますので、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":423,"id":"exchange-121"},{"speaker":"須貝委員","kind":"意見","question":"今回、２０１７年５月に国会で成立した案件でありまして、自治体の非正規公務員の位置づけといいますか、法的なバックがある位置づけに変わったということに関して、私はこれでよかったのかと思います。別段、働く人にとってマイナスがあるというふうには見えないので、私は今回の請願に関しては、結論を出すということで、不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":424,"id":"exchange-122"},{"speaker":"田中委員","kind":"意見","question":"本日、結論を出すで、採択を主張したいと思います。毎年、現在の非常勤職員の働き方が、制度上として不安定となるのはやはりどうかなと考えます。請願者の要旨にもあるように、非常勤職員の雇用の安定、処遇改善が自治体で実現できるように、意見書提出に採択をしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":425,"id":"exchange-123"},{"speaker":"西本委員","kind":"質問・要望","question":"本日、結論を出していただきたいです。私は、不安というよりも、位置づけが明確になり、プラス３億円から４億円かかるだろうと。期末手当も支給をする方向でということになれば、相当配慮したものになるのだろうというふうに思っています。あれをやったのに、私はこれをやったのにというようなところが出てこないように、そこはベースをつくっていただきたい。不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":426,"id":"exchange-124"},{"speaker":"中塚委員","kind":"質問・要望","question":"初めに確認したいのですけれども、今回の陳情の中身についてですが、今ご説明のあった手続でいうと、2)の要件審査の(1)の監査を実施しない場合（却下）（請求人へ通知）という対応を監査委員が行ったということでよろしいのか、陳情書はそれを認めてほしいという中身ではありますけれども、この(1)の監査を実施しない場合に当たるのか、そこをまず確認させていただきたいと思います。","respondent":"小川監査委員事務局長","answer":"今回の陳情者の方が陳情していらっしゃることの内容につきましては、監査にかかわることですので、私の口からこれに当たりますと言うのは差し控えしますけれども、先ほどご説明しましたとおり、手続については1)、2)の手続を踏みまして、(1)、(2)の順でいっているです。","voiceIndex":434,"id":"exchange-125"},{"speaker":"中塚委員","kind":"質問・要望","question":"具体的な事案については失礼いたしました。陳情に照らして伺いますけれども、法に規定していない手続、つまりは聞き取りが行われたということですが、要件審査をするに当たって、先ほども各部署に説明を求め、確認をとるとご説明がありましたが、要件審査の聞き取りについては、法に規定していない手続なのか、法に規定している手続なのか、どちらなのか伺いたいと思います。","respondent":"小川監査委員事務局長","answer":"実際に要件審査に当たりまして、監査を実施するかしないかを判断する場合、当該関係の対象部署に聞き取りを行うことは基本的に違法ではございません。そういったことは通常実施しているものです。","voiceIndex":436,"id":"exchange-126"},{"speaker":"中塚委員","kind":"質問","question":"監査をした際には見積書が出てきたということなのですけれども、この見積書というものは、つまりは非公開決定をご本人にされたのか、それとも一部非公開決定をご本人にされたのか、文書不存在という決定をされたのか、あとから出てきた、それはなぜだろうと思うのは理解できるのですけれども、その見積書の情報公開決定の理由をあわせて伺いたいと思います。","respondent":"小川監査委員事務局長","answer":"情報公開の具体的なご質問がございましたけれども、今回こちらの陳情者の具体的なお話につきましては、個々具体的にこちらのほうでお話しすることはできないというふうに考えてあります。","voiceIndex":438,"id":"exchange-127"},{"speaker":"中塚委員","kind":"質問・要望","question":"確かに個々具体的にお話しすることはできない。事実関係だけ確認したいのですけれども、情報公開請求して、ないと言われたものが、あとからあったというこの経過は事実ということなのか、そこを確認させていただきたいと思うのですけれども、いかがでしょうか。","respondent":"小川監査委員事務局長","answer":"そうしたときに、当該の対象部署についての確認をし、請求人が出した事実証明書の中では発見されなかったものが、聞き取りの中で発見されるということはあり得る話であると考えています。","voiceIndex":440,"id":"exchange-128"},{"speaker":"中塚委員","kind":"質問・要望","question":"その手続に不備はなかったのか、適正だったのかという疑問はすごく残ります。求めたものがなかったから、なかったことをもって住民監査請求をしたら、あとから出てきた。それは「えっ」と感じるのもわかります。そういう意味では、情報公開の交付に不手際がなかったのかと思いますけれども、質問してもそこの部分は先ほどご答弁いただいておりますので、不手際がなかったのかなという質問をしたいと思います。","respondent":"榎本総務部長","answer":"例えば、区全体の中でそれがあれば、あるという話になりますし、ただ、情報公開請求の場合には、それぞれの部長名で回答という形になりますので、そこの部分は十分請求者にも説明をしながら進めていく必要があると考えています。","voiceIndex":442,"id":"exchange-129"},{"speaker":"中塚委員","kind":"質問・要望","question":"一般論ですけれども、部単位で判断がある。所管課なのか経理課なのかで結果的に請求者が欲しいと思っていた情報が得られないというのは問題だと思うのです。そういう意味では、請求された方の情報公開請求についての窓口での対応はしっかりと丁寧に行っていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":444,"id":"exchange-130"},{"speaker":"田中委員","kind":"質問・要望","question":"この関係資料に示されている住民監査請求には、請求人の具体的かつ客観的な根拠を示すことが必要とあり、今回の請求人は、具体的な資料として情報公開で開示した見積書がついていない起案文書一式を客観的に示し、住民監査請求を求めているのに行われなかったことについて言われているので、先ほどの聞き取りのことは当然やるべきことで違法でもなくというのは、ちょっとどうなのかと。","respondent":"小川監査委員事務局長","answer":"先ほどもご説明いたしましたが、資料の大きな２番の手続についてをご覧いただきたいのですが、請求書の受付をした後に要件審査を行います。","voiceIndex":445,"id":"exchange-131"},{"speaker":"田中委員","kind":"意見","question":"この要件審査のところで請求人の方は具体的かつ客観的な根拠を示していますよね。でも、それでも監査委員の方が聞き取りを行ったので、監査を実施しませんということをお答えした。だから、これが監査に、行政側には聞き取りを行っていることが監査にならないのかというところを聞きたいです。","respondent":"小川監査委員事務局長","answer":"実際に監査するかしないかという判断を監査委員協議会で行っているというものです。繰り返しになりますが、要件審査を経て、実際に監査をするかしないかという判断をしているものです。具体的には、実際に監査をするかどうか判断するのは監査委員です。","voiceIndex":447,"id":"exchange-132"},{"speaker":"田中委員","kind":"質問","question":"その要件審査で監査委員が監査をしませんという判断をしたのはなぜですか。全て要件が整っていたのに監査を受けなかったその理由についてというのを聞いていいですか。監査委員がなぜ全て書類がそろっていたのに、できなかったのかということを、多分、陳情者の方はおっしゃっているのですけれども、その辺はお答えできますか。","respondent":"小川監査委員事務局長","answer":"ですので、繰り返しになりますが、請求者が主張する区の財務会計上の行為の違法性または不当性の根拠、損害発生の可能性が具体的かつ客観的に示されたものとは認められない場合には。","voiceIndex":449,"id":"exchange-133"},{"speaker":"田中委員","kind":"質問","question":"その具体的かつ客観的に示したものが資料添付であり、添付がないことが客観的な証拠となっていますよね。だから、そこの部分なのですけれども、資料添付の一式を添えて住民監査請求を提出しているけれども、その要件審査では、資料が具体的かつ客観的なものとして当たらなかったということですか。","respondent":"小川監査委員事務局長","answer":"こちらは法に定められたものでございまして、この事実証明書が添付されている場合でも、その事実証明書の中身を確認させていただいて、監査を実施することになじまないものであると判断した場合には、監査をしないです。","voiceIndex":451,"id":"exchange-134"},{"speaker":"須貝委員","kind":"質問","question":"陳情を出した方の気持ちはわかりますけれども、あくまできちんとした要件審査があるわけですから、それに対して証拠書類等が事実関係と違ったものが提出されていたから、やっぱりそれは不備があるわけですから、不備があったら、やっぱりその先に進めないわけですよね。だから、それは今回、監査委員の対応は、私は適切だったと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":453,"id":"exchange-135"},{"speaker":"田中委員","kind":"確認","question":"最後に確認です。陳情者の方が起案文書一式を添えたけれども、その文書が足りなかったので監査が行われなかったということを最後に確認させてください。そういうことでよいですか。","respondent":"小川監査委員事務局長","answer":"私のほうからは一般論でしか申し上げられませんけれども、繰り返しになりますが、事実証明書が添付されていたとしても、その事実証明書の中身を確認させていただいて、住民監査請求になじまないということであれば、実施をしないです。","voiceIndex":454,"id":"exchange-136"},{"speaker":"西本委員","kind":"質問・要望","question":"先ほど、部長のほうから話があったと思います。だけど、見積書はあると言って、そこの違いがあるわけではないですか。その上で、何をこの方は求めているかというと、説明不足だと私は思うので、そこは今後の教訓として説明をきちんとしてくださいね、誤解が生じますよということだけ、私がこの文書から行政側に申し上げたいのは、誤解のないように説明をしっかりしてくださいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":456,"id":"exchange-137"},{"speaker":"田中委員","kind":"意見","question":"先ほどから、委員の方々からもご意見があったのですけれども、この情報公開請求で開示した起案文書に不備があって、なかったはずの見積書が実はあったかもしれないという問題も本当は大きな問題だとは思うのですけれども、でも、今回の陳情者の陳情理由を読むと、そこの話ではなくて、あくまでも住民監査請求の手続の不備の問題であるので、この陳情を読む限りは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":457,"id":"exchange-138"},{"speaker":"大倉委員","kind":"意見","question":"本日、結論を出すということで、態度については不採択でお願いします。まさに今、話がありましたけれども、適正な請求書の受理が行われて要件審査が行われて、その場でしっかりとした監査委員による判断が適切に行われたと判断しますので、不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":459,"id":"exchange-139"},{"speaker":"つる副委員長","kind":"意見","question":"結論を出すで、不採択です。理由は、先ほど事務局長からご説明があったとおり、請願の要旨、理由それぞれにありますけれども、一般論でやりとりが各委員からありましたが、適正な受理、対応を監査委員のほうでもされているというふうに理解しましたので、不採択。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":461,"id":"exchange-140"},{"speaker":"中塚委員","kind":"質問・要望","question":"本日、結論を出すということと、不採択でお願いいたします。理由は、要件審査の聞き取りを含め、監査委員の対応は適切だったと思います。ただし、この問題もきっかけは情報公開による対応にやはり問題があったということだと思います。先ほども指摘をいたしましたが、情報公開の請求者の意図をしっかり汲んで、請求を受け付けるなどの対応を丁寧に進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":462,"id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"本日、結論を出すということで、不採択とします。ただ、今いろいろお話を聞いていた中で、我々もよくあるのですが、誤解が誤解を、また、きちんと説明をしていても、なかなか理解をしてもらえない。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":463,"id":"exchange-142"},{"speaker":"田中委員","kind":"質問・要望","question":"結論を出すで、生活者ネットワークとしては、この陳情を採択したいと思います。住民監査請求が適正に手続が行われるよう求めているだけの陳情であったので、反対する理由はないということと、あと、今このように議論がされたことでも、とてもよかったなと、きっと陳情された方も思うと思うので、ほんとうによかったなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":464,"id":"exchange-143"},{"speaker":"西本委員","kind":"質問・要望","question":"本日、結論を出していただきたいということで、不採択でお願いします。住民監査の仕組みもあまり知られていないのかもしれないです。誤解が誤解を生じていることもあるので、よく聞いていただいて、対応していただきますようお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":465,"id":"exchange-144"}]},{"id":"topic-12","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"前も申し上げたのですが、今、さまざまな自動車事故がある中で、やっぱり職員の方も忙しくいろいろ動いているので、今の場合もそうですが、やはりアイサイト、緊急停止できるような車に替えて、相手の方にけがをさせない、いろいろな大きな事故につながったりすると大変なので、こういう賠償金とかを払うならば、精神的にも費用的にもそういう車に乗りかえていくような対応が。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":472,"id":"exchange-145"},{"speaker":"西本委員","kind":"質問","question":"どういう状況なのかと思うのです。品川歴史館ですから、ここに車がバックしたからといって、そんなに人がいるわけでもなく、なぜ轢いてしまったのかと、非常に不思議です。何かいろいろな事情があったのかと思います。あったら教えてください。それから、福祉事務所に６７万円、この６７万円は本人にいくという形でよろしいのでしょうか。福祉事務所になぜいくのかという、この辺の流れも教えてください。","respondent":"立木経理課長","answer":"医療扶助等ですが、こちらの被害を受けた方が、横浜市のほうで生活保護を受けていらっしゃる方です。そちらのほうの生活扶助、医療扶助の補填費用ということで、横浜市のほうにお支払いをしたという形のものということになってあります。","voiceIndex":473,"id":"exchange-146"},{"speaker":"西本委員","kind":"質問","question":"横浜市のほうにこれを出すというのは、生活保護者だから、そこのある一定期間の補償という形で品川区が支出したという、そこまでしなければいけないものですか。そういう決まりだったのですか。","respondent":"立木経理課長","answer":"生活保護の受給者の方は、医療費も公費で出ておりますので、その分を品川区が損害賠償として横浜市の福祉事務所に補填したという形になります。","voiceIndex":475,"id":"exchange-147"},{"speaker":"つる副委員長","kind":"質問・要望","question":"このあたりについては、生活保護法に基づいて、個人情報、これは今、委員会資料は誰でも閲覧できる状況であったりするわけです。そういう部分については、どういう扱いになっているのか、これを確認をさせていただきたいのと、あと、恐らくこれは一時的ですけれども、収入になるというふうに理解しているのですが、その辺を確認させてください。","respondent":"立木経理課長","answer":"損害賠償金の部分に関しましては、私ども、慰謝料の部分が果たして収入として認定されるのかというところで、私、認識不足でございまして、実際、生活扶助の部分として収入として換算されるのかというのは、今、私のほうからはお答えができない状況です。","voiceIndex":477,"id":"exchange-148"},{"speaker":"つる副委員長","kind":"確認","question":"収入のところについては、本旨とあれかもしれないので、参考までに確認だったわけですが、個人情報のところで、既に傍聴者とかの閲覧資料にこの報告も出ていますね。それが既に黒塗りにされているのかどうかという確認をさせてください。ネットで見るときにも目につきますね。そのときにも、見たときに、既に黒塗りの対応なのか、その確認です。","respondent":"米田区議会事務局長","answer":"当然、区長部局のほうとの連携を図っておりまして、委員会の委員にお示しする資料については、全てを開示ということでやらせていただいておりますが、傍聴の資料およびインターネットで閲覧できる資料、要するに、一般の方々が見る資料といたしましては。","voiceIndex":479,"id":"exchange-149"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2136#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":93209,"voices":486}},{"id":"r01-20190702-6","meetingId":"r01-cm07","date":"2019年7月2日","dateIso":"2019-07-02","committee":"区民委員会","time":"午前１０時００分～午前１１時２４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特殊詐欺被害の現状と被害防止対策等","agenda":"特殊詐欺被害の現状と被害防止対策等","exchanges":[{"speaker":"くにば委員","kind":"質問・要望","question":"こちらの特殊詐欺被害についてなのですけれども、私からは主に自動通話録音機についてお伺いしたいと思います。現状ですと、総件数は８３件から５４件と、現状は減っておりますけれども、まず総件数が減ったことについての自動通話録音機の効果がどれぐらいあったと思われているのか。現在、自動通話録音機の普及活動をどのような形で取り組んでいらっしゃるか。そちらの予算についてお伺いしたい。","respondent":"黛生活安全担当課長","answer":"この効果ですが、大変申しわけございません、先ほどご説明したとおり、この自動通話録音機の効果を数値的にあらわすのが大変厳しいところでございまして、ただ、この自動通話録音機を設置したお宅は品川区内では１軒も被害に遭っていないという状況もありますので。","voiceIndex":5,"id":"exchange-001"},{"speaker":"くにば委員","kind":"意見","question":"もう一つですけれども、２３区でも同じように、ほとんどが取り組まれているということで、実際の自動通話録音機の効果は十分に体感しているところだと思うので、都に対しての何かしら報告を強く上げていくことも含めて、取り組みの強化を都に何かしら上げていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"松澤委員","kind":"質問","question":"なぜかというと、私も町会の理事会などに出ると、ご婦人方はそういう話が好きなので、「この電話はだめよ」という話の周知はすごいのです。その人に訴えかけるのはなかなか難しいではないですか。そういった取り組みは民生委員がやっているのか、難しい質問ですけれども、済みません、どういう取り組みを品川区で考えられているのか、少し疑問に思います。","respondent":"黛生活安全担当課長","answer":"「おじいちゃん、大丈夫ですか。こんな手口が今はやっているんですよ」などということで、直接話しかけるということを、今、実施しています。","voiceIndex":8,"id":"exchange-003"},{"speaker":"松澤委員","kind":"質問","question":"青色防犯パトロール隊の人数は大体どれぐらいですか。","respondent":"黛生活安全担当課長","answer":"このうち２名につきましては、受付のところで生活安全相談も担当している女性になりますが、隊員としては２０名、そして青色防犯パトロールカーにつきましては５台の体制で現在取り組みをしています。","voiceIndex":10,"id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"今、電話による詐欺の被害ということだったのですけれども、この中には、はがきによる請求の被害は入っていないのですか。","respondent":"黛生活安全担当課長","answer":"はがきによる被害もこの中に含まれているとお考えいただければと思います。ただ、申しわけございません、内訳がどうなっているかにつきましては、警視庁から情報がないものでございまして、少なくとも今、委員ご指摘のように、はがきによる被害もこの中に含まれてあります。","voiceIndex":12,"id":"exchange-005"},{"speaker":"おくの委員","kind":"質問","question":"私のささやかな経験では、こういうはがきが来たことをそれなりに伺ったり、議員になる前の話ですけれども、これはどうしたらいいのかという話が直接に何件かあったので、お伺いしておきたいのですけれども、現在は電話によるものが圧倒的で、はがきによるものはそれほどではなくなってきていると思っておいてよいのでしょうか。","respondent":"黛生活安全担当課長","answer":"被害につきましては、今、委員ご指摘のとおり、電話によるもののほうが非常に多いとお考えいただいて結構かと存じます。ただ、この中に、今ご指摘のありましたはがきによる被害もありまして、この手口も相変わらず続いているところです。","voiceIndex":14,"id":"exchange-006"},{"speaker":"藤原委員","kind":"質問・要望","question":"それについてはどう思いますかということと、あとは品川区高齢者クラブ連合会等でこういうふうにイベントでやっているのであれば、品川区高齢者クラブ連合会は連合体ですから個々のクラブがあるわけですよね、その委員を活用していただいて、そこからこういうものがあるという形で末端まで流していただくようにしていただいたり、あと町会の活用もしていただくとか。","respondent":"黛生活安全担当課長","answer":"今、電話に出ない対策をとるという物理的な面の切り札としても警視庁は考えているところですので、ぜひこれについては、東京都、あるいは区の財政当局、その他関係団体とも協議をいたしまして、１件でも多く区民の皆様方に届くように努めてまいりたいと考えているところです。","voiceIndex":16,"id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"「え？あの方が？」と思う方が「品川区」と言ったからと。もちろんすぐそれを伺ったときに、前任の生活安全担当課長には内容をお届けはしましたけれども、５０万円は今でも戻ってきていないと思うのですけれども、やはり「品川区の職員」を騙られてしまうと、信用、信頼がありますから、その辺の対策、品川区の職員としてはどういうふうに思いますか。","respondent":"黛生活安全担当課長","answer":"引き続き皆様方からのさまざまな意見を聞きながら、もし効果的で新しい取り組み等のアイデアがあるのであれば、それを積極的に取り入れて研究・調査を進めていきたいと考えているところです。","voiceIndex":18,"id":"exchange-008"},{"speaker":"湯澤委員","kind":"意見","question":"自動通話録音機についてですけれども、私もご高齢の方の家に電話をするときなどは、非常に生活安全担当課長と同じようにドキッとするというか、きちんと話さなければいけないというふうになるところもあったりするのですけれども、その貸し出しに関してもたくさんのニーズがあるのではないかとは思うのですけれども、その方たち全員に行くのは、今の予算や貸し出し台数で難しいとは思いますが、今。","respondent":"黛生活安全担当課長","answer":"そうした意味からいいますと、ニーズについては大きいものがあると認識しています。参考ですが、平成２８年度に４００台、平成２９年度につきましては５００台、平成３０年度は１,０００台、平成３１年度につきましては１,５００台を準備させていただいて対応しています。","voiceIndex":20,"id":"exchange-009"},{"speaker":"湯澤委員","kind":"意見","question":"ぜひ貸し出しを希望される方全て、予算の都合もたくさんあるとは思うのですけれども、貸し出してほしい、それによってこういう特殊詐欺被害に遭いたくないという方にはぜひ貸し出せるぐらいの台数、予算をつけていきたいと思っておるので、その辺もよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-010"},{"speaker":"こんの委員","kind":"質問","question":"今、ほかの委員からの質問を聞いていて、そもそも被害状況の分析というところでお聞きしたいのですけれども、平成３０年度から今に至っては２９件減ったというところで、まず、この減少の要因。被害状況をまず押さえた上でこういう対策に当たらなければいけないと思うのですが、そこら辺はどのようにつかんでいるのかをまずお聞きしたいと思います。","respondent":"黛生活安全担当課長","answer":"これを受けまして、警察・行政が自動通話録音機の設置を含めて対策に力を注いだことが一つ大きな要因であろうと認識しております。続きまして、大規模な詐欺グループの検挙がございました。","voiceIndex":23,"id":"exchange-011"},{"speaker":"こんの委員","kind":"質問・要望","question":"わかりました。ですが、被害状況の分析をした上で効果的に動くことが大事かと思ったので、今、状況をお聞きいたしました。どちら側だけということではないですが、それによって手の打ち方とか対策は大事だと思ったときに、この生活安全サポート隊の人たちと警視庁との連携の情報をいただける範囲、また、こちらからどれだけ情報をいただける連携がとれるものなのか、どういった連携状況なのでしょうか。","respondent":"黛生活安全担当課長","answer":"しかしながら、区民を守るという意味においては警察・行政が連携していかなければいけないというところは大変重要だと認識しておりますので、可能な限り必要な情報を入手し、手を打っていかなければいけないと考えているところです。","voiceIndex":25,"id":"exchange-012"},{"speaker":"こんの委員","kind":"質問","question":"状況がよくわかりました。そうすると、情報共有、情報提供を双方向でできるということで、よくわかりました。もう一つ、そこを踏み込ませていただくと、生活安全担当課長は警視庁から派遣されてこられている方なので、そこら辺の状況、黛生活安全担当課長がどこまで警視庁との連携を直接とれるものなのですか。","respondent":"黛生活安全担当課長","answer":"大変難しい質問ではありますが、課の例えば生活安全担当課となりますと、トップの生活安全担当課長とは直接電話で話ができるところですし、警視庁本部でも大変ランクの高い方からも、何かあったときは遠慮なく電話してくれということで私どもも話を伺っているところです。","voiceIndex":27,"id":"exchange-013"},{"speaker":"木村委員","kind":"質問","question":"いろいろとオレオレ詐欺だとか、また還付金詐欺ということで、これを防ぐために自動通話録音機を配備して対策する。そう考えると、今、自動通話録音機に対する犯人側の新しい手口があるのかどうか、出てきているのかどうか、あれば教えてほしいのですが。それに対して、もしそれがあれば、それはどのようにこれから対策をしていくのか、そういうことがあれば教えてください。","respondent":"黛生活安全担当課長","answer":"我々としても、これにかわる手段がどういうものになるかについては、まだはっきりしたものを想定しているわけではございませんが、当然、犯人グループがその手を打ってくるのであれば、その次の手も考えなければいけないということで、日々。","voiceIndex":31,"id":"exchange-014"},{"speaker":"木村委員","kind":"質問","question":"確かにこちらから先手を打つことは大変難しいと思いますし、ですから、それはこちらとしてはどうしても受け身になってしまうのかなというところもありますので、それがもしできるのであれば、こういう被害は本当に防ぐことができると思いますけれども、何とか先手を打てるような方法は見つからないのでしょうか。厳しいですよね。区内のタクシー業者がパトロールに協力してくれているということですかね。","respondent":"黛生活安全担当課長","answer":"この取り組みにつきましても、ほかの事業者の方々の賛同を得られるように丁寧に説明をしながら、一つでも多くの事業者の方に協力を得られるように一生懸命頑張ってまいりたいと考えております。","voiceIndex":33,"id":"exchange-015"},{"speaker":"木村委員","kind":"質問・要望","question":"本当に高齢者の皆さん、この人が独りで住んでいるから危ないということで、いろいろと町会にも協力してくれていることは確かでしょうし、同じように高齢者の人たちに対する気配りというか、そういうものを強化していくためには、これからどういうふうな指導を行政として行っていくのでしょうか。何かそういうので、今こういうことを考えているというようなことがあれば、お聞かせいただきたいと思います。","respondent":"黛生活安全担当課長","answer":"そういった意味において、現在取り組んでいることをさらに推し進めながら、地域全体で、弱者と言ったら大変失礼なのかもしれませんが、高齢者を見守るような形を何とかつくっていかなければならないのではないかと考えているところです。","voiceIndex":35,"id":"exchange-016"}]},{"id":"topic-02","title":"しながわ観光大使シナモロール×品川区３競技応援３キャラの仲良し大作戦！について","agenda":"しながわ観光大使シナモロール×品川区３競技応援３キャラの仲良し大作戦！について","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"缶バッジを提示して特典が受けられる、その特典とは何ですか。","respondent":"古巻文化観光課長","answer":"特典ですけれども、それぞれ施設によって、一応、缶バッジを見せていただきますと、３競技応援キャラグッズとか、ミニシートとか、そういったもの、さらに新しいグッズがもらえるとか、あと、しながわ歴史館につきましてはペアの招待券のプレゼントなども考えております。","voiceIndex":45,"id":"exchange-017"},{"speaker":"くにば委員","kind":"質問・要望","question":"こちらの缶バッジについてですけれども、まず１０万個という数字が、個人的な感覚としては非常に多い数字で、こちらに関して何かしら１０万個と設定したデータであるとか根拠があるのかどうか、そちらをまずお伺いしたいのが１点。もっと１０万個を配るために、そういった横つながりで何かしら区外でも配るという施策を何か考えているのであればお教えいただきたい。","respondent":"古巻文化観光課長","answer":"キャンペーンの内容については、お配りする際に一緒に小さいメモのような紙をつけることでキャンペーン内容の周知、当然、しながわ歴史館でありますとか区内の施設でのイベントについても記載しますし、また、ホームページへの誘導等。","voiceIndex":48,"id":"exchange-018"},{"speaker":"藤原委員","kind":"確認","question":"１０万個だから、１０万人の方に配布されるのかなと思っていたのですけれども、そうではないわけですね。そうすると、きのうも報告があったけれども、品川区の人口はゼロ歳児から高齢者の方まで４０万人、今いらっしゃるわけで、４人に１人が缶バッジを持つのかなと思ったら、そうではないということの確認と、あと、シナモロールは人だったのですね。単位が「４人」だから。人だったのですね。その確認です。","respondent":"古巻文化観光課長","answer":"犬ですが、サンリオの意向といたしまして、擬人的なというか人的なイメージのキャラクター設定がありますので、なるべく「人」ということを単位として使ってほしいという意向があるようなので、３キャラが「人」かどうかはまた議論はありますけれども。","voiceIndex":50,"id":"exchange-019"},{"speaker":"湯澤委員","kind":"提案","question":"１０万個を配って、それでつけてくだされば本当にいいと思うのですけれども、一時つけて、それで次のバッジが手に入ったとか、もっと好きなキャラクターがいるというのでまたつけかえてしまうとなると、結局、それをつくっても、オリンピック・パラリンピックまでつけているかどうかということにもなってしまうと思いますので、ご提案なのですけれども。","respondent":"古巻文化観光課長","answer":"その段階でしながわ観光大使をお願いしているというところがありますので、文化観光課としてはしっかり観光大使ということでの面のＰＲもしていきたいと思いますし、また、ご提案いただいたところにつきましても。","voiceIndex":52,"id":"exchange-020"},{"speaker":"こんの委員","kind":"質問・要望","question":"この説明の専用のページを開設していくということで、今、「わくわくしながわタウン」が既にあって、そこを拡充・更新をしていくという専用ページになるのか、それとも新たにつくろうとされているものなのか、競技のルールや「あるあるネタ」というところが書かれているのですけれども、どのような「あるあるネタ」なのか、今の段階でどのようなことを考えていらっしゃるのか。","respondent":"古巻文化観光課長","answer":"「あるあるネタ」等についてですけれども、ルールとか、どの業界もそうなのですけれども、競技に対して親しみを持っていただけるような形で、具体的に今、申し上げるのがなかなか難しいですけれども、例えばホッケー競技に対していろいろな情報等があると思うので。","voiceIndex":54,"id":"exchange-021"},{"speaker":"こんの委員","kind":"質問・要望","question":"この缶バッジの配布方法ですけれども、大手のコンビニエンスストアが協力してくださるというお話があったのですけれども、それと同時に、若年層と子育て世代に広くきちんと行き渡るという方法を考えられたほうがいいかなと思うと、一つは区立保育園、それから幼稚園、学校の配布物としてきちんと配布されるほうがいいかなとも考えられるのですけれども、その辺はいかがでしょうか。","respondent":"古巻文化観光課長","answer":"缶バッジの配布につきまして、確かになるべく１人の方が２０個も３０個も持っているというような状況は避けたいというのは区の思いでもありますので、なるべくたくさんの方に届くようにということで。","voiceIndex":56,"id":"exchange-022"},{"speaker":"こんの委員","kind":"質問","question":"女子のさくらジャパン、男性はサムライジャパンですか、決定されつつあるかと思うのですが、その決定されている日本のチームを品川区としてどこまで紹介できるのか。組織委員会なのか、そうした団体しかできないものなのか、品川区としてはどこまで発信できるものなのか、活用できるものでしたら、そうしたものも活用されてはどうですかと思うのですけれども、いかがでしょうか。","respondent":"古巻文化観光課長","answer":"今、お話いただいた点ですが、例えば代表選手の紹介というか、プロフィールとか、そういったものについては、そのまま勝手にというわけにはいかないと思いますので、それは組織委員会とも協議をした上で。","voiceIndex":58,"id":"exchange-023"},{"speaker":"こんの委員","kind":"質問・要望","question":"パラリンピックについてのブラインドサッカーは品川区ではできなくなって、応援という形ですけれども、その点についてはどういうふうに発信を、機運醸成をやろうとされますか。非常に大事で、ここ、観戦はしたいのですけれども、実は２学期が始まって以降の時期が観戦の時期かと思うと、どれだけそこを機運醸成できるかは一つの課題だと思うのですけれども、その点はいかがでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"しかしながら、９月に入ってしまいますけれども、試合時間は夜もありますし、日中もありますので、こちらはぜひこれからも区民の方にどんどんＰＲをしていって、チケットは、パラリンピックはこれからですので、たくさんの方にお申し込みをいただきたいと思っているところです。","voiceIndex":60,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2840#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":26460,"voices":71}},{"id":"r01-20190702-7","meetingId":"r01-cm07","date":"2019年7月2日","dateIso":"2019-07-02","committee":"厚生委員会","time":"午前１０時００分～午後 ０時０４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成３０年度品川区介護保険制度の運営状況","agenda":"平成３０年度品川区介護保険制度の運営状況","exchanges":[{"speaker":"石田（ち）副委員長","kind":"質問","question":"３ページの、先ほどご説明いただいた特定施設と特養ホームについて伺いたいのですけれども、先ほど、住所地特例でこの特定施設と特養ホーム等は、他区・他県の施設を使っていても人数がここで、給付費は品川のほうで払っているということで、区内を利用されている方、特定施設と特別養護老人ホームの区分で区内利用者数を聞きたいです。","respondent":"寺嶋高齢者福祉課長","answer":"特定施設のほうは、なかなかこれは状況の把握が難しいのですが、この資料をつくった時点での品川区内にある特定施設が１２施設と先ほど申し上げましたけれども、７４３定員だったのですが、これも月平均なので１人単位までは出ないのですけれども、約半数。","voiceIndex":7,"id":"exchange-001"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"今、特養ホームを区外で利用されている方が、２２０人ほどいるということになるのです。それと、林試の森の地域密着型は、２９人が入っているということなので、私たちはもう少し定員増できないかということもお願いしているのですけれども、林試の森の地域密着型の福祉施設は変更なしでそのまま行く計画なのかということを伺いたいのです。","respondent":"大串福祉計画課長","answer":"林試の森の活用ということで、福祉施設をいろいろ今考えているところです。今現在、地域のほうへの説明等々も行わせていただいておりますけれども、現在、我々品川区としてはあくまで地域密着型の高齢者施設というふうに考えております。","voiceIndex":9,"id":"exchange-002"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"何か変更があったのかということを伺いたいのと、あとは、先ほどの説明の中で、この総合事業の事業項目、私も前回の平成２９年度の運営状況を見たときに、名前や事業の数が違うのでなぜかと思ったら、今説明の中でわかりやすくというようなこともありましたけれども、こうした事業は１７事業あったのが、今回の平成３０年度は１６になっているのですけれども。","respondent":"宮尾高齢者地域支援課長","answer":"有償ボランティアさんが主体となって、体操・レクリエーション活動を行う、これで日常生活に必要な機能訓練を行うというものでして、こちらを平成３０年度は大井三丁目のゆうゆうプラザ、平塚橋、それと、大崎で実施させていただいたところです。","voiceIndex":11,"id":"exchange-003"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"総合事業の中に(1)と(2)がありますが、その(1)の2)のほう、介護予防・生活支援サービスの通所型のほうに、ゆうゆうプラザのミニデイが入っているということですね。","respondent":"宮尾高齢者地域支援課長","answer":"今回、たまたま外出習慣化事業が一般会計に移行はいたしましたが、これは昨年度と内容を変更することもありませんし、参加費等も、だからといって余分にいただくなどということもありません。","voiceIndex":13,"id":"exchange-004"},{"speaker":"あべ委員","kind":"質問","question":"非常にたくさんの要素がある資料ですので、聞きたいことがたくさんあるのですけれども、その中でも特に認定率です。品川区、１８.６％。これは収入とともに、２ページでしょうか。１８.６％ということですけれども、認定率の全国平均というのは今どのくらいなのでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"参考までに、品川区自体は、２３区の中では軽いほうからという言い方はおかしいのですけれども、４番目から５番目ぐらいで推移しているというふうに把握しています。","voiceIndex":16,"id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"これが変わってきます。もちろん、希望するサービスがそれぞれにどんどん行っていればいいのですけれども、やはり、できるだけ限られたお金を有効に使えるようなサービスの設定、バランスというのもあると思うのですが、そこは品川区としては今後どのような形で、制度も変わりますけれども、どういうものに力を入れていくというようなことはお考えですか。","respondent":"寺嶋高齢者福祉課長","answer":"その辺も全て管理をすると、やはり品川区の介護の方針は一貫して住みなれた我が家で暮らすということがありますので、可能な限り在宅でのサービスを支援して、必要なときに特養、施設等々というところはつなげていきたいので、今の段階では。","voiceIndex":20,"id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"この話を始めると終わらなくなってしまうので、一旦ここでおしまいにしたいと思います。個別の課題が出てくれば、またそのときにいろいろ伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-007"}]},{"id":"topic-02","title":"品川区立東品川高齢者多世代交流支援施設指定管理者候補者の公募","agenda":"品川区立東品川高齢者多世代交流支援施設指定管理者候補者の公募","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"昨日の繰り返しになりますので、念のためということです。品川区の指定管理者、どうも最低賃金でしかお給料を払いませんよというようなところが、結構、業態によってはある、業種によってはあるようなのですけれども、こちら、特に福祉系のところで人材を積み上げていくためには、やはりそうしたことにもしっかり品川区として目配りをしながら事業者を選んでいただきたいと考えています。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-008"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"３．指定管理者が行う業務の中の(2)高齢者多世代交流支援事業の運営というところに、この間、ほかにもゆうゆうプラザがありますけれども、この中身、事業の運営のこの事業はどういうものがあるのか伺いたいのと、あとは選定委員会のメンバーを教えてください。","respondent":"宮尾高齢者地域支援課長","answer":"選考委員会のメンバーにつきましては、詳細はこれから検討していきたいと思っているのですが、基本的には福祉部およびほかの部の管理職を中心に人選を進めていきたいというふうに考えております。","voiceIndex":29,"id":"exchange-009"}]},{"id":"topic-03","title":"平成３０年度品川区障害福祉計画実績","agenda":"平成３０年度品川区障害福祉計画実績","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"これも、先ほどと一緒で幾らでも聞きたいことはあるのですけれども、それぞれ個別の事案で質問するとして、やはり大きく気になるのが、２ページにあります施設入所者の地域生活への移行。そうした意味で、品川区で比較的重たい方の地域生活を支えるサービスについて、現状どのように認識して、そして今後どのように考えていらっしゃるのか教えてください。","respondent":"築山障害者施策推進担当課長","answer":"重度の方の地域での生活の支援というところにつきましては、今後地域で暮らすという点について、グループホームには力を入れて整備をしてまいりたいと思っているところです。在宅支援という部分においても、併せて進めてまいりたいところです。","voiceIndex":35,"id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"やはり、目標を立てるということは、既に、困難であることはわかっていても、さらに進めていきましょうということであるので、そこはぜひ努力をしていただきたいと思います。私費でヘルパーを入れたりしてやっていてもなかなか困難というようなお声も、いろいろな状況の方から伺います。この重度訪問介護の時間数については、今後どのようなお考えでしょうか。","respondent":"松山障害者福祉課長","answer":"委員ご指摘の１日８時間の上限というのは、今年度改正をいたしまして、それは削除いたしました。重度訪問の介護の状況に合わせて、ご本人に状況を聞きながら必要な時間数をということで、上限ということの認識はありません。","voiceIndex":37,"id":"exchange-011"},{"speaker":"あべ委員","kind":"質問・要望","question":"参考までにお伺いしたいのですけれども、本年度で、お一人の方で１カ月何時間というのが今一番多い数字なのかということを教えてください。一方で、要望は非常に多いところなのですけれども、これがなぜ実績として伸びてこないのか。やはり、供給側の上限、サービス供給をする側が需要に追いついていないので、ここで頭打ちということになっているという解釈でよろしいのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"移動支援の見込みよりも実績が少ないというところについては、委員のおっしゃられたとおり、従事される方、ヘルパーの確保のほうがなかなか思うように進んでいないというところがありますので、こちらについては。","voiceIndex":39,"id":"exchange-012"},{"speaker":"あべ委員","kind":"質問","question":"重度の時間が今手持ちの数字がないということで、後で結構ですので、本年度としては何時間から何時間という数字を教えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-013"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"ですけれども、１８歳以上のほうは、この計画をつくるときにアンケートをとらなかったので、その数字が出てきていないというのと、あと、それをとったとしても把握する部署が１カ所にまとまっていないというところで把握し切れないのかと思ったので、障害者のところで把握するというのは無理なことなのかを伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"医療的ケアが必要な方の人数の把握につきましては、保健センター等と連携を図りながら、人数の把握を行っていきたいと考えています。","voiceIndex":43,"id":"exchange-014"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"この第５期品川区障害福祉計画・第１期品川区障害児福祉計画の４３ページ、〔「持ってないよ」と呼ぶ者あり〕障害福祉計画の実績なので、私たちはこの計画がどう実績に反映されているのかというのを見たのですけれども、ここの中に、平成３０年度末までに区内において、保健、医療、障害福祉、保育、教育等の関係機関等が連携を図るための協議の場を設置するという。","respondent":"松山障害者福祉課長","answer":"計画では平成３０年度末までにという計画を出させていただいたのですけれども、調整にお時間を要しましたので、本年度中に設置を考えて、今実際に調整を図っているというところです。","voiceIndex":45,"id":"exchange-015"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"これもやはり、医療的ケアに必要なといったところを協議できる場になるので、ぜひ早期にお願いしたいと思います。計画は５６ページです。平成２８年度の計画では１６６人、しかし実績では３人。差があり過ぎるというところが疑問だったのですけれども、そこはなぜなのかということと、あと、平成２９年度、平成３０年度も半減している状況なのですけれども、これはどういうことなのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-016"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"最後に、相談支援のところですけれども、今回、在宅介護支援センターと民間支援事業所を公募するというところがありますが、自立支援協議会の中でも計画にないことが突然出されてきたということで、自立支援協議会の会長などもおっしゃっていたのですけれども、やはり計画にないことを出してきたという思いで皆さん受けとめているので、計画の６ページには、ＰＤＣＡサイクルで。","respondent":"松山障害者福祉課長","answer":"１９ページの高齢化重度介護対応の中で、やはり相談支援を中心に置きながらということは、基本的に書かせていただいているところですが、例えば在宅介護支援センターや民間支援事業所を公募するということについて、そこまでの具体的な施策に関して。","voiceIndex":50,"id":"exchange-017"}]},{"id":"topic-04","title":"眼科検診の開始","agenda":"眼科検診の開始","exchanges":[{"speaker":"石田（ち）副委員長","kind":"質問","question":"後期高齢者の歯科健診は、本当に高齢になってくると口の中の健康というのが必要になってきますし、手も衰えていくという、体とも一緒ですけれども、やはり口の中は軽視されがちと言いますか、まあ大丈夫かなと思われがちで、わかりづらいため余計というところもあり、そうした健診ができたことはよかったと思っているのですが、事業内容の(5)検査項目で、口腔機能評価に咀嚼能力、舌機能。","respondent":"池田国保医療年金課長","answer":"今月もフォロー研修ということで行わせていただきまして、７月の実施に向かっているところです。","voiceIndex":60,"id":"exchange-018"},{"speaker":"石田（ち）副委員長","kind":"確認","question":"事前にアンケートも行ってもらってということですけれども、そうすると、3)のフレイル評価、要は検査項目の1)、2)、3)は、全部歯科で行うということで確認させていただければと思います。","respondent":"池田国保医療年金課長","answer":"今、ご質問されたように、歯科で歯科医の方にこちらのほうを行っていただく予定になっております。","voiceIndex":62,"id":"exchange-019"}]},{"id":"topic-05","title":"住宅宿泊事業法施行後の状況","agenda":"住宅宿泊事業法施行後の状況","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"先ほど、苦情が２件ということで、数としてはあまり多くないと思うのですけれども、これはご相談を受けるとどのような対応をされているのでしょうか。","respondent":"鈴木生活衛生課長","answer":"基本的には事業者、営業者に注意をしまして、宿泊者は日々変わりますが、その都度、受付をする時点でしっかりとその辺の注意事項を伝えるようにということと、悪質であったり、あまりにも繰り返されるようなケースがあった場合には。","voiceIndex":69,"id":"exchange-020"},{"speaker":"あべ委員","kind":"確認","question":"１点、共同住宅が３分の２ということなのですけれども、今、共同住宅、集合住宅などは規約などでこの民泊禁止としているところも結構増えてきているかと思います。そうしたことも調査の上、届出を受けるということ、そこを確認させてください。","respondent":"鈴木生活衛生課長","answer":"ご質問の共同住宅における民泊を実施することの同意ですが、基本的には、管理組合がある建物に関しては、管理組合での同意、もしくは禁止していないことの確認を、規約等の写しで提出いただいて、確認がとれてから届出を受理しております。","voiceIndex":71,"id":"exchange-021"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"２１件が廃止となっているというのは、１回行ったけれども廃止したということでいいのか、そして、その理由は何だったのかというのと、あとは、警察との連携がありますけれども、警察がかかわるような事例があったのかも教えてください。","respondent":"鈴木生活衛生課長","answer":"警察との連携の具体的な内容ですけれども、基本的には、ごみや騒音の注意をしても改善されないときに、警察官の方と一緒に行って、実際に指導を少し強くするということが具体的なところでして、違法を実際の事件として検挙したというケースは今までありません。","voiceIndex":74,"id":"exchange-022"}]},{"id":"topic-06","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"渡部委員","kind":"意見","question":"特段、どこの場所というのはないのですけれども、今、所管事務調査をお示しいただいて、地域共生社会の推進などは他の自治体において、例えば高齢者の方々と若い世代と言いましょうか、児童と言いますか、こういうものがあるかどうかわからないのですけれども、シルバーセンターと児童館が合築になっているような施設があったり、例えば特養と保育園が合築になっているような施設等があれば。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":80,"id":"exchange-023"}]},{"id":"topic-07","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"昨日申し上げたとおりなのですけれども、ヤングケアラーの存在というものが社会の中で明らかになってくる中で、品川区としてやはりその実態の調査、把握、それから対応といったことを各課と連携しながら進めていくべきではないかと考えているのですが、品川区としての現在の状況と、それから今後のお考えについて教えてください。","respondent":"大串福祉計画課長","answer":"このヤングケアラーの問題につきましては、やはり教育委員会等の連携というのが一番大きなポイントになってこようかと考えていますので、そうした意味では、各所管、分野はこういった形という対応になりますけれども、連携をより一層。","voiceIndex":86,"id":"exchange-024"},{"speaker":"あべ委員","kind":"質問・要望","question":"実態把握には確かに教育委員会の力がないとなかなか難しいところだと思うのですけれども、物事の性質から言えばむしろ福祉部局が音頭をとる、中心となりつつ、その実態把握については教育委員会、その改善・対応についてはというような形で、連携するにもどこか中心になっていくところが必要だと考えていますし、これはやはり、前身課題は介護であり、その介護を誰が担うかというところで。","respondent":"大串福祉計画課長","answer":"そういった視点も含めて、教育委員会ともまた連携しながら、どういった形が一番、要はこういったヤングケアラーというものに陥っている方へのケアと言いますか、その辺の相談、あるいは対応、これが一番大事なところになってまいりますので、教育委員会を含めて。","voiceIndex":88,"id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3538#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":37731,"voices":96}},{"id":"r01-20190702-8","meetingId":"r01-cm07","date":"2019年7月2日","dateIso":"2019-07-02","committee":"建設委員会","time":"午前１０時００分～午後 ２時２３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"「」を聴取いたします。 初めに、(1)令和元年７月区営住宅入居者募集","agenda":"「」を聴取いたします。 初めに、(1)令和元年７月区営住宅入居者募集","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"そうなりますと、まさに低廉な区営住宅の出番ということになるのですけれども、やはり今回もたった４戸ということで、倍率もかなり高いと伺っています。低廉な民間アパートの数が区内でどんどん減っているという現状について、品川区はどの程度把握されていますか。お伺いします。","respondent":"森住宅課長","answer":"一定程度、そういった、古いといいましょうか、少し年数がたったものもあるのかとは考えておりまして、そういったところをどう低所得の方につなげていくのかというのは１つの課題かと考えています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"ただ、その中で、今あったように、実際どれだけあいているのかというのは、また別問題なのですけれども、やはり、かなり困っている方といいますか、これまで受け皿になっていたような住宅がどんどんなくなっているという現状がありますので、やはりそういった実態をさらにつかんでいただいて、区営住宅の増設を含めた区として必要な対策というのを、家賃補助という手もあると思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"大沢委員","kind":"質問","question":"家賃滞納の債務保証制度の協定業者というのは、区ではどれぐらい協定を結んでいらっしゃるのですか。","respondent":"森住宅課長","answer":"今年は１社にお願いしています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"今年はということは、数社ということもあり得るということですか。","respondent":"森住宅課長","answer":"今年はというのは、今はという意味です。","voiceIndex":11,"id":"exchange-004"}]},{"id":"topic-02","title":"西品川２・３丁目地区「防災生活道路」の拡幅に関する説明会","agenda":"西品川２・３丁目地区「防災生活道路」の拡幅に関する説明会","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"３点お伺いします。改めてここに６メートルの幅の道路を整備する防災上の品川区の考えについて、具体的にお伺いしたいというのが１つです。２つ目は、密集住宅市街地整備促進事業の事業期間は、この道路拡幅に限らず、いろいろパッケージだったと思いますけれども、平成３０年度からの１０年だったと思いますけれども、１０年を過ぎると具体的にはどうなるのかを２点目に伺います。","respondent":"高梨木密整備推進課長","answer":"６メートルにする区の考え、意義というところなのですが、各地区で防災生活道路として６メートルに拡幅整備していますが、各地区共通でご説明させていただいているのが、まず緊急車両の進入路として６メートルが必要だです。","voiceIndex":17,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"ここの地域に具体的に線を引いているわけですから、一般論プラス、やはりここを、４メートルではなくて６メートルにするということを、説明できるものがないのかというか、その辺はしっかり、もしあれば教えていただきたいというのはあります。伺います。","respondent":"高梨木密整備推進課長","answer":"そういった用地をうまく使って、代替地の提供であるとか、そういった部分で可能なご協力を、区としてもご提案させていただいて、沿道の権利者の方の意向に合うような形で進めていければいいと考えているところです。","voiceIndex":19,"id":"exchange-006"},{"speaker":"安藤委員","kind":"確認","question":"消防活動困難区域の話がありましたけれども、予定地よりはどちらかというと、３丁目のほうですけれども、西側にあったと記憶しているのですが、直接、消防活動困難区域ではないところに道路があるのですけれど、ホース等の関係で、この位置でも消防活動困難区域が全て解消されるということでいいのか、それだけ確認させてください。","respondent":"高梨木密整備推進課長","answer":"今回の道路整備で全ての消防活動困難区域が解消できるというわけではないのですが、大きく道路基盤が脆弱なところを６メートルにしていくといったところで、大部分が解消できると考えているところです。","voiceIndex":21,"id":"exchange-007"},{"speaker":"吉田委員","kind":"質問","question":"ここのまちづくり、道路のことについては、先ほど何とおっしゃいましたか、この地域の協議会ですか、そこに、この事業の対象になる、道路の両側に当たるような方たちは、どれぐらい参加しておられたのか。それも教えてください。","respondent":"高梨木密整備推進課長","answer":"沿道に現在お住まいで土地を所有していらっしゃる方が１６２軒いらっしゃいます。先ほども説明の中で申し上げましたが、住んではいないのですけれども権利をお持ちの方というのが９７軒、その他２５軒を合わせまして、全部で権利者の総数としては２８４軒の方がいらっしゃいます。","voiceIndex":24,"id":"exchange-008"},{"speaker":"吉田委員","kind":"質問","question":"先ほど１６２軒と９７軒と、その他とご答弁がありました。その他というのは、どういう方たちなのでしょうか。それと、防災まちづくり協議会を公募する時点で、ここの道路の話というのは既に織り込み済みで公募されたということだと思うのですけれども、そこに参加されている方たちの具体的な反応とか、そういうことがあれば教えてください。","respondent":"高梨木密整備推進課長","answer":"それと、公募に際してどのような話だったというところなのですが、基本的に、昨年度当初から密集事業を始めるといった段階で、整備計画を地域の皆様にはまちづくりニュース等でお示しして、それで防災まちづくり協議会を募っておりますので、皆さん。","voiceIndex":26,"id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"まちづくり協議会に１０名が参加されたのはすごくよかったと思うのですけれども、ぜひ強制的になどということがないように、個々の事情に合わせた丁寧な進め方をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-010"},{"speaker":"たけうち委員","kind":"質問","question":"今回、拡幅に関する説明なのですが、密集住宅の市街地整備の網がかかっている中で、先ほどもありましたけれど、防災生活道路を整備していく計画だと思うのですけれど、今回、説明会を開かれるに当たって、例えば、ここに住んでいなくて空き家になっているとか、そういうお宅もあるかもしれませんし、もしくは建て替えをちょうど考えていて、では、６メートルにするのであれば、ちょっと狭くなってしまうので。","respondent":"高梨木密整備推進課長","answer":"ただ、例えば小さ過ぎるとか、防災広場としてなかなか難しいという土地であっても、先ほどご紹介いたしましたとおり、ＵＲによる不燃化用地のエリア買いというような事業もありますので、まずＵＲが取得して、また将来、連坦するような土地を取得して。","voiceIndex":30,"id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ教えてください。空き家でもいいのだけれども、所有者がわからない物件があるではないですか。そういうものがあったときに、どこの、誰が、それを調査して、どういうアプローチをするのでしょうか。それを役所がやるというなら、それはそれでいいのだけど、相続人を探すまでやると、結構大変じゃないですか。それだけ教えてください。","respondent":"高梨木密整備推進課長","answer":"ただ、なかなか複数いたり、あと住所はわかっているのだけれど、なかなか連絡がとれないといった形で、取り組みをしているところ全てで、所有者、権利者の方にたどり着くといったものではなく、非常に困難を極めているといったような現状です。","voiceIndex":34,"id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問","question":"例えばそういうのは多分、空き家になっているわけじゃないですか。これは、進めるには相当時間がかかるのだけれども、こういうところは早目に解消しようというのであれば、そういうところから手をつけるというのも、ＵＲがいるのであれば１つの手かと思うのだけど、費用も含めて、その辺の兼ね合いというのか、どうお考えになっていらっしゃるかだけ教えてください。","respondent":"高梨木密整備推進課長","answer":"ただ、ＵＲは各地区でやっていますので、非常に多くのノウハウを持っています。なかなか相続に関して課題のあるような土地の扱いについても、今後お互いに勉強しながら、積極的に動きがとれるような捜索方法も検討していきたいと考えます。","voiceIndex":36,"id":"exchange-013"},{"speaker":"松本委員","kind":"質問","question":"その際に、では小さ過ぎる土地をＵＲが買った後、五年とか十年とかずっと持ち続けるということはあり得ると思うのですけれど、その場合の例えば管理コストなどというのは、区のほうから何かＵＲにお金が出ていたりということはあるのでしょうか。それともＵＲで全部やってくれているということになるのでしょうか。お願いします。","respondent":"高梨木密整備推進課長","answer":"今、委員からご紹介のあったようなケースですけれども、ＵＲが土地を買う場合は、ＵＲの独自事業、区と連携して行っていますけれども、ＵＲが密集改善に資する仕組みとして用地を保有し、活用するといったことで進めてますので、仮に狭小宅地をもって。","voiceIndex":39,"id":"exchange-014"}]},{"id":"topic-03","title":"広町地区におけるまちづくりの検討状況","agenda":"広町地区におけるまちづくりの検討状況","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"昨年の夏に建設委員会でもご報告があったと思うのです。その辺のスケジュール感というものを、改めて現時点で教えてください。３つ目は、行政機能・にぎわいゾーンとありますけれども、ただいまの説明ですと、にぎわい拠点の広場をつくるから、こういう名前になっているというよりも、商業機能という話もありましたけれども、区役所と商業施設の合築ということを意味しているのか、伺いたいと思います。","respondent":"稲田都市開発課長","answer":"委員がおっしゃったとおり、まちづくり構想が現在あるのですが、平成３０年度で、その一歩踏み込んだまちづくり方針というものをつくっていこうと考えておりましたが、この広町地区もそうですが、Ｃ地区、Ｅ地区という周辺のまちづくりの動きが出てきております。","voiceIndex":45,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"スケジュールはそういった事情だったということですけれど、その後、Ｃ地区やＥ地区で新たな動きが出てきているということなのでしょうか。昨年の夏から、この辺の新たな動きは具体的にどういう感じなのかというのを１点伺わせてください。これは、連携して何を検討していくのか、その辺をお伺いしたいというのが２点目です。","respondent":"稲田都市開発課長","answer":"Ｅ地区におきましては、協議会ができて、やってきたのですが、その中でいろいろと勉強する中で、発起人会というものをつくっていこうということで、昨年度も発起人会はやってきたのですが、今、その発起人会の中の方々でいろいろと検討しながら。","voiceIndex":47,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"この庁舎に関しても、今、建物という話があったので、ボリュームがどれぐらいできるかというのは、もちろん検討に当たっては必要な情報だと思うので、それは検討していいと思うのですけれども、この建物自体を商業施設と合築ということは、改めてやめていただきたいし、そうしないと、開発に引っ張られて、本質的に庁舎自体をどうするか、区民の方々の声を聞いて、本当に愛されて。","respondent":"稲田都市開発課長","answer":"それぞれの土地、ＪＲの土地、区の土地に、それぞれの建物を建てていくというような考えで、今はやっているところです。庁舎の話は、今、行財政改革特別委員会で庁舎のあり方については検討しています。その内容につきましては、そちらで検討が進むのではないかと考えています。","voiceIndex":49,"id":"exchange-017"},{"speaker":"たけうち委員","kind":"質問","question":"この保育園、劇団四季のところを、等価交換か何かで防災センターにくっつけるイメージなのかと思うのですけれど、それを思いながら右側の５－２のほうを見ますと、行政機能・にぎわいゾーンという部分が、これが全部、区の土地なのかわからないですけれど、これが仮に区の土地だとすると、ちょっと土地が広くなっているように見えるのだけど、そうすると、何かわからないですけれどＪＲと。","respondent":"稲田都市開発課長","answer":"このように広場を設けながら、建物の大きさとか、そういうものも、検討をする中に含まれているということで、広場はぜひとも設置していきたいと考えているところです。","voiceIndex":52,"id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"思いだけ言います。そう考えるのであれば、そういう手法もどこかで１つ考えたほうがいいだろうし、そうではなくて、庁舎は庁舎のあり方があって、庁舎は例えばお金をかけてもしっかり建てていくのだとか、そういう考えがあるじゃないですか。ほかのにぎわいはどういうふうにしていくんだとか、これを併設していくんだとか。やはりそれなりのものを考えていかないと、全体の感じが出てこないではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-019"}]},{"id":"topic-04","title":"戸越公園駅周辺まちづくりビジョン基本計画編（素案）の策定","agenda":"戸越公園駅周辺まちづくりビジョン基本計画編（素案）の策定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"鉄道立体化ということなのですけれども、補助２９号線の整備とは切り離して行うべきなのではないかと思いますけれども、立体化の現在の進捗状況についてまず伺いたいと思います。東西動線を確保するという部分が、今回、１つの目玉として入っていますけれども、高架下というのは歩行者道路にするという考えなのでしょうか。伺います。","respondent":"東野まちづくり立体化担当課長","answer":"高架になるかどうかという部分につきましても、東京都であわせて検討しているものになりますので、今後、高架になるか地下になるか、その辺につきましても、あわせて東京都から公表が得られると考えています。","voiceIndex":60,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"ではないと確保できないのではないかと思ったので伺いました。それと、資料に基づいて幾つかお伺いしたいのですが、まず３ページの左に、活力の観点から見た地域生活拠点の現状と特性の、周辺動向に「今後このエリアで働く多くの人の居住地として選択されるポテンシャルを有しています」と書いてあるのですけれども、品川区というのは、人口の増加をまちづくりの目的にしているのかどうか伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"居住性の確保というものも、駅前近辺につきましては、安心安全な観点からというところでも進めていくというものが考えられますので、１つの目的にはなってくるかと思います。ポテンシャルです。","voiceIndex":62,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"やはり人口を集めたいということなのでしょうか。それと、あと７ページ下です。駅超混雑の問題ですとか、そういったこととあわせて、先ほどの建て替え問題も新たな課題で、こういう２つの課題というのを区は考えた上で、このように、ここに戸越公園のブランド力をアップし、その強みを活かして、再開発を次々と行うと、一極集中を進めるような計画を出して誘導しているのでしょうか。伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"タワーマンションの建て替えという部分ですけれども、これは、再開発計画でつくるビルの計画におきまして、将来的な建て替えについても当然、検討の上、進められているものです。","voiceIndex":64,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"そうした課題というのが指摘され始めているわけですから、しかも人口集中、一極集中、都心居住といいますけれども、私は、都心居住を今までと同じように、今まで以上にどんどん進めていく、都心への一極集中を行政みずから進めていくということが果たして正しいのかというのは、見直さなくてはいけない時期に来ていると思いますので、私は、以上のことから、この計画というのは見直すべきだと思います。","respondent":"東野まちづくり立体化担当課長","answer":"誰もが住めるというような部分におきましては、駅の近くに居住空間を設けていく、そういうものも１つ、歩いて暮らせるまちづくりに資するものではないかと考えているところです。","voiceIndex":66,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後に伺いたいのがパブリックコメントの件ですけれども、パブリックコメントのご報告があるたびに求めておりますが、説明会の開催は求めたいと思います。やはり、区の情報公開と区民参加への姿勢が疑われてしまうのではないかというやり方だと思いますので、説明会の開催というのは絶対不可欠だと思いますし、今言ったような観点からも求めたいと思うのですけれども、いかがでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"先ほども私の説明でお話しさせていただきましたが、この基本計画編の素案作成に当たりましては、地元との意見交換会を行うことを考えてあります。","voiceIndex":68,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはりそれでは不十分だと思います。立体化に向けたワーキンググループ。まちづくり全体の、何といいますか、やはり商店街ですし、公園ですから、多くの方々が利用しているわけです。ですから、ぜひワーキンググループでの説明というのは、それはそれでやっていただいて、それも必要でしょうけれども、それ以外に説明会の開催というのを強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-025"},{"speaker":"たけうち委員","kind":"質問","question":"右側のほうは歩道側が非常に広くなっているのですけれど、ここを見ると、公共施設が随分、荏原第四中学校から大崎高校と戸越体育館と連なっているわけですけれども、それで立体化されると、荏原第四中学校と大崎高校のつながりも、また別のほうから行けるのか、ちょっとわからないのですけれども、その中で、いわゆる道路の安全性とか、また、ここには歩行者の空間。","respondent":"東野まちづくり立体化担当課長","answer":"公共施設の老朽化なども、ここを取り上げているところですので、そういったところとあわせて、何かしら、そういう対策がとれないかというものを今後検討していきたいというものです。","voiceIndex":72,"id":"exchange-026"},{"speaker":"たけうち委員","kind":"質問","question":"歩行者はもちろん大事だし、今、体育館側というか、大崎高校側のほうは、歩行者のスペースはかなりあるんです。逆に、車の両側通行が非常に危ない。そういうことを考えると、歩行者のもちろん安全が大事なのですけれども、それだけではなくて、車道の空間の整備みたいなことも検討になっていないのかと思うのですけれども、そこはどうなのでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"そういったところも、この地区の課題であると認識していますので、今後こういったところの検討も進めていきたいです。まだ方針段階ですので、詳しい整備の方向性などは決まっていないのですけれども、そういうところも今後、検討していきたいと考えているところです。","voiceIndex":74,"id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"３ページです。計画を考える上で、行政がどれぐらいのサービスを提供できるかということを盛り込むべきではないのかと。もし違ったらご指摘いただきたいのです。それを先に、ビジョンなどを描くときに組み込むべきではないのでしょうかと。そのことについて、もう既に想定されていて、これは概要版ということですので、描き切れていないのだということであれば、教えていただきたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"具体的な行政施設としての検討という部分につきましては、この地域に何が入ってくるかという部分の検討ということになるわけなのですけれども、現在、ビジョンの基本計画編で考えている分につきましては、現在ある行政施設としてのポテンシャルを活かした、人々のお住まい。","voiceIndex":77,"id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ考えるべきではないのでしょうかということなのです。何かその辺が、最初から、どっちが先かはわかりませんけれども、はじめの段階で、そういうことも検討しながら描くべきなのではないでしょうかということなのです。もし何かコメントがあったらお聞かせください。それから、パブリックコメントの実施です。そこで何か資料をいただけるとか、そういうことがあるのかどうか、あわせて伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"パブリックコメントです。広報しながわと同時期、つまり８月２１日に区のホームページにも掲載を予定しています。もう少し前にということなのですけれども、やはりこれにつきましては、公表の時期というものを合わせていく必要があるのではないかと考えるところです。","voiceIndex":79,"id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"提供できる行政サービスと、まちづくりを合わせて考えてほしいと、うまく私の意図がお話しできていないのだと思います。これは要望です。今後のこともありますので、ぜひ、少しでも早くしていただきたいし、パブリックコメントをたくさん求める以上、情報はなるべく、出しやすい方向で提供していただきたいと思います。これも強く要望しておきます。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-030"},{"speaker":"高橋（伸）副委員長","kind":"質問","question":"概要版の３ページの右側の中間のところに、次世代に選ばれるまちづくりというところで、これはコンセプトとして、「Ｐａｒｋ Ｌｉｆｅ Ｓｔａｔｉｏｎ戸越公園」を掲げていますけれども、その中で、やはりここは教育環境、まさにこれから体験型の環境学習施設が整備されていく中で、戸越公園、文庫の森、さまざまな教育機関がある中で、これは関連した質問になるかと思うのですけれども。","respondent":"溝口公園課長","answer":"今回、戸越公園の関係ですので、私からお答えします。委員がご指摘のとおり、環境学習交流施設ができたり、三ツ木保育園の仮園舎の整備が予定されているところです。","voiceIndex":83,"id":"exchange-031"},{"speaker":"高橋（伸）副委員長","kind":"質問・要望","question":"ぜひ私の要望として、よろしくお願いいたします。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-032"}]},{"id":"topic-05","title":"東京都の土砂災害警戒区域等の指定予定","agenda":"東京都の土砂災害警戒区域等の指定予定","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"その説明会を実施するということですので、やはりこれも、なるべく多くの方に来ていただく必要があると思うのですけれども、この周知方法というのですか、あと、なるべく多くの方に当日参加していただきたいと思うので、そういったところでの品川区としての工夫といいますか、それがあればお伺いします。","respondent":"長尾建築課長","answer":"説明会への参加を促す工夫というところですけれども、３月に調査結果の公表を受けた後ですけれども、東京都と説明会に関して連携しながら進めるということで、今回の土砂災害警戒区域の指定箇所の４９箇所は、主に、上大崎であったり東五反田という北側のエリアと。","voiceIndex":90,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。基本的なところで、４９箇所と３７箇所の、それぞれの棟数というのですか、世帯数というのですか、それぞれ具体的には幾つぐらいなのか伺いたいと思います。名前を忘れてしまいましたけれど、そういうものに実際に登録している世帯というのですか、それはそのうちどれぐらいなのか。","respondent":"長尾建築課長","answer":"今回、指定が予定されております土砂災害警戒区域４９箇所に関係する世帯数につきましては、まだ具体的に、この崖の周辺で何世帯といったところは調査が終わっておりません。","voiceIndex":92,"id":"exchange-034"},{"speaker":"安藤委員","kind":"意見","question":"すみません。調査は終わっていないということなのですけれども、説明会のご案内をするということですので、ではどうやって、どこにご案内するのかと思ったのです。逆に言うと、説明会の通知というのはどのようにするのか。対象ですとか、その辺をお聞かせください。","respondent":"長尾建築課長","answer":"失礼いたしました。対象となる区域につきましては、東京都のほうで具体的に定められておりまして、その区域にかかっている建物に居住されている方、あと権利をお持ちの方に対して、東京都で説明会の周知については行っているところです。","voiceIndex":94,"id":"exchange-035"},{"speaker":"石田（秀）委員","kind":"質問","question":"１つは、これは土砂災害のおそれのある区域を指定するのだけど、その土砂災害というのは、基準で、わかりやすく言うと、例えば雨だったら、１時間あたり１００ミリ以上降ったのが３時間降ってしまったとか、１時間でも危ないのかとか、それから地震で言うならば、震度６になったら崩れてしまうのだとか、震度５でも多分、指定されているところがありますとか、簡単にわかるような基準があるのかどうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-036"},{"speaker":"石田（秀）委員","kind":"質問","question":"出ているんだ。では、それを見ます。それから、あと、区が対応しなくてはいけない場所というのが、もし指定されて、区が関係するところがあるのであれば、それはどこかで対応しなくてはいけないわけではないですか。それで、区は、これが指定されたら、そういう対応はどうするなど考えていらっしゃるのか。その辺のところも教えてください。","respondent":"長尾建築課長","answer":"学校や公園などがあるのですけれども、こちらは所管課と情報共有しながら、これまでの安全確認の状況であるとか、今後の対応のお話であるとかというのは、引き続き連携しながら、安全性の確保に向けて取り組んでいきたいと考えているところです。","voiceIndex":97,"id":"exchange-037"},{"speaker":"石田（秀）委員","kind":"質問","question":"これは、指定されるじゃないですか。では、そこは自主的に何かしましょう。東日本大震災のときに、簡単に言うと、品川神社の品川富士は崩れた。鳥居も倒れたけれども、そのときに、自主的に、これはまずいというので、業者も呼んで、結構、強度を増して、崩れないように大分やった。だけど指導はするよ」とか、これは、いろんな方法が出てくるではないですか。その辺はどうお考えなのですか。","respondent":"長尾建築課長","answer":"ただ、危険性があることには違いありませんので、区としても一定の対応はしていきたいと考えております。","voiceIndex":99,"id":"exchange-038"},{"speaker":"たけうち委員","kind":"質問","question":"関連するのですけれども、今、お話に出た、既に品川区で急傾斜地の危険箇所というのが５０箇所ぐらいありますよね。それで、区のほうで見て、急傾斜地のいわゆる危険なところと、今回の土砂災害警戒区域等は、大体リンクしているのか、それともそうでもなく対象が結構広がっているのか、その辺はどうなのですか。","respondent":"長尾建築課長","answer":"こちら、急傾斜地崩壊危険箇所を抽出した際の方法と、今回の土砂災害警戒区域を抽出する方法というのが、どちらも東京都がやっているのですけれども、もとにしている資料等が大分違いまして、また現地での地形の確認に対しての方法も、精密性を上げて調査をしているので。","voiceIndex":102,"id":"exchange-039"},{"speaker":"たけうち委員","kind":"質問","question":"わかりました。だけど、それもＰＲしていきながら、今回のこの部分とリンクできるのかどうか。その部分についても、指定されたならば、やはりそういう補助制度で対応していかないといけないのではないかと思うのですけれど、一応、その辺の方向性を、もしあれば教えてください。","respondent":"長尾建築課長","answer":"できる限り、崖の改修を前向きに検討していただこうとしている方に対して後押しができるよう東京都と連携しながら、建築課としても進めていけたらと考えています。","voiceIndex":104,"id":"exchange-040"},{"speaker":"大沢委員","kind":"質問","question":"課長からお話を伺って、今回指定されると。ソフト面で積極的な行政の支援策があるが、逆にハード面に対してはどのようなことが行われているのか、簡単にお答えをお願いします。","respondent":"長尾建築課長","answer":"それで、所有者の方から、やはり崖の改修であるとか現状の確認であるとか、いろんなご相談があるかと思いますので、その際には、先ほどお伝えした、急傾斜地崩壊危険区域に対しての都の崖の安全化対策というところも含めて。","voiceIndex":106,"id":"exchange-041"},{"speaker":"松本委員","kind":"質問・要望","question":"結構、これは都と区の所管のところでいろいろとありそうな感じなのですけれども、先ほど安藤委員からの質問で、たしか警戒区域にいる世帯数などという質問が出て、それはまだ東京都から情報が提供されていないというお話などがあったと思うのですが、先ほどもお話がありましたけれど、７月に入って雨が増えてきて、できるだけ情報を共有して、区としても対応していただきたいと思うのですけれども、今後。","respondent":"長尾建築課長","answer":"どこまでの情報を提供いただけるかというところは、まだ引き続き、東京都と調整していく予定としております。","voiceIndex":108,"id":"exchange-042"}]},{"id":"topic-06","title":"（仮称）品川区立環境学習交流施設運営事業者候補者の選定","agenda":"（仮称）品川区立環境学習交流施設運営事業者候補者の選定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"施設の設置の１つの大きな理由にも挙がっていたかと思うのですけれども、温暖化問題に対する関心の高まりといいますか、その取り組みといいますか、そういったことがあったかと思うのですけれども、やはり喫緊の課題ですし、解決しなければ、人類の存続が危ぶまれるという問題ですので、これは重要視したほうがいいテーマではないかと思うのですけれども、今回の施設の計画に当たっては。","respondent":"小林環境課長","answer":"もちろん、屋外で遊べるスペースとしましても、じゃぶじゃぶ池の設置とか、あるいは遊具スペースの設置、これは１階のウッドデッキのちょうど右側ですか、東側に当たるところですが、そういったエリアに設置を、今、検討しています。","voiceIndex":115,"id":"exchange-043"},{"speaker":"安藤委員","kind":"意見","question":"ぜひお子さんが楽しめるスペースというのは、さらに、従来よりも発展していくような形で工夫していただければと思います。社会や地球全体の今のそういったところに関係してくる深い大切なテーマだと思いますので、ぜひそういったところを常設的に考えられるような施設にしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":117,"id":"exchange-044"},{"speaker":"吉田委員","kind":"質問","question":"それで、運営のほうにコンセプトなどが書いてあるので、その後の運営過程で、ずっと同じものが展示されているなどということはないと思うので、その辺の運営のやり方というのでしょうか、指定管理ということで、その範囲内で自分たちで工夫しながらやっていくということは理解しているのですけれども、その辺の決め方というのでしょうか、展示内容とか、その辺を教えてください。","respondent":"小林環境課長","answer":"この方針は、今回、運営・展示・建物を担う３者の三位一体の活動によりまして、地域とともに花開く施設として、将来にわたって目指すという理念のご説明があったところでございまして、その事業者の連携の強さ。","voiceIndex":119,"id":"exchange-045"},{"speaker":"吉田委員","kind":"質問","question":"ハード部分とソフト部分のところの、すみ分けというか役割分担についてはわかりました。例えば、企画展示ゾーンや、常設展示のところについて、多少、汎用性が担保されて、いろいろなこと、更新も可能というように理解したのですけれど、それでよろしいでしょうか。それで、もう少し踏み込んであれなのですけれど、この企画展示の内容ですよね。","respondent":"小林環境課長","answer":"そこの中で、区と指定管理者との関係ではありますが、必然的に指定管理者にお願いしておしまいというわけではなくて、常日ごろから、そういうところについては定期的に会議を設けて、進行状況や企画の内容等については。","voiceIndex":121,"id":"exchange-046"},{"speaker":"吉田委員","kind":"質問","question":"もう一つ、ボランティア室がありますよね。地域交流室と括弧書きでありますけれども、この活用のイメージを教えてください。多目的スペースもあるのですけれど、多目的スペースの活用のイメージ、誰がどういうふうに活用していくことをイメージされているのか教えてください。","respondent":"小林環境課長","answer":"多目的スペースはそういったところを担う役割をまず１つ持っているのとあわせまして、この施設は、今、教育委員会とも調整を図っているところですが、社会科見学の一環とか、あるいは近くの、区内の保育園・幼稚園の方が遠足にお越しいただいて。","voiceIndex":123,"id":"exchange-047"},{"speaker":"吉田委員","kind":"提案","question":"それで、環境というのは、本当にさまざまな切り口がありますので、固定化しないで、企業とか、こういう専門的にやっていらっしゃるようなところからの提案も当然受けたほうがいいと思いますけれども、地域の方たちの関心事がここに反映されていくような、地域で一体になってつくっていけるようなものにしていっていただきたいと思います。これは要望にとどめます。以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":125,"id":"exchange-048"},{"speaker":"たけうち委員","kind":"意見","question":"１つは、屋上に行けるのかということです。それで、屋上緑化か何かをやるのかどうかということとか、あと、環境学習交流施設なので、例えば太陽光ですとか風力ですとか、いわゆる自然エネルギーを使ったものもどこかに設置するのかというところ。お願いいたします。","respondent":"小林環境課長","answer":"当然ながら、需要があれば、夜間利用も十分に考えられるかと思っているところでございまして、夜間利用も頭に入れながら、今後、運営事業者とともに検討を深めてまいりたいと考えています。","voiceIndex":127,"id":"exchange-049"},{"speaker":"石田（秀）委員","kind":"質問","question":"何点かお伺いしたいのですが、建物については、ここに書いてある薬医門との調和が図れるということなのだけれども、外観を見たとき、ここにあるのだけど、例えば環境に優しい素材、例えば木材だとか、もしあれだったら、しっくいを使うとか、それは環境学習になるじゃないですか。「しっくいというのは、こういうわけで呼吸しているよ」とか、いろんな説明ができるじゃないですか。","respondent":"小林環境課長","answer":"一定、環境学習、今、委員からご提案いただいた内容も含めて、今後しっかりと検討していきたいと思ってあります。","voiceIndex":130,"id":"exchange-050"},{"speaker":"安藤委員","kind":"確認","question":"先ほど環境情報活動センターの話があったので、少し確認なのですが、今、八潮のこみゅにてぃぷらざに入っているところは、こちらに移ってくるという感じで調整が進んでいるのかどうかというのを確認したいのと、自然エネルギーの話がありましたけれど、その施設の電力を自然エネルギーで賄うという考え方があるではないですか。","respondent":"小林環境課長","answer":"そこの中で、全てをそのエネルギーで賄うことは基本的には難しいですけれど、特に立地条件等を今後、勘案した上で、どこのレベルのＺＥＢの認証が取れるかというところについては、今後、設計を進めていく中で検討していくことと感じてあります。","voiceIndex":134,"id":"exchange-051"},{"speaker":"安藤委員","kind":"質問・要望","question":"いろいろ評価の仕方はあると思いますけれども、ぜひ、自然エネルギーで賄っていくという方向を目指して、それがだんだん主流になっていくと思うのです。ですから、ぜひそこはこだわって、できる限り推進していただきたいというのが１つです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-052"},{"speaker":"高橋（伸）副委員長","kind":"提案","question":"これから、基本設計から実施設計に入っていくと思うのですけれども、提案概要の図面をベースに進めていくということでよろしいでしょうか。そこをお聞きしたいと思います。","respondent":"小林環境課長","answer":"使い勝手につきましても、もう少しヒアリングをかけていかなければならない部分もありますので、基本、これがベースではありますけれど、細かな仕様等につきましては、今後詳細を詰めた上で、基本設計・実施設計に進んでまいりたいと考えています。","voiceIndex":138,"id":"exchange-053"},{"speaker":"高橋（伸）副委員長","kind":"質問","question":"それと、外観のイメージは、このイメージパース図なのですけれど、これは北東から見たイメージ図ですよね。それと、あと１階の平面図の中の、コミュニティラウンジについてです。収納キッチンとありますけれど、これは何か売店みたいになるのか、もしくはここで、皆さんがお弁当など持ってきて食べられるようなラウンジなのか、飲食を提供できるようなラウンジなのかどうか、お聞きしたいと思います。","respondent":"小林環境課長","answer":"今後、設計業務を進めていく中では、やはりほかの面、なかなか学校側についてはどう表現するかはあろうかと思いますが、それ以外の、公園に面した方角のパースの雰囲気などにつきましては、今後設計を進めていく中で、しっかりとつくっていくこととして。","voiceIndex":140,"id":"exchange-054"}]},{"id":"topic-07","title":"第二戸越幹線整備工事（北品川立坑）","agenda":"第二戸越幹線整備工事（北品川立坑）","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"確認なのですが、下流部のシールド工というのが令和３年８月以降になって、全体事業の完了が令和６年度ということでよろしいのかというのが１点です。もう一つは、今回の北品川の立坑完成後の作業ヤード部分というのですけれども、これは、事業後に隣接する子供の森公園用地の一部として、活用するという予定があるのでしょうか。伺いたいと思います。伺います。","respondent":"松本河川下水道課長、溝口公園課長","answer":"私からは、下流部シールドの予定ですが、今、委員からご説明がありましたように、令和３年までが、今回契約しました北品川立坑の工事となりますので、その後、下流部のシールド工事に入る予定としております。これについても、買収することができれば、公園の拡張にもつながりますので、できることなら買いたいというものでありますが、相手のあることですので、そういったところも含めて、今後しっかり。","voiceIndex":152,"id":"exchange-055"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"作業ヤードの部分で、よくお話だけしていただきたいのは、１月に１回ぐらい、ボールをまとめておいてもらって、少年野球の方にボールを返してほしいというか、結構入ってしまって、ボールがなくなってしまって結構大変なので、作業ヤードにボールが入ったら、毎回ではなくていいので、１カ月に１回ぐらい、打ち合わせをしていただいて、回収できるような体制をとっていただきたい。これはお願いです。","respondent":"溝口公園課長、松本河川下水道課長","answer":"どういう形で活用できるのか、また今後、児童相談所とか下水道工事も入ってくるところですので、そういった中で、所有者である東京都と、どういう活用ができるのか、それについては引き続き協議していきたいと考えているところです。私からはボールにつきましてお答えします。事業者にしっかりボールのことについては申し伝えまして、ボールをきちんと返せるような体制をとらせていただきたいと考えております。","voiceIndex":156,"id":"exchange-056"}]},{"id":"topic-08","title":"防災行政無線の設備更新","agenda":"防災行政無線の設備更新","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"１点確認なのですが、３２から４６は新設ということで、増やすということでよろしいのかという確認と、あと、防災無線ですが、地域によっては、かねてから「聞こえないんですよ」という声があったり、あるいは更新しデジタル化した後には、「音が大き過ぎて困るんですけど」という声もいただいたこともあるのですけれども、大変兼ね合いが難しいところではあると思いますけれども。","respondent":"中島防災課長","answer":"１点目の、１５カ所は新設かということですが、これにつきましては、これまでの調査等を含みまして、対応が必要だと考えられる場所を選定いたしまして、新たに新設するものです。","voiceIndex":163,"id":"exchange-057"},{"speaker":"たけうち委員","kind":"質問・要望","question":"裏面のほうで、戸別という記載があって、それが何かというのを教えてもらいたいのと、あと、デジタル化になったからといって、何か格段に聞こえやすくなるということではないという理解でいるのですけれども、そこを教えていただきたい。","respondent":"中島防災課長","answer":"やはり一定程度、高層ビル等々の遮蔽により聞こえないということもありますので、そのあたりは今後、個別の調整などで別途対応してまいりたいと思います。","voiceIndex":166,"id":"exchange-058"},{"speaker":"たけうち委員","kind":"提案","question":"わかりました。そうすると、令和２年以降の計画で、新設の予定があるのか、それともそれはないのかということです。それから、ちょっと今回、うちの会派から一般質問で、デジタル化に合わせて、なかなか聞こえない場合の電光掲示板的なデジタルサイネージといったものもご提案させていただいたのですけれども、今後、その辺は、この間、答弁いただいたばかりですけれども、何かあれば教えてください。","respondent":"中島防災課長","answer":"デジタル化にあわせたデジタルサイネージ等での情報発信についてですが、一般質問の答弁と重複いたしますが、今年度の事業です災害時の情報収集・情報発信の検討の中で具体的に考えてまいりたいと思います。","voiceIndex":168,"id":"exchange-059"}]},{"id":"topic-09","title":"避難勧告等に関するガイドラインの改定","agenda":"避難勧告等に関するガイドラインの改定","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"確認なのですが、警戒レベルは国から発せられて、それに合わせて自治体が発令するというものなのか、区独自の判断ができるのかを確認させてください。","respondent":"中島防災課長","answer":"したがいまして、あくまで判断は区が、避難指示、避難勧告を出します。それに警戒レベルをつけて、区が発令するというものです。","voiceIndex":174,"id":"exchange-060"}]},{"id":"topic-10","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"たけうち委員","kind":"提案","question":"あと、今、国土交通省でやっている空き家ですとか、そうした遊休不動産等を活用したリノベーションまちづくりということで、コミュニティーの再生とか産業振興、雇用促進等で、各地で展開している事業なので、いろんな都市で、和歌山市とか北九州市とか、山梨市などもそうですけれど、そうした事業もいいかと思い提案いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":180,"id":"exchange-061"},{"speaker":"大沢委員","kind":"質問・要望","question":"さかのぼると、平成２５年に私ども建設委員会でありましたけれど、このときも台風で中止になったという経緯がありますので、兵庫県神戸市の人と防災未来センターについては、ぜひとも見学というか視察させていただきたい。今度は３度目の正直で、ぜひともここは一回、視察をさせていただきたいと思っていますので、ご斟酌のほう、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":182,"id":"exchange-062"},{"speaker":"安藤委員","kind":"意見","question":"羽田新ルートの問題は、やはりこの１年間が、かなり大事な年になってきますので、首都圏空港機能強化ということもうたわれていますので、成田のほうなどで実際にどのような現状が起きているのかということですとか、あるいは伊丹空港のある豊中市といったところを、建設委員会としても研究していくといいますか、視察していくことはいいことではないかというのが１点です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":184,"id":"exchange-063"},{"speaker":"石田（秀）委員","kind":"意見","question":"なぜかといったら、京都市の場合は、多分、皆さんのほうがご存じだけど、京都市は、土地を京都市が貸して、建物から運営から全部、オリックスがやっていて、その回収費用も何も全部やっていて、もし利益が出れば、その分については市に入るみたいな話でやっているので、そういう運営の仕方も１つの方法だと思っているので、京都水族館はいいかもしれない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":186,"id":"exchange-064"},{"speaker":"吉田委員","kind":"意見","question":"レジ袋禁止条例だったか、それをこの間、制定したと思うのですけれど。それで、その前段として、川の名前を忘れました、清掃活動とか、アプリを使っていろんな人が参加しやすいような、ごみを減らすような活動も、市民と行政が協働して行っているということがあるので、所管事務調査には取り上げられませんでしたが、もし視察先として、所管にかかわることですので、行きたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":188,"id":"exchange-065"},{"speaker":"大沢委員","kind":"質問","question":"ご参考の意見を伺いまして、自民党の石田秀男委員にお願いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":200,"id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4264#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":63416,"voices":204}}]);
